window.HB_TR["2-chronicles"]["ur"]=["1۔ اور سلیمان، داؤد کا بیٹا، اپنی بادشاہی میں مضبوط ہوا، اور خداوند اس کا خدا اس کے ساتھ تھا، اور اس نے اسے بے حد بڑھا دیا۔\n2۔ پھر سلیمان نے پورے اسرائیل، ہزاروں اور سینکڑوں کے کپتانوں، اور ججوں سے، اور پورے اسرائیل کے ہر حکمران سے، جو بزرگوں کا سردار تھا، سے بات کی۔\n3۔ یوں سلیمان اور اس کے ساتھ موجود تمام جماعت اس بلند مقام پر چلے گئے جو گبعون میں تھا؛ کیونکہ وہاں خدا کی جماعت کا خیمہ تھا، جو موسیٰ، خداوند کے بندے نے بیابان میں بنایا تھا۔\n4۔ لیکن خدا کا صندوق داؤد نے کیرجاتجیاریم سے اس جگہ پر لایا تھا جہاں داؤد نے اس کے لیے تیار کیا تھا: کیونکہ اس نے یروشلم میں اس کے لیے خیمہ لگایا تھا۔\n5۔ مزید برآں، وہ براسن قربان گاہ، جو بیزلیل، یوری کے بیٹے، حور کے بیٹے نے بنایا تھا، اس نے خداوند کے خیمے کے سامنے رکھا: اور سلیمان اور جماعت نے اس کی طرف رجوع کیا۔ {اس نے کہا: یا، کیا تھا}\n6۔ اور سلیمان وہاں خدا کے سامنے براسن قربان گاہ پر چلا گیا، جو جماعت کے خیمہ میں تھا، اور اس پر ہزاروں جلانے کی قربانیاں پیش کیں۔\n7۔ اس رات خدا سلیمان پر ظاہر ہوا اور اس سے کہا، پوچھو میں تمہیں کیا دوں گا۔\n8۔ اور سلیمان نے خدا سے کہا، تو نے میرے باپ داؤد پر بہت رحم کیا ہے، اور مجھے اس کی جگہ بادشاہت دی ہے۔\n9۔ اب، اے خداوند خدا، اپنے باپ داؤد سے کیا گیا وعدہ پورا ہو جائے: کیونکہ تو نے مجھے ایک قوم پر بادشاہ بنایا ہے جیسے زمین کی مٹی کثرت ہو۔ {جیسے...: عبرانی۔ بالکل زمین کی گرد کی طرح}\n10۔ اب مجھے حکمت اور علم دو، تاکہ میں باہر جا کر اس قوم کے سامنے آ سکوں: کیونکہ کون اس تیری قوم کا فیصلہ کر سکتا ہے، {جو اتنی عظیم ہے؟'\n11۔ اور خدا نے سلیمان سے کہا، کیونکہ یہ تمہارے دل میں ہے، اور تم نے دولت، دولت، عزت، یا اپنے دشمنوں کی جان نہیں مانگی، اور نہ ہی لمبی عمر مانگی؛ بلکہ تم نے اپنے لیے حکمت اور علم مانگا ہے، تاکہ تم میرے لوگوں کا فیصلہ کر سکو، جن پر میں نے تمہیں بادشاہ بنایا ہے:\n12۔ حکمت اور علم {تمہیں} عطا کیا گیا ہے؛ اور میں تمہیں دولت، دولت اور عزت دوں گا، جو تم سے پہلے کسی بادشاہ کو نہیں ملا، اور نہ ہی تمہارے بعد کسی کو ایسا ملے گا۔\n13۔ پھر سلیمان {اپنے سفر سے} اس بلند مقام پر پہنچا جو {تھا} گبعون میں یروشلم پہنچا، جماعت کے خیمہ کے سامنے سے، اور اسرائیل پر حکمرانی کی۔\n14۔ اور سلیمان نے رتھ اور گھڑ سوار جمع کیے، اور اس کے پاس ایک ہزار چار سو رتھ اور بارہ ہزار سوار تھے، جنہیں اس نے رتھوں کے شہروں اور بادشاہ کے ساتھ یروشلم میں رکھا۔\n15۔ اور بادشاہ نے یروشلم میں چاندی اور سونا {اتنے کثرت سے} بنائے جتنے پتھر، اور دیودار کے درختوں نے وادی میں فراوانی کے لیے چاپلوسی کے درختوں کی طرح بنایا۔ {بنایا: عبرانی۔ دیا گیا}\n16۔ اور سلیمان نے مصر سے گھوڑے اور لینن کا دھاگہ لانا منوایا: بادشاہ کے تاجروں کو کپڑے کا دھاگہ قیمت پر ملا۔ {سلیمان...: عبرانی۔ گھوڑوں کی روانگی جو سلیمان کا تھا}\n17۔ اور انہوں نے مصر سے چھ سو چاندی کے لیے ایک رتھ اور ایک گھوڑا ایک سو پچاس کے لیے نکالا۔ اور یوں انہوں نے تمام حتیوں کے بادشاہوں اور شام کے بادشاہوں کے لیے اپنے وسائل سے گھوڑے نکالے۔ {مطلب: عبوری۔ ہاتھ}","1۔ اور سلیمان نے خدا کے نام کے لیے ایک گھر اور اس کی بادشاہت کے لیے گھر بنانے کا عزم کیا۔\n2۔ اور سلیمان نے تین سو دس ہزار آدمیوں کو بوجھ اٹھانے کو کہا، اور چولیس ہزار کو پہاڑ میں کاٹنے کے لیے، اور تین ہزار چھ سو کو ان کی نگرانی کرنے کو کہا۔\n3۔ اور سلیمان نے صور کے بادشاہ حورام کو بھیجا، کہا، جیسے تم نے میرے باپ کے ساتھ داؤد کے ساتھ سلوک کیا، اور اسے دیودار کے درخت بھیجے تاکہ وہ اس کے لیے ایک گھر بنا سکے جہاں وہ رہے، {میرے ساتھ بھی ایسا ہی سلوک کرو}۔ {ہورام: یا، ہیرم}\n4۔ دیکھو، میں خداوند میرے خدا کے نام پر ایک گھر بناتا ہوں، تاکہ اسے وقف کروں، اور اس کے سامنے میٹھا لوبان جلاؤں، اور مسلسل روٹی دکھانے کے لیے، اور صبح و شام، سبت کے دن، نئے چاندوں پر، اور خداوند ہمارے خدا کے باوقار تہواروں کے لیے۔ یہ {ایک فرمان ہے} ہمیشہ کے لیے اسرائیل کے لیے۔ {میٹھا...: عبرانی۔ مصالحوں کی خوشبو}\n5۔ اور جو گھر میں بناتا ہوں {عظیم} ہے: کیونکہ عظیم {ہے} ہمارا خدا تمام دیوتاؤں سے بلند۔\n6۔ لیکن کون اس کے لیے گھر بنا سکتا ہے، جب کہ آسمان اور آسمان اسے سمیٹے نہیں سکتے؟ تو پھر میں کون ہوں کہ میں اس کے لیے گھر بناؤں، سوائے اس کے کہ اس کے سامنے قربانی دوں؟ {قابل ہے: عبرانی۔ طاقت برقرار رکھی ہے، یا، حاصل کی ہے}\n7۔ اب مجھے ایک چالاک آدمی بھیج دو جو سونے، چاندی، پیتل، لوہے، جامنی، سرخ اور نیلے رنگ میں کام کرے، اور جو میرے ساتھ یہوداہ اور یروشلم میں موجود چالاک لوگوں کے ساتھ تدفین کرنے کی مہارت رکھتا ہو، جنہیں میرے والد نے فراہم کیا تھا۔ {قبر تک: عبرانی۔ قبر کی قبروں تک}\n8۔ لبنان سے دیودار، صنوبر اور الگم کے درخت بھی بھیج دو، کیونکہ میں جانتا ہوں کہ تمہارے خادم لبنان میں لکڑی کاٹنے میں مہارت رکھتے ہیں؛ اور دیکھو، میرے بندے {تمہارے بندوں کے ساتھ} ہوں گے، {الگم: جسے المگم بھی کہا جاتا ہے}\n9۔ یہاں تک کہ میرے لیے وافر لکڑی تیار کرنے کے لیے: کیونکہ جو گھر میں تعمیر کرنے جا رہا ہوں {وہ شاندار ہوگا} عظیم ہوگا۔ {شاندار...: عبرانی۔ عظیم اور شاندار}\n10۔ اور دیکھو، میں تمہارے خادموں کو وہ لکڑی کاٹنے والے دوں گا، بیس ہزار پیسے گندم کے پیسے، بیس ہزار جو، بیس ہزار شراب کے غسل اور بیس ہزار تیل کے حمام دوں گا۔\n11۔ پھر صور کے بادشاہ حورام نے تحریری جواب دیا، جو اس نے سلیمان کو بھیجا، کیونکہ خداوند نے اپنے لوگوں سے محبت کی ہے، اس نے تمہیں ان پر بادشاہ بنایا ہے۔\n12۔ ہورام نے مزید کہا، مبارک ہو خداوند اسرائیل کے خدا، جس نے آسمان اور زمین بنائے، جس نے داؤد بادشاہ کو ایک دانا بیٹا دیا، جو حکمت اور سمجھ سے مالا مال ہے، جو خداوند کے لیے گھر اور اس کی بادشاہی کے لیے گھر بنا سکے۔ {موصول...: عببرانی۔ سمجھداری اور سمجھ بوجھ جاننا}\n13۔ اور اب میں نے ایک چالاک آدمی بھیجا ہے، جو سمجھ بوجھ سے بھرپور ہے، اپنے والد کے ہورام کا،\n14۔ دان کی بیٹیوں کی ایک عورت کا بیٹا، اور اس کا باپ صور کا آدمی تھا، سونے، چاندی، پیتل، لوہا، پتھر اور لکڑی میں، جامنی، نیلے، عمدہ کتان اور سرخ میں کام کرنے میں ماہر تھا؛ اور کسی بھی قسم کی تدفین کو دفن کرنا، اور ہر وہ چال معلوم کرنا جو اس کے خلاف ہو، تمہارے چالاک آدمیوں کے ساتھ، اور میرے آقا ڈیوڈ کے چالاک آدمیوں کے ساتھ۔\n15۔ اب گندم، جو، تیل اور شراب، جس کا ذکر میرے آقا نے کیا ہے، وہ اپنے خادموں کو بھیج دے:\n16۔ اور ہم لبنان سے لکڑیاں کاٹیں گے، جتنا تمہیں ضرورت ہو: اور ہم اسے سمندر کے راستے تیروں کی صورت میں یوفا تک پہنچائیں گے؛ اور تم اسے یروشلم تک لے جاؤ گے۔ {اتنا ہی...: اپنی تمام ضرورت کے مطابق عبری} {جوپا: عبرانی۔ جافو}\n17۔ اور سلیمان نے اسرائیل کی سرزمین میں موجود تمام اجنبیوں کو گنتا تھا، جیسا کہ اس کے باپ نے داؤد نے گنا تھا؛ اور وہ ایک سو پچاس ہزار تین ہزار چھ سو ملے۔ {دی اجنبی: عبرانی۔ مرد، اجنبی\n18۔ اور اس نے ان میں سے تین سو دس ہزار کو بوجھ اٹھانے والے، اور چولیس ہزار پہاڑ میں کٹائی کرنے والے مقرر کیے، اور تین ہزار چھ سو نگران مقرر کیے تاکہ لوگوں کو کام فراہم کیا جا سکے۔","1۔ پھر سلیمان نے یروشلم میں ماؤنٹ موریاہ میں خداوند کا گھر تعمیر کرنا شروع کیا، جہاں {خدا} اپنے والد داؤد کو ظاہر ہوا، اس جگہ پر جو داؤد نے اورنان یبوسی کے تھریشنگ فلور میں تیار کی تھی۔ {کہاں...: یا، جو اس کے والد داؤد کو دیکھا گیا تھا} {اورنان: جسے آراونا بھی کہا جاتا ہے}\n2۔ اور اس نے اپنی حکومت کے دوسرے مہینے کے دوسرے دن میں تعمیر شروع کی۔\n3۔ اب یہ وہ چیزیں ہیں جن میں سلیمان کو خدا کے گھر کی تعمیر کے لیے ہدایت دی گئی تھی۔ پہلی پیمائش کے بعد کی لمبائی کیوبٹس کے حساب سے تین سو کیوبٹ تھی، اور چوڑائی بیس کیوبٹ تھی۔ {ہدایت شدہ: عبوری۔ قائم شدہ}\n4۔ اور وہ برآمدہ جو {گھر کے سامنے} تھا، اس کی لمبائی {گھر کی چوڑائی} کے مطابق بیس کیوبٹ تھی، اور اونچائی {ایک سو بیس} تھی: اور اس کے اوپر خالص سونا رکھا گیا۔\n5۔ اور بڑے گھر کو اس نے صنوبر کے درخت سے ڈھانپ دیا، جس پر عمدہ سونا چڑھایا، اور اس پر کھجور کے درخت اور زنجیریں لگا دیں۔\n6۔ اور اس نے گھر کو خوبصورتی کے لیے قیمتی پتھروں سے سجایا: اور سونا پرویم کا سونا تھا۔ {گارنشڈ: عبوری۔ کورڈ}\n7۔ اس نے گھر، بیموں، ستونوں، دیواروں اور دروازوں کو بھی سونے سے ڈھانپ دیا؛ اور دیواروں پر کندہ شدہ فرشتے تھے۔\n8۔ اور اس نے سب سے مقدس گھر بنایا، جس کی لمبائی گھر کی چوڑائی کے مطابق بیس کیوبٹ تھی، اور اس کی چوڑائی بیس ہاتھ تھی، اور اس پر عمدہ سونے سے ڈھانپ دیا، جو چھ سو ٹیلنٹ بنتا تھا۔\n9۔ اور کیلوں کا وزن {تھا} پچاس شیکل سونا۔ اور اس نے اوپری کمروں پر سونا سکھایا۔\n10۔ اور سب سے مقدس گھر میں اس نے دو کروبی مجسمے بنائے اور ان پر سونے کا رنگ دیا۔ {تصویر...: یا، (جیسا کہ کچھ لوگ سمجھتے ہیں) متحرک کام کا}\n11۔ اور کروبیوں کے پر بیس ہاتھ لمبے تھے: ایک پر {ایک فرشتہ کا} پانچ ہاتھ تھا، جو گھر کی دیوار تک پہنچتا تھا؛ اور دوسرا پر {اسی طرح} پانچ کیوبٹ تھا، جو دوسرے فرشتہ کے پر تک پہنچتا تھا۔\n12۔ اور دوسرے فرشتہ کا {ایک} پر {تھا} پانچ ہاتھ تھا، جو گھر کی دیوار تک پہنچتا تھا: اور دوسرا پر {تھا} پانچ ہاتھ {بھی}، جو دوسرے فرشتہ کے پر سے جڑا ہوا تھا۔\n13۔ ان کروبیوں کے پر بیس کیوبٹ تک پھیل گئے: اور وہ اپنے پیروں پر کھڑے ہوئے، اور ان کے چہرے اندر کی طرف تھے۔ {اندرونی طرف: یا، گھر کی طرف}\n14۔ اور اس نے پردہ نیلا، جامنی، سرخ، عمدہ کتان بنایا، اور اس پر فرشتے بنائے۔ {لکھا: عبریڈی۔ اوپر جانے کی وجہ سے}\n15۔ اس نے گھر کے سامنے تیس اور پانچ ہاتھ اونچے دو ستون بنائے، اور ہر ایک کے اوپر جو کپیٹر تھا وہ پانچ کیوبٹ کا تھا۔ {اونچا: ہیب۔ لمبا}\n16۔ اور اس نے زنجیریں بنائیں، {جیسا کہ} پیش گوئی میں، اور ستونوں کے سروں پر {انہیں} باندھ دیے؛ اور سو انار بنائے، اور انہیں زنجیروں میں باندھا۔\n17۔ اور اس نے مندر کے سامنے ستون کھڑے کیے، ایک دائیں اور دوسرا بائیں طرف؛ اور دائیں ہاتھ والے کا نام یاخن رکھا، اور بائیں ہاتھ والے کا نام بوعز۔ {جچن: یعنی، وہ قائم کرے گا} {بوعز: یعنی، اس میں طاقت ہے}","1۔ اس کے علاوہ اس نے پیتل کا ایک قربان گاہ بنایا، جس کی لمبائی بیس کیوبٹ، چوڑائی بیس کیوبٹ اور اونچائی دس کیوبٹ تھی۔\n2۔ اسی طرح اس نے دس کیوبٹس کا پگھلا ہوا سمندر بنایا، جو کنارے سے کنارے تک گول تھا، اور اس کی اونچائی کے برابر پانچ کیوبٹ تھا؛ اور تیس کیوبٹ کی قطار اس کے گرد گھومتی تھی۔ {سے...: عبرانی اپنے کنارے سے کنارے تک}\n3۔ اور اس کے نیچے بیل کی مماثلت تھی، جو اس کے گرد گھیرے ہوئے تھی: دس ایک کیوبٹ میں، جو سمندر کے گرد گھیرے ہوئے تھے۔ دو قطاریں بیلوں کی ڈھالی گئی تھیں، جب اسے ڈھالا گیا۔\n4۔ وہ بارہ بیلوں پر کھڑا تھا، تین شمال کی طرف، تین مغرب کی طرف، تین جنوب کی طرف، اور تین مشرق کی طرف دیکھ رہے تھے: اور سمندر ان پر اوپر تھا، اور ان کے تمام پچھلے حصے اندر کی طرف تھے۔\n5۔ اور اس کی موٹائی ہاتھ کی چوڑائی تھی، اور اس کا کنارہ پیالے کے کنارے کی طرح تھا، جس میں کنول کے پھول تھے؛ {اور} اسے تین ہزار حمام ملے اور اس نے سنبھالا۔ {پھولوں کے ساتھ...: یا، کنول کے پھول کی طرح}\n6۔ اس نے دس لیور بھی بنائے، اور دائیں ہاتھ پر پانچ اور بائیں طرف پانچ رکھے، تاکہ ان میں دھوئے جا سکیں: وہ چیزیں جو انہوں نے جلانے والی قربانی کے لیے پیش کیں؛ لیکن سمندر پادریوں کے لیے نہانے کے لیے تھا۔ {ایسا...: عبرانی۔ سلائی کی قربانی کا کام}\n7۔ اور اس نے ان کی شکل کے مطابق سونے کے دس موم بتی بنائیں، اور انہیں مندر میں رکھ دیا، پانچ دائیں ہاتھ پر، اور پانچ بائیں طرف۔\n8۔ اس نے دس میزیں بھی بنائیں، اور انہیں مندر میں، پانچ دائیں طرف، اور پانچ بائیں طرف رکھے۔ اور اس نے سونے کے سو بیسن بنائے۔ {بیسن: اور، بولز}\n9۔ مزید برآں، اس نے پادریوں کا صحن، عظیم صحن، اور دربار کے دروازے بنائے، اور ان کے دروازوں کو پیتل سے ڈھانپ دیا۔\n10۔ اور اس نے سمندر کو مشرقی سرے کے دائیں طرف، جنوب کے خلاف رکھا۔\n11۔ اور حورام نے برتن، بیلچے، اور حوض بنائے۔ اور ہورام نے وہ کام مکمل کیا جو اسے بادشاہ سلیمان کے لیے خدا کے گھر کے لیے کرنا تھا؛ {بیسن: اور، بولز} {ختم: عبوری۔ مکمل کرنا ہے}\n12۔ {یعنی}، دو ستون، پوملز، اور چیپٹرز {جو تھے} دو ستونوں کے اوپر، اور دو ہار جو دو پوملز کو ڈھانپتے تھے جو {ستونوں کے اوپر} تھے؛\n13۔ اور دو ہاروں پر چار سو انار؛ ہر ہار پر دو قطاریں انار رکھی جاتی تھیں، تاکہ چیپٹرز کے دو پوملز کو ڈھانپ دیا جا سکے جو ستونوں پر {تھے}۔ {اوپر: ہیب۔ چہرے پر}\n14۔ اس نے بنیادیں بھی بنائیں، اور بیسز پر لیورز بنائیں؛ {لیورز: اور، کیلڈرونز}\n15۔ ایک سمندر، اور اس کے نیچے بارہ بیل۔\n16۔ برتن، بیلچے، گوشت کے کانٹے اور ان کے تمام آلات بھی اپنے والد ہورام نے بادشاہ سلیمان کے لیے روشن پیتل کے خداوند کے گھر کے لیے بنائے تھے۔ {روشن: عبوری۔ روشن کیا گیا، یا، رچ دیا گیا}\n17۔ اردن کے میدان میں بادشاہ نے انہیں مٹی کی زمین میں پھینکا، جو سکوت اور زرداتا کے درمیان تھا۔ {clay...: عببرانی۔ زمین کی موٹائی}\n18۔ یوں سلیمان نے یہ تمام برتن بڑی مقدار میں بنائیں: کیونکہ پیتل کا وزن معلوم نہیں ہو سکا۔\n19۔ اور سلیمان نے وہ تمام برتن بنائے جو خدا کے گھر کے لیے تھے، سونے کی قربان گاہ بھی، اور وہ میزیں جن پر روٹی رکھی گئی تھی؛\n20۔ مزید یہ کہ موم بتی اور ان کے چراغ، تاکہ وہ نیور کے سامنے کی طرح خالص سونے کی طرح جلیں؛\n21۔ اور پھول، چراغ اور چمٹے، {جو سونے سے بنے ہیں}، {اور} وہ کامل سونا؛ {کامل...: عبوری۔ سونے کی کمال}\n22۔ اور سنیفرز، اور بیسن، چمچ، اور بنو، {سونے} کے: اور گھر کا داخلہ، اس کے اندرونی دروازے سب سے مقدس {جگہ} کے لیے، اور مندر کے گھر کے دروازے، {سونے} کے تھے۔ {بیسن: اور، بولز}","1۔ یوں وہ سارا کام جو سلیمان نے خداوند کے گھر کے لیے کیا تھا، مکمل ہو گیا: اور سلیمان نے وہ سب چیزیں لے آئیں جو اس کے والد نے وقف کی تھیں؛ اور چاندی، سونا، اور تمام آلات اسے خدا کے گھر کے خزانے میں شامل کر دیتے ہیں۔\n2۔ پھر سلیمان نے اسرائیل کے بزرگوں اور قبائل کے تمام سرداروں، جو بنی اسرائیل کے باپ اجداد میں سے سردار تھے، کو یروشلم میں جمع کیا تاکہ وہ داؤد کے شہر سے خداوند کے عہد کا صندوق نکالیں، جو {ہے} صیہون۔\n3۔ اسی لیے اسرائیل کے تمام لوگ ساتویں مہینے کی دعوت میں بادشاہ کے سامنے جمع ہوئے۔\n4۔ اور اسرائیل کے تمام بزرگ آئے؛ اور لاویوں نے کشتی سنبھال لی۔\n5۔ اور انہوں نے صندوق، جماعت کا خیمہ اور وہ تمام مقدس برتن جو خیمہ میں تھے، انہیں کاہنوں اور لاویوں نے اٹھایا۔\n6۔ اسی طرح بادشاہ سلیمان اور اسرائیل کی تمام جماعت جو اس کے پاس صندوق کے سامنے جمع ہوئی، نے بھیڑیں اور بیل قربان کیے، جو نہ بتائے جا سکتے تھے اور نہ ہی تعداد میں شمار کیے جا سکتے تھے۔\n7۔ اور کاہنوں نے خداوند کے عہد کے صندوق کو اس کی جگہ، گھر کے پیش گوئی، اور سب سے مقدس {جگہ، حتیٰ کہ} میں کروبیوں کے پروں کے نیچے لایا:\n8۔ کیونکہ کروبیوں نے اپنے پر صندوق کی جگہ پر پھیلا دیے، اور کروبی نے صندوق اور اس کے اوپر کے لاٹھیوں کو ڈھانپ لیا۔\n9۔ اور انہوں نے کشتی کے ڈنڈے نکالے تاکہ لکڑیوں کے سرے صندوق سے پہلے ہی دیکھے جا سکیں؛ لیکن وہ باہر نہیں دیکھے گئے۔ اور یہ آج تک موجود ہے۔ {وہاں...: یا، وہ وہاں ہیں}\n10۔ {صندوق میں کچھ نہیں تھا سوائے ان دو میزوں کے جو موسیٰ نے حرب میں رکھی تھیں، جب خداوند نے بنی اسرائیل کے ساتھ {ایک معاہد} کیا، جب وہ مصر سے باہر آئے۔ {جب خداوند: یا، کہاں، وغیرہ}\n11۔ اور یہ اس وقت ہوا جب پادری مقدس {جگہ} سے باہر آئے: (کیونکہ تمام پادری {جو موجود تھے} مقدس تھے، {اور} نے {پھر} انتظار نہیں کیا: {موجود: عبرانی۔ مل گیا}\n12۔ اسی طرح لاوی {جو کہ} گانے والے تھے، سب آصاف، ہیمان، یدوتون کے، اپنے بیٹوں اور بھائیوں کے ساتھ، سفید چادروں میں ملبوس، جھنجھن، زبور اور ہارپ کے ساتھ، قربان گاہ کے مشرقی سرے پر کھڑے تھے، اور ان کے ساتھ ایک سو بیس پادری بگل بجا رہے تھے :)\n13. یہ بھی ہوا کہ جیسے بگل بجانے والے اور گلوکار ایک ہو گئے، کہ وہ ایک آواز نکالیں جو خدا کی تعریف اور شکریہ میں سنائی دیتی رہیں؛ اور جب انہوں نے اپنی آواز کو ترمپٹ، سنبل اور موسیقی کے آلات سے بلند کیا، اور خداوند کی تعریف کی، {کہا}، کیونکہ {وہ} اچھا ہے؛ کیونکہ اس کی رحمت {ہمیشہ قائم ہے}: کہ {تب} گھر بادل سے بھر گیا، {حتی} خداوند کا گھر؛\n14۔ تاکہ پادری بادلوں کی وجہ سے خدمت کرنے کے لیے کھڑے نہ ہو سکے: کیونکہ خداوند کی جلال نے خدا کے گھر کو بھر دیا تھا۔","1۔ پھر سلیمان نے کہا، خداوند نے کہا ہے کہ وہ گہری تاریکی میں رہے گا۔\n2۔ لیکن میں نے تمہارے لیے رہائش کا گھر بنایا ہے، اور ہمیشہ کے لیے تمہارے لیے ایک جگہ ہے۔\n3۔ اور بادشاہ نے اپنا چہرہ موڑ لیا، اور پورے اسرائیل کی جماعت کو برکت دی: اور اسرائیل کی تمام جماعت کھڑی ہو گئی۔\n4۔ اور اس نے کہا، مبارک ہو خداوند اسرائیل کے، جس نے اپنے ہاتھوں سے وہ سب کچھ پورا کیا جو اس نے میرے باپ داؤد سے کہا، اور کہا،\n5۔ جس دن میں نے اپنی قوم کو مصر کی سرزمین سے نکالا، میں نے اسرائیل کے تمام قبائل میں سے کوئی شہر نہیں چنا تاکہ میرا نام وہاں ہو؛ نہ میں نے کسی انسان کو اپنے قوم اسرائیل پر حکمران بنانے کے لیے منتخب کیا:\n6۔ لیکن میں نے یروشلم کو چنا ہے، تاکہ میرا نام وہاں ہو؛ اور میں نے داؤد کو اپنے قوم اسرائیل پر ترجیح دی ہے۔\n7۔ اب یہ میرے باپ داؤد کے دل میں تھا کہ وہ اسرائیل کے خداوند خدا کے نام کے لیے ایک گھر تعمیر کرے۔\n8۔ لیکن خداوند نے میرے باپ داؤد سے کہا، چونکہ یہ تمہارے دل میں تھا کہ میرے نام کے لیے گھر بناؤ، تم نے اچھا کیا کیونکہ یہ تمہارے دل میں تھا:\n9۔ اگرچہ تم گھر نہیں بناؤ گے؛ لیکن تمہارا بیٹا جو تمہاری کمر سے نکلے گا، وہ میرے نام کے لیے گھر بنائے گا۔\n10۔ خداوند نے اپنا کلام پورا کیا جو اس نے کہا ہے: کیونکہ میں اپنے باپ داؤد کے کمرے میں زندہ ہوا ہوں، اور اسرائیل کے تخت پر بیٹھا ہوں، جیسا کہ خداوند نے وعدہ کیا تھا، اور میں نے یہ گھر اسرائیل کے خداوند خدا کے نام کے لیے تعمیر کیا ہے۔\n11۔ اور اس میں میں نے وہ صندوق رکھا ہے، جس میں خداوند کا عہد ہے، جو اس نے بنی اسرائیل کے ساتھ کیا تھا۔\n12۔ اور وہ خداوند کے قربان گاہ کے سامنے تمام اسرائیل کی جماعت کے سامنے کھڑا ہوا اور اپنے ہاتھ پھیلا دیے:\n13۔ کیونکہ سلیمان نے پانچ ہاتھ لمبا، پانچ ہاتھ چوڑا، اور تین ہاتھ اونچا ایک مچھلا بنایا اور اسے صحن کے بیچ میں رکھا، اور اس پر کھڑا ہوا، اسرائیل کی تمام جماعت کے سامنے گھٹنے ٹیک کر اپنے ہاتھ آسمان کی طرف پھیلایا، {طویل...: عبرانی۔ اس کی لمبائی وغیرہ}\n14۔ اور کہا، اے رب اسرائیل کے خدا، آسمان اور زمین میں تیرے جیسا کوئی خدا نہیں؛ جو عہد قائم رکھتا ہے، اور اپنے بندوں پر رحم کرتا ہے، جو اپنے تمام دلوں سے تیرے سامنے چلتے ہیں:\n15۔ تو نے اپنے خادم داؤد میرے باپ کے ساتھ وہ وعدہ پورا کیا جو تم نے اس سے کیا تھا؛ اور اپنے منہ سے بولو، اور اپنے ہاتھ سے پورا کیا، جیسا کہ آج ہے۔\n16۔ اب، اے رب اسرائیل کے خدا، اپنے بندے داؤد میرے باپ کے ساتھ جو وعدہ کیا ہے، اسے قائم رکھ اور کہا، میرے سامنے کوئی انسان اسرائیل کے تخت پر بیٹھنے سے محروم نہیں ہوگا؛ پھر بھی تمہارے بچے میرے قانون میں چلنے کے اپنے راستے پر دھیان دیں، جیسے تم میرے سامنے چلے ہو۔ {وہاں...: عبرانی۔ کوئی آدمی کاٹا نہیں جائے گا}\n17۔ اب، اے اسرائیل کے خداوند، تیری بات ثابت ہو، جو تو نے اپنے بندے داؤد سے کہی ہے۔\n18. لیکن کیا خدا حقیقت میں زمین پر انسانوں کے ساتھ رہے گا؟ دیکھو، آسمان اور آسمانوں کا آسمان تمہیں قید نہیں کر سکتے؛ یہ گھر جو میں نے بنایا ہے، اس سے کہیں دور کی بات ہے!\n19۔ لہٰذا اپنے بندے کی دعا اور اس کی التجا کا احترام کرو، اے خداوند میرے خدا، کہ اپنے بندے کی دعا اور پکار کو سنو جو تمہارے خادم تمہارے سامنے کہتا ہے:\n20۔ تاکہ تمہاری آنکھیں دن رات اس گھر پر کھلی رہیں، اس جگہ پر جہاں تم نے کہا تھا کہ تم اپنا نام وہاں رکھنا چاہتے ہو؛ اس دعا کو سننے کے لیے جو تمہارا بندہ اس جگہ کے لیے دعا کرتا ہے۔ {اس جگہ کی طرف...: یا، اس جگہ پر}\n21۔ لہٰذا اپنے خادم اور اپنے قوم اسرائیل کی دعاؤں کو سنو، جو وہ اس جگہ کی طرف بڑھائیں گے: اپنے گھر سے سنو، {حتیٰ کہ} آسمان سے؛ اور جب تم سنو تو معاف کر دو۔ {بنا: عبوری۔ دعا کریں} {اس جگہ کی طرف...: یا، اس جگہ پر}\n22۔ اگر کوئی شخص اپنے پڑوسی کے خلاف گناہ کرے، اور اس پر قسم کھائی جائے کہ وہ اسے قسم دے، اور قسم اس گھر میں تمہارے قربان گاہ کے سامنے آئے؛ {اور ایک حلف...: عبرانی۔ اور وہ اس سے قسم کا تقاضا کرتا ہے}\n23۔ تو پھر آسمان سے سنو، اور اپنے بندوں کا فیصلہ کرو، بدکاروں کا بدلہ دے کر، اس کے اپنے سر پر اس کا راستہ بدلہ دے کر؛ اور راستبازوں کو راستباز بنا کر، اسے اس کی راستبازی کے مطابق دے کر۔\n24۔ اور اگر تمہارے لوگ اسرائیل دشمن کے سامنے بدتر ہو جائیں، کیونکہ انہوں نے تمہارے خلاف گناہ کیا ہے؛ اور واپس آئے گا، تمہارے نام کا اعتراف کرے گا، اور اس گھر میں تمہارے سامنے دعا کرے گا اور دعا کرے گا؛ {رکھا جائے...: یا، دیوانہ ہو جاؤ} {اندر: یا، کی طرف}\n25۔ پھر آسمانوں سے سنو، اپنے قوم اسرائیل کے گناہ کو معاف کرو، اور انہیں اس زمین پر واپس لے آؤ جو تم نے انہیں اور ان کے باپ اجداد کو دی ہے۔\n26۔ جب آسمان بند ہو جائے اور بارش نہ ہو، کیونکہ انہوں نے تمہارے خلاف گناہ کیا ہے؛ {پھر بھی} اگر وہ اس جگہ کی طرف دعا کریں، اور آپ کے نام کا اعتراف کریں، اور جب آپ انہیں تکلیف دیں تو اپنے گناہ سے منہ موڑ لیں؛ {اس جگہ کی طرف...: یا، اس جگہ پر}\n27۔ تو تو آسمان سے سنو، اور اپنے بندوں اور اپنے قوم اسرائیل کے گناہ کو معاف کر، جب تم نے انہیں نیک راستہ سکھایا ہے جس میں وہ چلنے چاہئیں؛ اور اپنی زمین پر بارش نازل کر، جو تم نے اپنے لوگوں کو وراثت کے طور پر دی ہے۔\n28۔ اگر زمین میں کمی ہو، اگر وبا ہو، اگر پھپھوندی، پھپھوندی، ٹڈی دل یا کیٹرپلرز ہوں؛ اگر ان کے دشمن ان کے ملک کے شہروں میں ان کا محاصرہ کریں؛ جو بھی زخم یا بیماری ہو: {شہروں میں...: عبرانی۔ ان کے دروازوں کی سرزمین میں}\n29۔ {تو} کون سی دعا {یا} کیا دعا کی جائے کسی انسان سے، یا تمہارے تمام قوم اسرائیل کی، جب ہر کوئی اپنی تکلیف اور غم کو پہچان لے گا، اور اس گھر میں اپنے ہاتھ پھیلائے گا: {اندر: یا، کی طرف} {اس جگہ کی طرف...: یا، اس جگہ پر}\n30۔ پھر آسمان سے اپنے گھر کو سنو، اور معاف کرو، اور ہر انسان کو اس کے تمام طریقوں کے مطابق پیش کرو، جس کے دل کو تم جانتے ہو؛ (کیونکہ تو صرف انسانوں کے بچوں کے دلوں کو جانتی ہو:)\n31۔ تاکہ وہ تم سے ڈریں، جب تک وہ اس زمین میں رہتے ہیں جو تم نے ہمارے آباؤ اجداد کو دی ہے۔ {خدا حافظ...: عبرانی۔ وہ تمام دن جو} {زمین میں: عبرانی۔ زمین کے چہرے پر}\n32۔ مزید اس اجنبی کے بارے میں، جو تیری قوم اسرائیل سے نہیں بلکہ تمہارے عظیم نام، تمہارے طاقتور ہاتھ، اور تمہارے پھیلائے ہوئے بازو کے لیے دور دراز ملک سے آیا ہے؛ اگر وہ اس گھر میں آ کر دعا کریں؛ {اس جگہ کی طرف...: یا، اس جگہ پر}\n33۔ پھر تو آسمان سے سنو، {حتیٰ کہ} اپنے گھر سے، اور اجنبی کی پکارنے والی ہر چیز کے مطابق عمل کرو؛ تاکہ زمین کے تمام لوگ تیرے نام کو جان سکیں، اور آپ سے ڈریں، جیسا کہ آپ کے لوگ اسرائیل سے ڈرتے ہیں، اور جان سکیں کہ یہ گھر جو میں نے بنایا ہے وہ آپ کے نام سے پکارا جاتا ہے۔ {یہ...: عبرانی اس گھر پر تیرا نام پکارا جاتا ہے}\n34۔ اگر تمہارے لوگ اپنے دشمنوں کے خلاف جنگ کے لیے نکلیں جیسا کہ تم انہیں بھیجو گے، اور وہ تم سے اس شہر کی طرف دعا کریں جو تم نے چنا ہے، اور اس گھر کی طرف جو میں نے تمہارے نام کے لیے بنایا ہے؛\n35۔ پھر آسمان سے ان کی دعا اور دعا سنو اور ان کے مقصد کو قائم رکھو۔ {سبب: یا، دائیں طرف}\n36۔ اگر وہ تمہارے خلاف گناہ کریں، (کیونکہ کوئی ایسا انسان نہیں جو گناہ نہ کرے،) اور تم ان سے ناراض ہو جاؤ، اور انہیں ان کے دشمنوں کے سامنے حوالے کر دو، اور وہ انہیں قیدی بنا کر کسی دور یا قریب زمین میں لے جاؤ؛ {وہ انہیں قیدیوں میں لے جاتے ہیں: عبرانی۔ جو انہیں قیدی بناتے ہیں وہ انہیں لے جاتے ہیں}\n37۔ پھر بھی {اگر} وہ خود کو اس زمین میں سمجھیں جہاں انہیں قید کیا گیا ہے، اور اپنی قید کی سرزمین میں آپ سے دعا کریں، کہیں: ہم نے گناہ کیا ہے، ہم نے برا کیا ہے، اور بدکاری کی ہے؛ {سوچو...: عبرانی۔ ان کے دل میں واپس لاؤ}\n38۔ اگر وہ اپنے پورے دل اور جان کے ساتھ تمہارے پاس واپس آئیں اس سرزمین میں جہاں وہ انہیں قیدی لے کر آئے ہیں، اور اپنی زمین کی طرف دعا کریں، جو تم نے ان کے باپوں کو دی، اور اس شہر کی طرف جو تم نے چنا ہے، اور اس گھر کی طرف جو میں نے تمہارے نام کے لیے بنایا ہے:\n39۔ پھر آسمانوں سے سنو، حتیٰ کہ اپنے گھر سے، ان کی دعا اور دعائیں سنو، ان کے مقصد کا دفاع کرو، اور اپنے لوگوں کو معاف کرو جنہوں نے تمہارے ساتھ گناہ کیا ہے۔ {سبب: یا، دائیں طرف}\n40۔ اب، میرے خدا، میں تجھ سے التجا کرتا ہوں کہ تیری آنکھیں کھلی رہو، اور {تمہارے} کان {ہو} اس جگہ کی دعا [جو کی جاتی ہے}۔ {ابھی...: عبرانی اس جگہ کی دعا کے لیے}\n41. لہٰذا، اے خداوند خدا، اپنی آرام گاہ اور اپنی طاقت کے صندوق میں اٹھو: اے خداوند خدا، اپنے کاہنوں کو نجات کے لباس میں ملبوس ہو اور تمہارے مقدسین نیکی میں خوش ہوں۔\n42. اے خداوند خدا، اپنے مسح شدہ کا چہرہ نہ موڑو: اپنے بندے داؤد کی رحمتوں کو یاد رکھ۔","1۔ جب سلیمان نے دعا ختم کی، تو آگ آسمان سے نیچے آئی، اور اس نے جلنے والی قربانی اور قربانیاں جلا دیں؛ اور خداوند کی شان نے گھر کو بھر دیا۔\n2۔ اور پادری خداوند کے گھر میں داخل نہیں ہو سکتے تھے، کیونکہ خداوند کی جلال نے خداوند کے گھر کو بھر دیا تھا۔\n3۔ اور جب تمام بنی اسرائیل نے دیکھا کہ آگ کیسے گر رہی ہے، اور خداوند کی شان گھر پر ہے، تو وہ فرش پر اپنے چہرے زمین پر رکھ کر سجدہ کرنے لگے، عبادت کرنے لگے، اور خداوند کی تعریف کی، {کہنے لگے}، کیونکہ {وہ} اچھا ہے؛ اس کی رحمت {ہمیشہ کے لیے} کے لیے۔\n4۔ پھر بادشاہ اور تمام لوگ خداوند کے سامنے قربانیاں پیش کرنے لگے۔\n5۔ اور بادشاہ سلیمان نے بیس بائیس ہزار بیل اور ایک لاکھ بیس ہزار بھیڑیں قربان کیں: یوں بادشاہ اور تمام لوگوں نے خدا کے گھر کو وقف کیا۔\n6۔ اور کاہنوں نے اپنے عہدوں کا انتظار کیا: لاوی بھی خداوند کے ساز لے کر گئے، جو داؤد بادشاہ نے خداوند کی تعریف کے لیے بنائے تھے، کیونکہ اس کی رحمت ہمیشہ قائم رہتی ہے، جب داؤد نے ان کی خدمت سے تعریف کی؛ اور کاہنوں نے ان کے سامنے بگل بجائے، اور تمام اسرائیل کھڑے ہو گئے۔ {ان کے...: عبرانی کے ذریعے۔ ان کے ہاتھ سے}\n7۔ مزید برآں، سلیمان نے صحن کے وسط کو مقدس قرار دیا جو خداوند کے گھر کے سامنے تھا: کیونکہ وہاں اس نے جلنے کی قربانیاں اور صلح کی نذرانے کی چکنائی پیش کی، کیونکہ سلیمان نے جو برازن قربان گاہ بنائی تھی، وہ جلنے والی قربانیاں، گوشت کی قربانیاں اور چربی حاصل نہیں کر سکتی تھی۔\n8۔ اسی وقت سلیمان نے سات دن عید منایا، اور تمام اسرائیل اس کے ساتھ، جو بہت بڑی جماعت تھی، حمات کے داخل ہونے سے لے کر مصر کے دریا تک جانے سے۔\n9۔ اور آٹھویں دن انہوں نے ایک سنجیدہ اجتماع کیا: کیونکہ انہوں نے سات دن قربان گاہ اور سات دن عید کی تقدیس کی۔ {ایک سنجیدہ...: عبرانی۔ ایک روک تھام}\n10۔ اور ساتویں مہینے کے تین اور بیسویں دن اس نے لوگوں کو ان کے خیموں میں بھیج دیا، خوش اور دل سے اس بھلائی کے لیے جو خداوند نے داؤد، سلیمان، اور اس کے قوم اسرائیل کو دی تھی۔\n11۔ یوں سلیمان نے خداوند کے گھر اور بادشاہ کے گھر کو مکمل کیا: اور جو کچھ بھی سلیمان کے دل میں خداوند کے گھر اور اپنے گھر میں بنانے کے لیے آیا، وہ اس نے خوشحالی سے حاصل کیا۔\n12۔ اور خداوند نے رات کو سلیمان کو ظاہر کیا، اور اس سے کہا، میں نے تمہاری دعا سنی ہے، اور اس جگہ کو اپنے لیے قربانی کا گھر چنا ہے۔\n13۔ اگر میں آسمان کو بند کر دوں کہ بارش نہ ہو، یا اگر میں ٹڈی دل کو حکم دوں کہ وہ زمین کو نگل جائیں، یا اگر میں اپنی قوم میں وبا بھیجوں؛\n14۔ اگر میرے لوگ، جنہیں میرے نام سے پکارا جاتا ہے، عاجز ہو جائیں، دعا کریں، میرا چہرہ تلاش کریں، اور اپنے برے طریقوں سے منہ موڑ لیں؛ تب میں آسمان سے سنوں گا، ان کے گناہ معاف کروں گا، اور ان کی سرزمین کو شفا دوں گا۔ {جو کہ...: عبرانی جس پر میرا نام پکارا جاتا ہے}\n15. اب میری آنکھیں کھلی ہوں گی، اور میرے کان اس جگہ پر کی جانے والی دعا پر توجہ دیں گے۔ {ابھی...: عبرانی اس جگہ کی دعا کے لیے}\n16۔ کیونکہ اب میں نے اس گھر کو چنا اور مقدس کیا ہے، تاکہ میرا نام ہمیشہ کے لیے وہاں رہے: اور میری آنکھیں اور میرا دل ہمیشہ وہاں رہیں گے۔\n17۔ اور جہاں تک تمہارا تعلق ہے، اگر تم میرے سامنے چلو، جیسا کہ تمہارے والد نے داؤد کے ساتھ چلنا چاہا، اور جو کچھ میں نے تمہیں حکم دیا ہے اس کے مطابق عمل کرو، اور میرے قوانین اور فیصلوں کی پابندی کرو؛\n18۔ پھر میں تیری سلطنت کا تخت قائم کروں گا، جیسا کہ میں نے تمہارے باپ سے داؤد سے عہد کیا ہے، کہہ رہا ہوں: اسرائیل میں حکمران بننے والا کوئی آدمی تمہیں نہیں چھوڑے گا۔ {وہاں...: عبرانی۔ تم سے کوئی راستہ نہیں کاٹے گا}\n19۔ لیکن اگر تم منہ موڑ لو، اور میرے قوانین اور احکامات کو چھوڑ دو، جو میں نے تمہارے سامنے رکھے ہیں، اور دوسرے دیوتاؤں کی عبادت کرو اور ان کی عبادت کرو؛\n20۔ پھر میں انہیں اپنی زمین سے جڑوں سے نکال کر نکالوں گا جو میں نے انہیں دی ہے؛ اور یہ گھر، جسے میں نے اپنے نام کے لیے مقدس قرار دیا ہے، میں اپنی نظر سے دور کر دوں گا، اور اسے تمام قوموں کے درمیان ایک کہاوت اور نعرہ بنا دوں گا۔\n21۔ اور یہ گھر، جو بلند ہے، ہر اس شخص کے لیے حیران کن ہوگا جو اس کے پاس سے گزرے گا؛ تاکہ وہ کہے، خداوند نے اس زمین اور اس گھر کے ساتھ ایسا کیوں کیا؟\n22۔ اور جواب دیا جائے گا، کیونکہ انہوں نے اپنے باپ اجداد کے خداوند خدا کو چھوڑ دیا، جس نے انہیں مصر کی سرزمین سے نکالا، اور دوسرے دیوتاؤں کو تھام لیا، ان کی عبادت کی اور ان کی خدمت کی، اسی لیے اس نے ان پر یہ ساری برائی مسلط کی۔","1۔ اور یہ بیس سال کے آخر میں ہوا، جب سلیمان نے خداوند کا گھر اور اپنا گھر تعمیر کیا،\n2۔ کہ وہ شہر جو حورام نے سلیمان کو بحال کیا تھا، سلیمان نے انہیں تعمیر کیا اور بنی اسرائیل کو وہاں آباد کیا۔\n3۔ اور سلیمان ہماتژوبہ گیا اور اس پر غالب آیا۔\n4۔ اور اس نے بیابان میں تدمور اور تمام دکان دار شہر بنائے۔\n5۔ اس نے اوپر بیت حورون اور نیچے بیت حورون تعمیر کیے، جو دیواروں، دروازوں اور سلاخوں سے باڑدار شہر تھے؛\n6۔ اور بعلت، اور وہ تمام ذخیرہ شدہ شہر جو سلیمان کے پاس تھے، اور تمام رتھ کے شہر، اور گھڑ سواروں کے شہر، اور وہ سب جو سلیمان یروشلم، لبنان اور اپنی سلطنت کی پوری سرزمین میں بنانا چاہتا تھا۔ {یہ سب...: عبرانی۔ سلیمان کی تمام خواہش جو وہ تعمیر کرنا چاہتا تھا}\n7۔ {جہاں تک} تمام لوگ {جو ہتیوں، اموریوں، پریزیوں، حویوں، اور یبوسی لوگوں کے باقی رہ گئے تھے، جو {اسرائیل} کے نہیں تھے،\n8۔ {لیکن} ان کے بچوں میں، جو ان کے بعد زمین میں رہ گئے اور جنہیں بنی اسرائیل نے نہیں کھایا، سلیمان نے انہیں آج تک خراج دینے پر مجبور کیا۔\n9۔ لیکن بنی اسرائیل میں سلیمان نے اپنے کام کے لیے کوئی خادم نہیں بنایا؛ لیکن وہ جنگی آدمی تھے، اور اس کے کپتانوں کے سربراہ، اور اس کے رتھ اور گھڑ سواروں کے کپتان تھے۔\n10۔ اور یہ {تھے} بادشاہ سلیمان کے افسران کے سردار، {حتی} دو سو پچاس، جو عوام پر حکمرانی کرتے تھے۔\n11۔ اور سلیمان نے فرعون کی بیٹی کو داؤد کے شہر سے اس گھر میں لایا جو اس نے اس کے لیے بنایا تھا: کیونکہ اس نے کہا، میری بیوی اسرائیل کے بادشاہ داؤد کے گھر میں نہیں رہے گی، کیونکہ وہ مقامات مقدس ہیں، جہاں خداوند کا صندوق آیا ہے۔ {مقدس: عبرانی۔ مقدس مقام}\n12۔ پھر سلیمان نے خداوند کے سامنے اس قربان گاہ پر جلنے کی قربانیاں پیش کیں، جو اس نے برآمدے کے سامنے بنائی تھی،\n13۔ حتیٰ کہ ہر دن ایک مخصوص شرح کے بعد، موسیٰ کے حکم کے مطابق، سبت پر، نئے چاندوں پر، اور مقدس تہواروں پر، سال میں تین بار، بغیر خمیر کے روٹی کے تہوار، ہفتوں کے تہوار میں، اور خیمہ جات کے عید میں۔\n14۔ اور اس نے اپنے والد داؤد کے حکم کے مطابق کاہنوں کی خدمت کے لیے اور لاویوں کو ان کے ذمہ داریوں کے لیے مقرر کیا تاکہ وہ ہر دن کے فرض کے مطابق کاہنوں کے سامنے تعریف اور خدمت کریں: دربان بھی ہر دروازے پر اپنے راستوں سے چلتے تھے: کیونکہ خدا کے آدمی داؤد نے یہی حکم دیا تھا۔ {اسی طرح ڈیوڈ...: عبرانی۔ اسی طرح خدا کے آدمی داؤد کا حکم بھی تھا۔\n15۔ اور انہوں نے بادشاہ کے حکم سے کاہنوں اور لاویوں کو کسی معاملے یا خزانے کے بارے میں نہیں توڑا۔\n16۔ اب سلیمان کے تمام کام خداوند کے گھر کی بنیاد کے دن تک تیار کیے گئے تھے، اور جب تک کہ وہ مکمل نہ ہو جائے۔ {تو} خداوند کا گھر مکمل ہو گیا۔\n17۔ پھر سلیمان ایزیونگبر گیا، اور ایلوتھ گیا، جو سمندر کے کنارے ادوم کی سرزمین پر تھا۔ {ایلوتھ: جسے ایلاتھ بھی کہا جاتا ہے}\n18۔ اور حورام نے اسے اپنے خادموں، جہازوں اور سمندر کے بارے میں جاننے والے خادموں کے ہاتھوں بھیجا؛ اور وہ سلیمان کے خادموں کے ساتھ اوفیر گئے، وہاں سے چار سو پچاس ٹینٹ سونا لے کر بادشاہ سلیمان کے پاس لے آئے۔","1۔ اور جب سبا کی ملکہ نے سلیمان کی شہرت کے بارے میں سنا، تو وہ یروشلم میں سلیمان کو مشکل سوالات سے آزمانے آئی، بہت بڑی جماعت کے ساتھ، مصالحے دار اونٹ، وافر سونا اور قیمتی پتھروں کے ساتھ، اور جب وہ سلیمان کے پاس آئی، تو اس نے اپنے دل کی تمام باتوں کے بارے میں اس سے بات کی۔\n2۔ اور سلیمان نے اسے اس کے سارے سوالات بتا دیے: اور سلیمان سے کچھ بھی چھپا ہوا نہیں تھا جو اس نے اسے نہ بتایا۔\n3۔ اور جب سبا کی ملکہ نے سلیمان کی حکمت دیکھی، اور وہ گھر جو اس نے بنایا تھا،\n4۔ اور اس کے دسترخوان کا گوشت، اس کے خادموں کی نشست، اس کے وزیروں کی حاضری، اور ان کے لباس؛ اس کے پیالیوں کے ساتھ، اور ان کے لباس؛ اور اس کی چڑھائی جس کے ذریعے وہ خداوند کے گھر میں چڑھا؛ اس میں اب کوئی جذبہ نہیں تھا۔ {جام بردار: یا، بٹلرز}\n5۔ اور اس نے بادشاہ سے کہا، {یہ} ایک سچی خبر تھی جو میں نے اپنی زمین میں تمہارے اعمال اور تیری حکمت کے بارے میں سنی: {رپورٹ: عبرانی۔ لفظ} {اعمال: یا، اقوال}\n6۔ لیکن میں نے ان کی باتوں پر یقین نہیں کیا، جب تک میں آ نہ گیا، اور میری آنکھوں نے اسے دیکھ لیا: اور دیکھو، تمہاری حکمت کی عظمت کا آدھا حصہ مجھے نہیں بتایا گیا: {کیونکہ} تو اس شہرت سے بڑھ کر ہے جو میں نے سنی۔\n7. مبارک ہو تمہارے لوگ، اور خوش نصیب ہیں یہ تمہارے بندے، جو ہمیشہ تمہارے سامنے کھڑے ہیں اور تیری حکمت سنتے ہیں۔\n8۔ خداوند تیرا خدا مبارک ہو، جس نے تجھ سے خوش ہوا کہ تمہیں اپنے تخت پر بٹھایا، اور بادشاہ بنے، خداوند تیرے خدا کے لیے: کیونکہ تیرے خدا نے اسرائیل سے محبت کی، انہیں ہمیشہ کے لیے قائم کرنے کے لیے، اس لیے اس نے تمہیں ان پر بادشاہ بنایا، تاکہ فیصلہ اور انصاف کرو۔\n9۔ اور اس نے بادشاہ کو ایک سو بیس تالنٹ سونا اور مصالحے بہت زیادہ اور قیمتی پتھر دیے: نہ ہی وہ مصالحہ تھا جو سبا کی ملکہ نے بادشاہ سلیمان کو دیا تھا۔\n10۔ اور حورام کے خادم اور سلیمان کے خادم، جو اوفیر سے سونا لاتے تھے، الگم کے درخت اور قیمتی پتھر لاتے تھے۔ {الگم...: جسے المگ کے درخت بھی کہا جاتا ہے}\n11۔ اور بادشاہ نے الگم کے درختوں کی چھتیں خداوند کے گھر، بادشاہ کے محل کے لیے اور گلوکاروں کے لیے ہارپ اور زبور بنائیں: اور یہوداہ کی سرزمین میں اس سے پہلے ایسی کوئی نہیں تھی۔ {چھتیں: یا، سیڑھیاں: عبرانی۔ شاہراہیں}\n12۔ اور بادشاہ سلیمان نے سبا کی ملکہ کو اپنی تمام خواہشات دے دیں، جو اس نے مانگی، سوائے اس کے جو اس نے بادشاہ کے لیے لائی تھی۔ تو وہ مڑی، اور اپنی زمین چلی گئی، وہ اور اس کے خادم۔\n13۔ ایک سال میں سلیمان کے پاس سونے کا وزن چھ سو تئیس اور چھ ٹیلنٹ سونا تھا؛\n14۔ اس کے علاوہ جو آدمی اور تاجر لائے تھے۔ اور عرب کے تمام بادشاہوں اور ملک کے حکمرانوں نے سلیمان کو سونا اور چاندی پہنچایا۔ {گورنرز: یا، کپتان}\n15. اور بادشاہ سلیمان نے دو سو ہدف {شکست خوردہ} سونے کیے: چھ سو {شیکل} شکست خوردہ سونا ایک ہدف کو دیے گئے۔\n16۔ اور تین سو ڈھالیں {جو مارے ہوئے سونے سے بنی ہیں}: تین سو {شیکل} سونا ایک ڈھال کو دیا گیا۔ اور بادشاہ نے انہیں لبنان کے جنگل کے گھر میں رکھا۔\n17۔ اس کے علاوہ بادشاہ نے ہاتھی دانت کا ایک عظیم تخت بنایا اور اس پر خالص سونے کی سجاوٹ کی۔\n18۔ اور {تخت تک پہنچنے کے لیے چھ سیڑھیاں تھیں}، جن میں سونے کا ایک اسٹول تھا، {جو} تخت سے بندھا ہوا تھا، اور بیٹھنے کی جگہ کے دونوں طرف کھڑے تھے، اور دو شیر کھڑے تھے: {رہائش: عبرانی۔ ہاتھ}\n19۔ اور بارہ شیر ایک طرف اور دوسری طرف چھ سیڑھیوں پر کھڑے تھے۔ کسی بھی سلطنت میں ایسا کچھ نہیں بنایا گیا۔\n20۔ اور بادشاہ سلیمان کے تمام مشروب کے برتن سونے کے تھے، اور لبنان کے جنگل کے گھر کے تمام برتن خالص سونے کے تھے: کوئی بھی چاندی کے نہیں تھے؛ یہ سلیمان کے زمانے میں کوئی چیز نہیں تھی۔ {خالص: عبرانی۔ چپ رہو} {کوئی چاندی کا نہیں تھا: یا ان میں چاندی نہیں تھی}\n21۔ کیونکہ بادشاہ کے جہاز حورام کے خادموں کے ساتھ ترشیش جاتے تھے: ہر تین سال بعد ترشیش کے جہاز سونا، چاندی، ہاتھی دانت، بندر اور مور لاتے تھے۔ {ہاتھی دانت: یا، ہاتھیوں کے دانت}\n22۔ اور بادشاہ سلیمان نے زمین کے تمام بادشاہوں کو دولت اور حکمت دی۔\n23۔ اور زمین کے تمام بادشاہوں نے سلیمان کی موجودگی کی درخواست کی، تاکہ وہ اس کی حکمت سنیں، جو خدا نے اس کے دل میں رکھی تھی۔\n24۔ اور انہوں نے ہر آدمی کو اس کا تحفہ دیا، چاندی کے برتن، سونے کے برتن، کپڑے، ہارنس، مصالحے، گھوڑے اور خچر، سال بہ سال تنخواہ کے ساتھ۔\n25۔ اور سلیمان کے پاس گھوڑوں اور رتھ کے لیے چار ہزار اصطبل اور بارہ ہزار گھڑ سوار تھے؛ جنہیں انہوں نے رتھ کے شہروں میں اور یروشلم میں بادشاہ کے ساتھ عطا کیا۔\n26۔ اور اس نے دریا سے لے کر فلسطینیوں کی سرزمین تک، اور مصر کی سرحد تک تمام بادشاہوں پر حکومت کی۔ {دریا: یعنی، فرات ہے}\n27. اور بادشاہ نے یروشلم میں چاندی کو پتھر بنایا، اور دیودار کے درختوں نے وہ خوشامد کے درخت بنائے جو نشیبی میدانوں میں کثرت سے ہیں۔ {سلور بنایا: عبرانی۔ چاندی دی}\n28۔ اور انہوں نے مصر اور تمام زمینوں سے گھوڑے سلیمان لے آئے۔\n29۔ اب سلیمان کے باقی اعمال، سب سے پہلے اور آخری، کیا وہ ناتھن نبی کی کتاب میں، احییاہ شیلون کی نبوت میں اور عیدو غیب دان کے خوابوں میں یروبعام بیٹے نباط کے خلاف لکھے نہیں گئے؟ {کتاب: عبرانی۔ الفاظ}\n30۔ اور سلیمان یروشلم میں چالیس سال تک پورے اسرائیل پر حکومت کرتا رہا۔\n31۔ اور سلیمان نے اپنے باپ دادا کے ساتھ سونا شروع کیا، اور اسے اپنے والد داؤد کے شہر میں دفن کیا گیا، اور اس کے بیٹے رحبعام نے اس کی جگہ حکومت کی۔","1۔ اور رحبعام شیکم کے پاس گیا: کیونکہ شیکم کے پاس تمام اسرائیل آئے تھے تاکہ اسے بادشاہ بنائیں۔\n2۔ اور جب یربعام، نیبت کا بیٹا، جو مصر میں تھا، جہاں وہ سلیمان بادشاہ کے حضور سے بھاگا تھا، نے سنا کہ یربعام مصر سے واپس آ گیا۔\n3۔ اور انہوں نے اسے بھیجا اور بلایا۔ تو یربعام اور سارا اسرائیل آئے اور رحبعام سے کہا،\n4۔ تمہارے باپ نے ہمارا جوا سخت کر دیا: اب اپنے باپ کی سخت غلامی اور اس کے بھاری جوے کو کچھ کم کر دو، اور ہم تیری خدمت کریں گے۔\n5۔ اور اس نے ان سے کہا، تین دن بعد میرے پاس واپس آؤ۔ اور لوگ روانہ ہو گئے۔\n6۔ اور بادشاہ رحبعام نے ان بوڑھوں سے مشورہ کیا جو اس کے والد سلیمان کے سامنے کھڑے تھے جب وہ زندہ تھا، اور کہا، تم مجھے کیا مشورہ دیتے ہو کہ میں اس قوم کو جواب دوں؟\n7۔ اور انہوں نے اس سے کہا، \"اگر تم اس قوم کے ساتھ مہربان رہو، انہیں خوش کرو اور ان سے اچھے الفاظ کہو، تو وہ ہمیشہ کے لیے تمہارے خادم رہیں گے۔\n8۔ لیکن اس نے بوڑھوں کی دی ہوئی نصیحت کو چھوڑ دیا، اور ان نوجوانوں سے مشورہ کیا جو اس کے ساتھ پلے بڑھے تھے اور اس کے سامنے کھڑے تھے۔\n9۔ اور اس نے ان سے کہا، تم کیا مشورہ دیتے ہو کہ ہم ان لوگوں کو جواب دے سکیں، جنہوں نے مجھ سے بات کی ہے، کہ تمہارے والد نے ہم پر جو بوجھ لگایا تھا اسے کچھ کم کرو؟\n10۔ اور جو نوجوان اس کے ساتھ پلے بڑھے تھے، انہوں نے اس سے کہا، \"اسی طرح تم ان لوگوں کا جواب دو گے جو تم سے بات کرتے ہیں، کہ تمہارے والد نے ہمارا جوا بھاری کر دیا، لیکن تو اسے ہمارے لیے تھوڑا ہلکا کر دے؛ یوں تم انہیں کہو گے، میری چھوٹی {انگلی} میرے والد کی کمر سے زیادہ موٹی ہوگی۔\n11۔ جہاں میرے والد نے تم پر بھاری جوا ڈالا ہے، میں تمہارے جوتے میں مزید جکڑوں گا: میرے والد نے تمہیں کوڑے مار کر سزا دی، لیکن میں تمہیں بچھوؤں سے سزا دوں گا۔ {میرے والد نے لکھا: عبرانی۔ میرے والد نے لیڈ}\n12۔ تو یربعام اور تمام لوگ تیسرے دن رہوبعام آئے، جیسا کہ بادشاہ نے کہا تھا، تیسرے دن دوبارہ میرے پاس آنا۔\n13۔ اور بادشاہ نے سختی سے جواب دیا؛ اور بادشاہ رحبعام نے بوڑھوں کی نصیحت کو ترک کر دیا،\n14۔ اور نوجوانوں کی نصیحت پر جواب دیا، کہا، میرے والد نے تمہارا جوا بھاری کر دیا، لیکن میں اس میں اضافہ کروں گا: میرے والد نے تمہیں کوڑے مار کر سزا دی، لیکن میں تمہیں بچھو سے سزا دوں گا۔\n15۔ لہٰذا بادشاہ نے لوگوں کی بات نہیں سنی، کیونکہ مقصد خدا کا تھا، تاکہ خداوند اپنا کلام پورا کرے، جو اس نے احییاہ شیلون کے ہاتھوں یربعام بیٹے نباط سے کہا۔\n16۔ اور جب پورے اسرائیل نے دیکھا کہ بادشاہ ان کی بات نہیں سنے گا، تو لوگوں نے بادشاہ کو جواب دیا، \"داؤد میں ہمارا کیا حصہ ہے؟ اور یسوع کے بیٹے میں ہمارے پاس کوئی وراثت نہیں: اے اسرائیل، ہر آدمی اپنے خیموں میں چلو: اور اب، داؤد، اپنے گھر کا خیال رکھو۔ تو تمام اسرائیل اپنے خیموں میں چلے گئے۔\n17. لیکن {جہاں تک یہوداہ کے شہروں میں رہنے والے بنی اسرائیل کا تعلق تھا، رحبعام نے ان پر حکومت کی۔\n18۔ پھر بادشاہ رحبعام نے ہادورام کو بھیجا جو {تھا} کو خراج کے لیے بھیجا؛ اور بنی اسرائیل نے اسے پتھر مارے، جس سے وہ مر گیا۔ لیکن بادشاہ رحبعام نے جلدی کی کہ اسے {اپنی} کے رتھ تک لے جائے، تاکہ وہ یروشلم فرار ہو جائے۔ {اسپیڈ: ہیب۔ خود کو مضبوط کیا}\n19۔ اور اسرائیل آج تک داؤد کے گھر کے خلاف بغاوت کرتا ہے۔","1۔ اور جب رحبعام یروشلم آیا، تو اس نے یہوداہ اور بنیامین کے گھرانے سے ایک لاکھ چولیس ہزار منتخب {مرد} جمع کیے، جو جنگجو تھے، تاکہ اسرائیل کے خلاف لڑیں اور وہ بادشاہی کو دوبارہ رحبعام لے آئے۔\n2۔ لیکن خداوند کا کلام شمعیاہ خدا کے آدمی پر آیا، اور کہا،\n3۔ یہوداہ کے بادشاہ سلیمان کے بیٹے رحبعام اور یہوداہ اور بنیامین کے تمام اسرائیلوں سے کہو،\n4۔ خداوند یہ فرماتا ہے، تم اوپر نہیں جاؤ گے، نہ اپنے بھائیوں سے لڑو گے: ہر آدمی کو اس کے گھر واپس لوٹا، کیونکہ یہ کام میرے ساتھ ہوا ہے۔ اور انہوں نے خداوند کے کلام کی اطاعت کی، اور یربعام کے خلاف جانے سے واپس آ گئے۔\n5۔ اور رحبعام یروشلم میں مقیم رہا، اور یہوداہ میں دفاع کے لیے شہر بنائے۔\n6۔ اس نے بیت لحم، ایتام، اور ٹیکوا بھی بنایا،\n7۔ اور بیثزور، اور شوکو، اور عدولام،\n8۔ اور گث، اور مریشاہ، اور زف،\n9۔ اور ادورائیم، اور لاخش، اور عزیقا،\n10۔ اور زورح، اور ایجالون، اور ہبرون، جو یہوداہ اور بنیامین میں باڑ والے شہروں میں ہیں۔\n11۔ اور اس نے قلعے مضبوط کیے، اور ان میں کپتان، خوراک اور تیل و شراب کا ذخیرہ رکھا۔\n12۔ اور ہر کئی شہروں میں ڈھالیں اور نیزے رکھے، اور انہیں بہت مضبوط بنایا، یہوداہ اور بنیامین اس کے ساتھ تھے۔\n13۔ اور وہ کاهن اور لاوی جو پورے اسرائیل میں تھے، اپنے تمام ساحلوں سے اس کے پاس آئے۔ {resource...: عبرانی۔ خود کو اس کے سامنے پیش کیا}\n14۔ کیونکہ لاویوں نے اپنے مضافات اور ملکیت چھوڑ دی، اور یہوداہ اور یروشلم آ گئے: کیونکہ یربعام اور اس کے بیٹوں نے انہیں خداوند کے سامنے کاہن کے عہدے کو انجام دینے سے نکال دیا تھا:\n15۔ اور اس نے اسے بلند مقامات، شیطانوں اور بچھڑیوں کے لیے پادری مقرر کیے۔\n16۔ اور ان کے بعد اسرائیل کے تمام قبائل میں سے جنہوں نے اسرائیل کے خداوند خدا کی تلاش کے لیے دل لگا دیے، یروشلم آئے تاکہ اپنے باپ اجداد کے خداوند خدا کے لیے قربانی دیں۔\n17۔ یوں انہوں نے یہوداہ کی بادشاہی کو مضبوط کیا، اور سلیمان کے بیٹے رحبعام کو تین سال مضبوط بنایا: تین سال تک وہ داؤد اور سلیمان کے راستے میں چلتے رہے۔\n18۔ اور رحبعام نے اسے محالات، یرموتھ کے بیٹے داؤد کی بیٹی، اور ابیحیل، جو یسیسی کے بیٹے ایلیاب کی بیٹی تھی، کو بیوی بنایا؛\n19۔ جس سے ان کے بچے ہوئے؛ یسوع، اور شمریہ، اور زحام۔\n20۔ اور اس کے بعد اس نے ابشالوم کی بیٹی ماخاہ کو لیا؛ جس سے اسے ابیجہ، عطائی، زیزا، اور شلومیت پیدا ہوئے۔ {معخا: اسے یوریل کی بیٹی میخایا بھی کہا جاتا ہے}\n21۔ اور رحبعام نے ابسالوم کی بیٹی ماخاہ کو اپنی تمام بیویوں اور کنیزوں سے زیادہ محبت کی: (کیونکہ اس نے اٹھارہ بیویاں اور تین سو کنیزیں رکھی تھیں؛ اور اس کے بیس اور آٹھ بیٹے اور تین سو بیٹیاں پیدا ہوئیں۔)\n22۔ اور رحبعام نے ابیاہ، ماخاہ کے بیٹے کو سردار بنایا، {اپنے بھائیوں میں حکمران بننے کے لیے} کیونکہ {اس نے سوچا} کہ وہ اسے بادشاہ بنائے گا۔\n23۔ اور اس نے دانشمندی سے کام کیا، اور اپنے تمام بچوں کو یہوداہ اور بنیامین کے تمام ملکوں میں، ہر باڑ والے شہر میں تقسیم کر دیا، اور انہیں فراوانی سے خوراک دی۔ اور وہ بہت سی بیویاں چاہتا تھا۔ {کئی بیویاں: عبرانی۔ بیویوں کی کثرت}","1۔ اور ایسا ہوا، جب رحبعام نے بادشاہی قائم کی اور خود کو مضبوط کیا، تو اس نے خداوند کے قانون اور اپنے ساتھ تمام اسرائیل کو چھوڑ دیا۔\n2۔ اور ایسا ہوا، {کہ} بادشاہ رحبعام کے پانچویں سال میں مصر کے بادشاہ شیشاک یروشلم کے خلاف آئے، کیونکہ انہوں نے خداوند کے خلاف زیادتی کی تھی،\n3۔ بارہ سو رتھ اور تین لاکھ سوار سوار تھے: اور وہ لوگ بے شمار تھے جو اس کے ساتھ مصر سے نکلے؛ لوبمز، سوکیمز، اور ایتھوپین۔\n4۔ اور اس نے وہ باڑ والے شہر لے لیے جو {یہوداہ سے متعلق} تھے، اور یروشلم آیا۔\n5۔ پھر شمعیاہ نبی رحبعام آیا، اور یہوداہ کے شہزادوں کے پاس جو شیشک کی وجہ سے یروشلم جمع ہوئے تھے، اور ان سے کہا، خداوند نے فرمایا، تم نے مجھے چھوڑ دیا، اور اسی لیے میں نے تمہیں شیشک کے ہاتھ میں چھوڑ دیا۔\n6۔ جس پر اسرائیل کے شہزادے اور بادشاہ نے خود کو عاجز کیا؛ اور انہوں نے کہا، خداوند راستباز ہے۔\n7۔ اور جب خداوند نے دیکھا کہ وہ خود کو عاجز کر رہے ہیں، تو خداوند کا کلام شمعیاہ کے پاس آیا، کہنے لگا، انہوں نے خود کو عاجز کر دیا ہے؛ {لہٰذا} میں انہیں تباہ نہیں کروں گا، لیکن انہیں کچھ نجات دوں گا؛ اور میرا غصہ شیشک کے ہاتھ سے یروشلم پر نہیں برسائے گا۔ {کچھ: یا، تھوڑی دیر کے لیے}\n8۔ پھر بھی وہ اس کے خادم ہوں گے؛ تاکہ وہ میری خدمت اور ملکوں کی سلطنتوں کی خدمت کو جان سکیں۔\n9۔ یوں مصر کے بادشاہ شیشاک یروشلم کے خلاف آئے اور خداوند کے گھرانے کے خزانے اور بادشاہ کے گھر کے خزانے لے لیے؛ اس نے سب کچھ لے لیا: اس نے وہ سونے کی ڈھالیں بھی لے گئیں جو سلیمان نے بنائی تھیں۔\n10۔ اس کے بجائے بادشاہ رحبعام نے پیتل کے ڈھال بنائے اور انہیں محافظ کے سردار کے حوالے کر دیا، جو بادشاہ کے گھر کے داخلی راستے پر تھا۔\n11۔ اور جب بادشاہ خداوند کے گھر میں داخل ہوا، تو محافظ آیا اور انہیں لے آیا اور دوبارہ گارڈ چیمبر میں لے آیا۔\n12۔ اور جب اس نے خود کو عاجز کیا، تو خداوند کا غضب اس سے منہ موڑ گیا، کہ وہ اسے مکمل طور پر تباہ نہیں کرے گا: اور یہوداہ میں بھی سب کچھ ٹھیک رہا۔ {اور اور...: یا، اور پھر بھی یہوداہ میں اچھی چیزیں تھیں}\n13۔ یوں بادشاہ رحبعام نے یروشلم میں خود کو مضبوط کیا اور حکومت کی: کیونکہ رحبعام ایک اور چالیس سال کا تھا جب اس نے حکومت شروع کی، اور اس نے سترہ سال یروشلم میں حکومت کی، وہ شہر جسے خداوند نے اسرائیل کی تمام قبائل میں سے منتخب کیا تھا تاکہ وہاں اپنا نام رکھا جا سکے۔ اور اس کی والدہ کا نام نعمہ ایک عمونیٹیس تھا۔\n14۔ اور اس نے برائی کی، کیونکہ اس نے اپنے دل کو خداوند کی تلاش کے لیے تیار نہیں کیا۔ {تیار: یا، طے شدہ}\n15. اب رحبعام کے اعمال، پہلے اور آخر، کیا وہ شمعیاہ نبی کی کتاب اور عیدو غیب گو کی کتاب میں نسب نامے کے بارے میں نہیں لکھے گئے؟ اور رحبعام اور یربعام کے درمیان مسلسل جنگیں ہوتی رہیں۔ {کتاب: عبرانی۔ الفاظ}\n16۔ اور رحبعام اپنے باپ و اجداد کے ساتھ سو گیا، اور داؤد کے شہر میں دفن کیا گیا: اور اس کا بیٹا ابیاہ اس کی جگہ حکومت کرنے لگا۔ {ابیجہ: جسے ابیجام بھی کہا جاتا ہے}","1۔ اب بادشاہ یربعام کے اٹھارہویں سال میں ابییاہ نے یہوداہ پر حکومت شروع کی۔\n2۔ انہوں نے یروشلم میں تین سال حکومت کی۔ اس کی والدہ کا نام بھی میخایا تھا، جو یوریل آف گبعیہ کی بیٹی تھی۔ اور ابیاہ اور یربعام کے درمیان جنگ ہوئی۔\n3۔ اور ابیاہ نے بہادر جنگجوؤں کی فوج کے ساتھ جنگ ترتیب دی، {حتیٰ کہ} چار لاکھ منتخب مردوں کے ساتھ: یربعام نے بھی آٹھ لاکھ منتخب مردوں کے ساتھ اس کے خلاف جنگ ترتیب دی، {جو بہادر اور طاقتور لوگ تھے}۔ {ابیجہ سیٹ: عبرانی۔ ابیجہ ایک ساتھ بندھے ہوئے}\n4۔ اور ابییاہ پہاڑ زمرایم پر کھڑا ہوا، جو افرایم پہاڑ میں ہے، اور کہا، اے یربعام، اور تمام اسرائیل، میری بات سنو؛\n5. کیا تمہیں معلوم نہیں ہونا چاہیے کہ اسرائیل کے خداوند خدا نے اسرائیل کی بادشاہی ہمیشہ کے لیے داؤد کو دی، {حتیٰ کہ} اسے اور اس کے بیٹوں کو نمک کے عہد کے ذریعے بھی؟\n6۔ پھر بھی یربعام، نیباط کا بیٹا، سلیمان کے خادم جو داؤد کا خادم تھا، زندہ ہو گیا ہے اور اپنے رب کے خلاف بغاوت کر دیا ہے۔\n7۔ اور اس کے پاس بیکار لوگ جمع ہوئے، بلیال کے بچے، اور انہوں نے رحبعام کے بیٹے سلیمان کے خلاف مضبوط ہو گئے، جب رحبعام جوان اور نرم دل تھا اور ان کا مقابلہ نہ کر سکا۔\n8۔ اور اب تم سوچتے ہو کہ خداوند کی بادشاہی کا مقابلہ کرو گے جو داؤد کے بیٹوں کے ہاتھ میں ہے؛ اور تم بہت بڑی تعداد میں ہو، اور تمہارے ساتھ سنہری بچھڑے بھی ہیں، جنہیں یربعام نے تمہیں دیوتاؤں کے طور پر بنایا۔\n9۔ کیا تم نے خداوند کے کاہنوں، ہارون کے بیٹوں، اور لاویوں کو نکال کر خود کو [دوسرے] زمینوں کی قوموں کی طرح کاہن نہیں بنایا؟ تاکہ جو بھی ایک نوجوان بیل اور سات مینڈوں کے ساتھ خود کو مقدس کرے، {وہی} وہ {جو خدا نہیں} کا پادری بن سکے۔ {تقدس کے لیے...: عبرانی۔ اپنے ہاتھ کو بھرنے کے لیے}\n10۔ لیکن جہاں تک ہمارا تعلق ہے، خداوند ہمارا خدا ہے، اور ہم نے اسے نہیں چھوڑا؛ اور وہ کاہن، جو خداوند کی خدمت کرتے ہیں، ہارون کے بیٹے ہیں، اور لاوی اپنے کام پر انتظار کرتے ہیں:\n11۔ اور وہ ہر صبح اور ہر شام خداوند کے لیے جلائی گئی قربانیاں اور میٹھا لوبان جلاتے ہیں: شیو بریڈ بھی {انہیں صاف میز پر ترتیب میں رکھا جاتا ہے}؛ اور سونے کی شمعدانی اور اس کے چراغوں کے ساتھ، جو ہر شام جلتی ہے: کیونکہ ہم خداوند اپنے خدا کی ذمہ داری سنبھالتے ہیں؛ لیکن تم نے اسے چھوڑ دیا ہے۔\n12۔ اور دیکھو، خدا خود ہمارے ساتھ ہے [ہمارا} کپتان، اور اس کے پادری بگل بجا کر تمہارے خلاف خبردار کر رہے ہیں۔ اے بنی اسرائیل کو، اپنے باپ اجداد کے خداوند خدا کے خلاف نہ لڑو؛ کیونکہ تم خوشحال نہیں ہو گے۔\n13۔ لیکن یربعام نے ان کے پیچھے ایک گھات لگا کر حملہ کر دیا: یوں وہ یہوداہ کے سامنے تھے، اور حملہ ان کے پیچھے تھا۔\n14۔ اور جب یہوداہ نے پیچھے مڑ کر دیکھا، دیکھو، جنگ پہلے اور پیچھے تھی: اور انہوں نے خداوند کو پکارا، اور کاہنوں نے بگل بجائے۔\n15۔ پھر یہوداہ کے لوگوں نے چیخ ماری: اور جب یہوداہ کے لوگوں نے چیخ ماری، تو ایسا ہوا کہ خدا نے ابییاہ اور یہوداہ کے سامنے یربعام اور تمام اسرائیل کو شکست دی۔\n16۔ اور بنی اسرائیل یہوداہ کے سامنے بھاگ گئے: اور خدا نے انہیں ان کے ہاتھ میں دے دیا۔\n17۔ اور ابیاہ اور اس کے لوگ نے انہیں بڑے قتل عام سے مار ڈالا: یوں اسرائیل کے پانچ لاکھ منتخب مرد مارے گئے۔\n18۔ یوں اس وقت بنی اسرائیل کو قابو میں کیا گیا، اور یہوداہ کے بچے غالب آئے، کیونکہ وہ اپنے باپ اجداد کے خداوند خدا پر بھروسہ کرتے تھے۔\n19۔ اور ابیاہ نے یربعام کا پیچھا کیا اور اس سے شہر لے لیے، بیت تھل اور ان کے قصبے، یشانہ اور ان کے قصبوں سے، اور افرائین کو ان کے قصبوں سے۔\n20۔ ابے کے زمانے میں یربعام دوبارہ طاقت حاصل نہ کر سکا: اور خداوند نے اسے مارا، اور وہ مر گیا۔\n21۔ لیکن ابیاہ طاقتور ہو گیا، اس نے چودہ بیویاں شادی کیں، اور بیس دو بیٹے اور سولہ بیٹیاں پیدا کیں۔\n22. اور ابیاہ کے باقی اعمال، اس کے طریقے، اور اس کے اقوال نبی ایدو کی کہانی میں لکھے گئے ہیں۔","1۔ تو ابیاہ اپنے باپ اجداد کے ساتھ سو گیا، اور انہوں نے اسے داؤد کے شہر میں دفن کیا: اور اس کا بیٹا آسا اس کی جگہ حکومت کرنے لگا۔ ان کے زمانے میں زمین دس سال تک پرسکون تھی۔\n2۔ اور آسا نے وہ کیا جو خداوند اپنے خدا کی نظر میں اچھا اور درست تھا:\n3۔ کیونکہ اس نے عجیب دیوتاؤں کے قربان گاہیں اور اونچی جگہیں ہٹا دیں، اور مجسمے توڑ دیے، اور جھنڈ کاٹ دیے: {تصاویر: عبرانی۔ مجسمے}\n4۔ اور یہوداہ کو حکم دیا کہ وہ اپنے باپ اجداد کے خداوند خدا کی تلاش کرے، اور قانون و حکم پر عمل کرے۔\n5۔ اس نے یہوداہ کے تمام شہروں میں سے اونچی جگہیں اور مجسمے لے لیے، اور بادشاہی اس کے سامنے خاموش ہو گئی۔ {تصاویر: عبرانی۔ سن امیجز}\n6۔ اور اس نے یہوداہ میں باڑ والے شہر بنائے: کیونکہ زمین کو آرام ملا، اور ان سالوں میں اس کے پاس کوئی جنگ نہیں تھی؛ کیونکہ خداوند نے اسے آرام دیا تھا۔\n7۔ اسی لیے اس نے یہوداہ سے کہا، آؤ یہ شہر تعمیر کریں، اور ان کے گرد دیواریں، برج، دروازے اور سلاخیں بناؤ، جب تک زمین ابھی ہمارے سامنے ہے؛ کیونکہ ہم نے خداوند اپنے خدا کی تلاش کی ہے، ہم نے اس کی تلاش کی ہے، اور اس نے ہمیں ہر طرف آرام دیا ہے۔ تو انہوں نے تعمیر کی اور ترقی کی۔\n8۔ اور آسا کے پاس ایک فوج تھی جس میں نشانے اور نیزے تھے، یہوداہ سے تین لاکھ تھے؛ اور بنیامین سے، جو ڈھالیں نکالتا اور کمانیں نکالتا، دو لاکھ چار ہزار: یہ سب بہادر لوگ تھے۔\n9۔ اور ان کے خلاف زراح ایتھوپیائی ہزار ہزار کی فوج اور تین سو رتھ لے کر آیا؛ اور مریشاہ آیا۔\n10۔ پھر آسا اس کے خلاف نکلا، اور انہوں نے مارشاہ میں زفاتھا کی وادی میں صف بندی کی۔\n11۔ اور آسا نے خداوند اپنے خدا سے پکارا، اور کہا، اے خداوند، تیری مدد کے لیے کچھ نہیں، چاہے وہ بہت سے ہوں یا ان کے پاس جن کے پاس کوئی طاقت نہیں: اے خداوند ہمارے خدا، ہماری مدد فرما؛ کیونکہ ہم تیرے اوپر آرام کرتے ہیں، اور تیرے نام پر ہم اس ہجوم کے خلاف جا رہے ہیں۔ اے خداوند، تو ہمارا خدا ہے؛ انسان تم پر غالب نہ آئے۔ {آدمی: یا، فانی انسان}\n12۔ تو خداوند نے ایتھوپیائیوں کو آسا اور یہوداہ کے سامنے شکست دی؛ اور ایتھوپین فرار ہو گئے۔\n13۔ اور آسا اور اس کے ساتھ موجود لوگ ان کا پیچھا کرتے ہوئے جرار تک پہنچے: اور ایتھوپیا کے لوگ شکست کھا گئے، وہ خود کو سنبھال نہ سکے؛ کیونکہ وہ خداوند کے سامنے اور اس کے لشکر کے سامنے تباہ ہو گئے؛ اور انہوں نے بہت سا مال غنیمت اٹھایا۔ {تباہ شدہ: عبرانی۔ ٹوٹا ہوا}\n14۔ اور انہوں نے جیرار کے ارد گرد کے تمام شہروں کو تباہ کر دیا؛ کیونکہ خداوند کا خوف ان پر چھا گیا، اور انہوں نے تمام شہروں کو تباہ کر دیا؛ کیونکہ ان میں بہت زیادہ مال تھا۔\n15۔ انہوں نے مویشیوں کے خیمے بھی مارے، بھیڑیں اور اونٹ بڑی مقدار میں لے گئے، اور یروشلم واپس چلے گئے۔","1۔ اور خدا کی روح عزریہ، عودید کے بیٹے پر آئی:\n2۔ اور وہ آسا سے ملنے نکلا اور اس سے کہا، اے آسا اور تمام یہوداہ اور بنیامین کو سنو؛ خداوند تمہارے ساتھ ہے، جب تک تم اس کے ساتھ ہو؛ اور اگر تم اسے تلاش کرو گے، تو وہ تم میں ملے گا؛ لیکن اگر تم اسے چھوڑ دو، تو وہ تمہیں چھوڑ دے گا۔ {ملنے کے لیے...: عبرانی۔ آسا سے پہلے}\n3۔ اب ایک طویل عرصے سے اسرائیل سچے خدا کے بغیر، بغیر کسی تعلیم دینے والے پادری کے، اور بغیر قانون کے رہا ہے۔\n4۔ لیکن جب وہ اپنی مصیبت میں اسرائیل کے خداوند خدا کی طرف مڑے اور اسے تلاش کیا، تو وہ ان سے مل گیا۔\n5۔ اور ان وقتوں میں جو باہر جاتا تھا اس کے لیے کوئی امن نہیں تھا، نہ ہی آنے والے کے لیے، بلکہ تمام ملکوں کے باشندوں پر شدید پریشانیاں تھیں۔\n6۔ اور قوم سے قوم اور شہر شہر سے تباہ ہو گئی: کیونکہ خدا نے انہیں ہر قسم کی مصیبتوں سے پریشان کیا۔ {تباہ شدہ: عبرانی۔ ٹکڑوں میں مارا گیا}\n7۔ اس لیے مضبوط رہو، اور اپنے ہاتھ کمزور نہ ہوں، کیونکہ تمہارا کام انعام ملے گا۔\n8۔ اور جب آسا نے یہ الفاظ سنے، اور نبی عودید کی پیش گوئی سنی، تو اس نے ہمت کی، اور یہوداہ اور بنیامین کی تمام زمینوں سے، اور ان شہروں سے جو اس نے کوہ افرائیم سے چھین لیے تھے، اور خداوند کے مذبح کو دوبارہ زندہ کیا، جو خداوند کے برآمدے کے سامنے تھا۔ {ابومینبل...: عبرانی۔ ابومینیشن\n9۔ اور اس نے تمام یہوداہ اور بنیامین کو، اور ان کے ساتھ اجنبیوں کو افرائیم اور منسی سے اور شمعون سے جمع کیا، کیونکہ وہ اسرائیل سے کثرت سے اس کے پاس آئے، جب انہوں نے دیکھا کہ خداوند اس کا خدا اس کے ساتھ ہے۔\n10۔ یوں وہ سب یروشلم میں تیسرے مہینے جمع ہوئے، آسا کی حکومت کے پندرہویں سال میں۔\n11۔ اور انہوں نے اسی وقت خداوند کو اس مال غنیمت میں سے پیش کیا جو انہوں نے لائی تھی، سات سو بیل اور سات ہزار بھیڑیں۔ {وہی...: عبرانی۔ اس دن}\n12۔ اور انہوں نے ایک عہد کیا کہ وہ اپنے باپوں کے خداوند خدا کو پورے دل اور جان سے تلاش کریں؛\n13۔ جو بھی اسرائیل کے خداوند خدا کی تلاش نہیں کرے گا، اسے قتل کر دیا جائے، چاہے وہ چھوٹا ہو یا بڑا، چاہے مرد ہو یا عورت۔\n14۔ اور وہ بلند آواز میں، چیخ و پکار، بگل اور کارنیٹس کے ساتھ خداوند سے قسم کھاتے ہیں۔\n15۔ اور پورا یہوداہ اس قسم پر خوش ہوا: کیونکہ انہوں نے پورے دل سے قسم کھائی تھی اور پوری خواہش سے اس کی تلاش کی تھی؛ اور وہ ان میں سے پایا گیا: اور خداوند نے انہیں آس پاس آرام دیا۔\n16۔ اور {ماخاہ} کے بارے میں، جو آسا بادشاہ کی ماں تھی، اس نے اسے {ملکہ} ہونے سے ہٹا دیا، کیونکہ اس نے ایک جھنڈ میں بت بنایا تھا: اور آسا نے اس کا بت کاٹ کر {اسے} کو روند ڈالا، اور کدرون ندی پر جلا دیا۔ {ماں: یعنی، دادی} {آئیڈل: عبوری۔ ہارر}\n17۔ لیکن بلند مقامات اسرائیل سے نہیں چھین لیے گئے: پھر بھی آسا کا دل اس کے تمام دنوں میں کامل رہا۔\n18۔ اور اس نے خدا کے گھر میں وہ چیزیں لائی جو اس کے والد نے وقف کی تھیں، اور جو اس نے خود وقف کی تھیں، چاندی، سونا اور برتن۔\n19۔ اور آسا کی حکومت کے پانچویں تیسویں سال تک مزید کوئی جنگ نہیں ہوئی۔","1۔ آسا بعشا کے حکومت کے چھٹے اور تیسویں سال میں اسرائیل کے بادشاہ نے یہوداہ کے خلاف آ کر رامہ تعمیر کی، تاکہ کوئی بھی یہوداہ کے بادشاہ آسا کے پاس باہر نہ جا سکے۔\n2۔ پھر آسا نے خداوند کے گھر اور بادشاہ کے گھر کے خزانے سے چاندی اور سونا نکالا، اور شام کے بادشاہ بن حداد کو بھیجا، جو دمشق میں رہتا تھا، اور کہا، {دمشق: عبرانی۔ دارمیسیک}\n3. {میرے اور تمہارے درمیان ایک اتحاد ہے}، جیسے {تھا} میرے والد اور تمہارے والد کے درمیان: دیکھو، میں نے تمہیں چاندی اور سونا بھیجا ہے؛ جاؤ، اسرائیل کے بادشاہ بعشا سے اپنی وفاداری توڑ دو، تاکہ وہ مجھ سے دور ہو جائے۔\n4۔ اور بن حداد نے بادشاہ آسا کی بات مانی، اور اپنی فوجوں کے کپتانوں کو اسرائیل کے شہروں پر بھیجا؛ اور انہوں نے ایجون، دان، اور ابیلمایم، اور نفتالی کے تمام ذخیرے شہروں کو شکست دی۔ {اس کا: عبری۔ جو اس کے تھے}\n5۔ اور جب بعشا نے سنا تو اس نے رامہ کی تعمیر چھوڑ دی اور اپنا کام ختم کر دیا۔\n6۔ پھر آسا بادشاہ نے پورا یہوداہ لے لیا؛ اور انہوں نے رامہ کے پتھر اور ان کے لکڑی کو اٹھا لیا، جس سے بعشا تعمیر کر رہا تھا؛ اور اس نے ان کے ساتھ گبا اور مزپاہ تعمیر کیے۔\n7۔ اور اسی وقت حنانی پیش گو یہوداہ کے بادشاہ آسا کے پاس آیا اور اس سے کہا، کیونکہ تم نے شام کے بادشاہ پر بھروسہ کیا ہے، اور اپنے خدا خداوند پر بھروسہ نہیں کیا، اس لیے شام کے بادشاہ کی فوج تیرے ہاتھ سے نکل گئی ہے۔\n8۔ کیا ایتھوپیائی اور لوبیم ایک بڑی فوج نہیں تھے، جن کے پاس بہت سے رتھ اور گھڑ سوار تھے؟ لیکن چونکہ تو نے خداوند پر بھروسہ کیا، اس نے انہیں تمہارے ہاتھ میں دے دیا۔ {ایک بڑا: عبوری۔ کثرت سے}\n9۔ کیونکہ خداوند کی آنکھیں پوری زمین میں ادھر ادھر دوڑتی ہیں، تاکہ وہ ان لوگوں کے لیے مضبوط ہو جائے جن کا دل اس کے لیے کامل ہے۔ یہاں تم نے بے وقوفی کی ہے: اس لیے اب سے تمہاری جنگیں ہوں گی۔ {دکھانا...: یا، ان کے ساتھ مضبوطی سے تھامنا وغیرہ}\n10۔ پھر آسا غیب گو پر غصہ ہوا اور اسے قید خانے میں ڈال دیا؛ کیونکہ {وہ} اس {چیز} کی وجہ سے اس پر غصے میں تھا۔ اور آسا نے ایک ہی وقت میں {کچھ} لوگوں پر ظلم کیا۔ {دبائے ہوئے: عبرانی۔ کچل دیا گیا}\n11۔ اور دیکھو، آسا کے اعمال، پہلے اور آخری، وہ یہوداہ اور اسرائیل کے بادشاہوں کی کتاب میں لکھے گئے ہیں۔\n12۔ اور آسا اپنی حکومت کے انتالیسویں سال میں اپنے پیروں میں بیمار ہو گیا، یہاں تک کہ اس کی بیماری {عظیم} ہو گئی: پھر بھی اپنی بیماری میں اس نے خداوند سے نہیں بلکہ طبیبوں کی طرف رجوع کیا۔\n13۔ اور آسا نے اپنے باپ دادا کے ساتھ سونا اور اپنی حکومت کے ایک اور چالیسویں سال میں وفات پا گئی۔\n14۔ اور انہوں نے اسے اس کے اپنے قبروں میں دفن کیا، جو اس نے داؤد کے شہر میں اپنے لیے بنائی تھی، اور اسے اس بستر میں لٹایا جو میٹھے خوشبوؤں اور مختلف قسم کے مصالحوں سے بھرا ہوا تھا جو داروسازوں کے فن سے تیار کیے گئے تھے: اور اس کے لیے بہت بڑی آگ لگائی۔ {نے بنایا: عبرانی۔ کھود چکا تھا}","1۔ اور اس کا بیٹا یہوشافاط نے اس کی جگہ حکومت کی، اور اسرائیل کے خلاف مضبوط ہوا۔\n2۔ اور اس نے یہوداہ کے تمام باڑ والے شہروں میں فوجیں تعینات کیں، اور یہوداہ کی سرزمین اور افرائیم کے شہروں میں بھی چھاؤنیاں قائم کیں، جو اس کے والد آسا نے قبضے میں لیے تھے۔\n3۔ اور خداوند یہوشافاط کے ساتھ تھا، کیونکہ اس نے اپنے باپ داؤد کے پہلے راستوں پر چلنا شروع کیا اور بعلیم کی طرف نہیں گیا؛ {کا...: یا، اپنے والد کا، اور داؤد کا}\n4۔ بلکہ اس نے اپنے باپ کے {خداوند} خدا کی طرف رجوع کیا، اور اس کے احکامات پر عمل کیا، نہ کہ اسرائیل کے اعمال کے مطابق۔\n5۔ لہٰذا خداوند نے بادشاہی کو اپنے ہاتھ میں قائم کیا؛ اور تمام یہوداہ جو یہوشافات کے لیے تحفے لائے گئے؛ اور ان کے پاس دولت اور عزت وافر مقدار تھی۔ {لایا گیا: عبوری۔ دیا گیا}\n6۔ اور اس کا دل خداوند کے راستوں میں بلند ہوا: اس کے علاوہ اس نے یہوداہ سے اونچی جگہیں اور درختیں چھین لیں۔ {تھا...: یعنی، حوصلہ افزائی کی گئی}\n7۔ اپنی حکومت کے تیسرے سال میں اس نے اپنے شہزادوں کو بھیجا، {حتیٰ کہ} بن حیل، عوبدیہ، زکریا، نیتھانیل، اور میخایا کو یہوداہ کے شہروں میں تعلیم دینے کے لیے۔\n8۔ اور ان کے ساتھ {اس نے بھیجا} لاوی، {حتی} شمعیہ، اور نیتھانیا، اور زبادیہ، اور عساہیل، اور شیمیرموت، اور یہوناتان، اور ادونیہ، اور توبییہ، اور توبادونیاہ، لاوی؛ اور ان کے ساتھ الیشاما اور یہورام، پادری۔\n9۔ اور انہوں نے یہوداہ میں تعلیم دی، اور اپنے ساتھ خداوند کے قانون کی کتاب رکھی، اور یہوداہ کے تمام شہروں میں گھومتے ہوئے لوگوں کو تعلیم دی۔\n10۔ اور خداوند کا خوف یہوداہ کے ارد گرد کی تمام ملکیتوں پر چھا گیا، اس لیے انہوں نے یہوشافاط کے خلاف کوئی جنگ نہ کی۔ {گرنا: عبرانی۔ تھا}\n11۔ اسی طرح {کچھ} فلسطینیوں نے یہوشافات کے تحفے اور چاندی کا خراج دیا؛ اور عربوں نے اسے ریوڑ دیے، سات ہزار سات سو مینڈے، اور سات ہزار سات سو بکریاں۔\n12۔ اور یہوشافاط نے بہت زیادہ پرفارم کیا؛ اور اس نے یہوداہ میں قلعے اور دکانوں کے شہر تعمیر کیے۔ {قلعے: یا، محل}\n13۔ اور اس کے پاس یہوداہ کے شہروں میں بہت کام تھا: اور جنگجو، بہادر آدمی، یروشلم میں تھے۔\n14۔ اور یہ ان کی تعداد ان کے آباؤ اجداد کے گھر کے مطابق ہے: یہوداہ کے، ہزاروں کے کپتان؛ ادناہ سردار، اور اس کے ساتھ تین لاکھ بہادر آدمی۔\n15۔ اور اس کے ساتھ کپتان یہوحانان تھا، اور اس کے ساتھ دو لاکھ چار ہزار تھے۔ {اگلا...: عبرانی۔ اس کے ہاتھوں سے}\n16۔ اور اس کے بعد عماسیہ، زکری کا بیٹا تھا، جس نے خوش دلی سے خود کو خداوند کے سامنے پیش کیا؛ اور اس کے ساتھ دو لاکھ بہادر آدمی۔\n17۔ اور بنیامین کے بارے میں؛ ایلیادا، ایک بہادر آدمی، اور اس کے ساتھ دو لاکھ کمان اور ڈھال سے مسلح آدمی۔\n18۔ اور اس کے بعد یہوزاباد تھا، اور اس کے ساتھ ایک لاکھ چولیس ہزار جنگ کے لیے تیار تھے۔\n19۔ یہ بادشاہ کی خدمت کرتے تھے، ان کے علاوہ جنہیں بادشاہ نے پورے یہوداہ کے باڑ والے شہروں میں رکھا تھا۔","1۔ اب یہوشافات کے پاس دولت اور عزت کی فراوانی تھی، اور اس نے اہاب کے ساتھ رشتہ قائم کیا۔\n2. اور {کچھ وقت} بعد وہ اخاب کے پاس سامریہ چلا گیا۔ اور اہاب نے اس کے لیے بھیڑ اور بیل کثرت سے ذبح کیے، اور اپنے ساتھ موجود لوگوں کے لیے بھیڑ اور بیل مارے، اور اسے قائل کیا کہ وہ اس کے ساتھ راموتجلعاد چڑھ جائے۔ {بعد...: عبرانی۔ سالوں کے آخر میں}\n3۔ اور اسرائیل کے بادشاہ اہاب نے یہوداہ کے بادشاہ یہوشافات سے کہا، کیا تم میرے ساتھ راموتجلعاد جاؤ گے؟ اور اس نے جواب دیا، میں تمہاری طرح ہوں، اور میرے لوگ تمہارے لوگوں کی طرح ہیں؛ اور {ہم تمہارے ساتھ ہوں گے} جنگ میں۔\n4۔ اور یہوشافاط نے اسرائیل کے بادشاہ سے کہا، آج خداوند کے کلام سے پوچھو، میں دعا کرتا ہوں۔\n5۔ اسی لیے اسرائیل کے بادشاہ نے چار سو نبیوں کو جمع کیا اور ان سے کہا، کیا ہم راموتگیلاد جائیں جنگ کے لیے، یا میں برداشت کروں؟ اور انہوں نے کہا، اوپر جاؤ؛ کیونکہ خدا اسے بادشاہ کے ہاتھ میں دے گا۔\n6۔ لیکن یہوشافاط نے کہا، {کیا} یہاں خداوند کا کوئی نبی نہیں ہے جو ہم اس سے پوچھ گچھ کر سکیں؟ {اس کے علاوہ: عبرانی۔ ابھی، یا اس سے بھی زیادہ}\n7۔ اور اسرائیل کے بادشاہ نے یہوشافات سے کہا، {ابھی بھی ایک آدمی ہے}، جس سے ہم خداوند سے پوچھ سکتے ہیں: لیکن میں اس سے نفرت کرتا ہوں؛ کیونکہ اس نے کبھی مجھے نیکی کی پیش گوئی نہیں کی، بلکہ ہمیشہ برائی کی پیش گوئی کی: وہی میکایا ہے جو ایملا کا بیٹا ہے۔ اور یہوشافاط نے کہا، بادشاہ ایسا نہ کہے۔\n8۔ اور اسرائیل کے بادشاہ نے اپنے ایک افسر کو بلایا اور کہا، جلدی سے میکائیا، املا کے بیٹے کو لے آؤ۔ {افسران: یا، خواجہ سرا} {لے آؤ...: عببرانی۔ جلدی کریں}\n9۔ اور اسرائیل کا بادشاہ اور یہوداہ کا یہوشافاط، بادشاہ، دونوں اپنے تخت پر بیٹھے تھے، {اپنے} کے لباس میں، اور وہ سامریہ کے دروازے کے دروازے کے دروازے پر ایک خالی جگہ پر بیٹھے تھے؛ اور تمام انبیاء نے ان سے پہلے نبوت کی تھی۔ {خلا...: یا، فرش}\n10۔ اور حنانا کے بیٹے زدیقیاہ نے اسے لوہے کے سینگ بنائے اور کہا، خداوند یوں فرماتا ہے، ان سے تو شام کو دھکیل دو جب تک وہ نگل نہ جائیں۔ {وہ...: عبرانی۔ تم انہیں کھا جاتے ہو}\n11۔ اور تمام نبیوں نے یہ پیش گوئی کی، کہا، راموتجلعاد جاؤ اور خوش ہو جاؤ: کیونکہ خداوند بادشاہ کے ہاتھ میں دے گا۔\n12۔ اور وہ پیغامبر جو میکعیاہ کو بلانے گیا تھا، اس نے اس سے کہا، دیکھو، انبیاء کے الفاظ بادشاہ کے لیے اچھے ہونے کا اعلان ایک ساتھ کرتے ہیں؛ لہٰذا، میں تم سے دعا کرتا ہوں کہ تمہارا کلام ان میں سے ایک کی طرح ہو، اور اچھی بات کرو۔ {ساتھ...: عبوری۔ ایک منہ سے}\n13۔ اور میکعیاہ نے کہا، {جیسا کہ خداوند زندہ ہے، جیسا کہ میرا خدا فرمائے، وہی میں بولوں گا۔\n14۔ اور جب وہ بادشاہ کے پاس آیا، تو بادشاہ نے کہا، میکائیا، کیا ہم راموتجلعاد جائیں جنگ کے لیے، یا میں برداشت کروں؟ اور اس نے کہا، اوپر جاؤ اور خوش رہو، اور وہ تمہارے ہاتھ میں دے دیے جائیں گے۔\n15۔ اور بادشاہ نے اس سے کہا، کتنی بار میں تمہیں حکم دوں کہ تم مجھ سے صرف سچ کہو خداوند کے نام پر؟\n16۔ پھر اس نے کہا، میں نے تمام اسرائیل کو پہاڑوں پر بکھرا ہوا دیکھا، جیسے بھیڑیں جن کا کوئی چرواہا نہیں: اور خداوند نے فرمایا، ان کا کوئی مالک نہیں؛ لہٰذا، ہر آدمی کو سکون سے اپنے گھر واپس لوٹنے دیں۔\n17۔ اور اسرائیل کے بادشاہ نے یہوشافات سے کہا، کیا میں نے تمہیں نہیں بتایا کہ وہ مجھے بھلائی کی پیش گوئی نہیں کرے گا بلکہ برائی کرے گا؟ {لیکن برائی: یا، لیکن برائی کے لیے}\n18۔ پھر اس نے کہا، لہٰذا خداوند کا کلام سنو؛ میں نے خداوند کو اس کے تخت پر بیٹھا دیکھا، اور آسمان کی ساری فوج اس کے دائیں ہاتھ اور {بائیں طرف} کھڑی تھی۔\n19۔ اور خداوند نے فرمایا، کون اسرائیل کے بادشاہ آہاب کو آمادہ کرے گا کہ وہ راموتجلعاد پر اوپر جا کر گر جائے؟ اور ایک نے اس انداز میں کہا، اور دوسرا اس طرح کہا۔\n20۔ پھر ایک روح نکلی، اور خداوند کے سامنے کھڑی ہوئی، اور کہا، میں اسے بہکاؤں گا۔ اور خداوند نے اس سے کہا، کس لیے؟\n21۔ اور اس نے کہا، میں باہر جاؤں گا، اور اس کے تمام نبیوں کے منہ میں جھوٹا روح بنوں گا۔ اور {خداوند} نے فرمایا، تو اسے لبھاؤ گے، اور تم بھی کامیاب ہو گے: باہر جاؤ، اور ایسا ہی کرو۔\n22۔ اب دیکھو، خداوند نے ان تمہارے نبیوں کے منہ میں جھوٹا روح ڈال دیا ہے، اور خداوند نے تمہارے خلاف برائی کی ہے۔\n23۔ پھر زدیقیاہ چنانا کا بیٹا قریب آیا، اور میکایا کے گال پر مارا اور کہا، خداوند کی روح مجھ سے کہاں گئی تاکہ وہ تم سے بات کرے؟\n24۔ اور میکائیاہ نے کہا، دیکھو، اس دن تم دیکھو گے جب تم اندرونی کمرے میں جا کر خود کو چھپاؤ گے۔ {into...: یا، چیمبر سے چیمبر میں: عبرانی۔ ایک کمرہ ایک کمرے میں}\n25۔ پھر اسرائیل کے بادشاہ نے کہا، میکائے کو لے جاؤ اور اسے شہر کے گورنر آمون اور بادشاہ کے بیٹے یوآش کے پاس لے جاؤ؛\n26۔ اور کہو، بادشاہ کہتا ہے، اس {آدمی} کو قید میں ڈال دو، اور اسے مصیبت کی روٹی اور مصیبت کے پانی سے کھلاؤ، جب تک میں امن کے ساتھ واپس نہ آؤں۔\n27۔ اور میکعیاہ نے کہا، اگر تم واقعی امن کے ساتھ واپس آؤ گے، تو کیا خداوند نے میرے بارے میں نہیں کہا۔ اور اس نے کہا، سنو، سب لوگ۔\n28۔ تو اسرائیل کا بادشاہ اور یہوشافاط، یہوداہ کا بادشاہ، راموتجلعاد کے پاس گئے۔\n29۔ اور اسرائیل کے بادشاہ نے یہوشافات سے کہا، میں بھیس بدل کر جنگ میں جاؤں گا؛ لیکن اپنے لباس پہنو۔ لہٰذا اسرائیل کے بادشاہ نے بھیس بدل لیا؛ اور وہ لڑائی میں گئے۔\n30۔ اب شام کے بادشاہ نے ان رتھوں کے کپتانوں کو حکم دیا جو اس کے ساتھ تھے، کہہ دیا، چھوٹے یا بڑے سے نہ لڑو، سوائے اسرائیل کے بادشاہ کے۔\n31۔ اور جب رتھوں کے کپتانوں نے یہوشافات کو دیکھا تو انہوں نے کہا، یہ اسرائیل کا بادشاہ ہے۔ لہٰذا وہ اس کے گرد گھیرے ہوئے تاکہ لڑیں: لیکن یہوشفات نے پکارا، اور خداوند نے اس کی مدد کی؛ اور خدا نے انہیں اپنے سے دور کر دیا۔\n32۔ کیونکہ ایسا ہوا کہ جب رتھ کے کپتانوں نے دیکھا کہ وہ اسرائیل کا بادشاہ نہیں ہے، تو وہ اس کا پیچھا کرنے سے پیچھے ہٹ گئے۔ {سے...: عبرانی اس کے بعد سے}\n33۔ اور ایک {یقین} آدمی نے ایک حملے پر کمان نکالی، اور اسرائیل کے بادشاہ کو ہارنس کے جوڑوں کے درمیان مارا، تو اس نے اپنے رتھ والے سے کہا، اپنا ہاتھ گھماؤ، تاکہ تم مجھے لشکر سے باہر لے جاؤ؛ کیونکہ میں زخمی ہوں۔ {ایک منصوبے میں: عبوری۔ اپنی سادگی میں} {درمیان...: عبرانی جوڑوں کے درمیان اور بریسٹ پلیٹ کے درمیان} {زخمی: عبرانی۔ بیمار ہو گیا}\n34۔ اور اس دن جنگ شدت اختیار کر گئی: تاہم اسرائیل کا بادشاہ خود اپنے رتھ میں شامیوں کے خلاف شام تک کھڑا رہا: اور سورج غروب ہونے کے قریب وہ مر گیا۔","1۔ اور یہوشافاط، یہوداہ کا بادشاہ، امن کے ساتھ اپنے گھر واپس آیا۔\n2۔ اور یہو، حنانی غیب گو کا بیٹا، اس سے ملنے باہر گیا اور بادشاہ یہوشافاط سے کہا، کیا تمہیں بدکاروں کی مدد کرنی چاہیے، اور ان سے محبت کرنی چاہیے جو خداوند سے نفرت کرتے ہیں؟ لہٰذا خداوند کے سامنے تم پر غصہ ہے۔\n3۔ پھر بھی تم میں کچھ اچھی باتیں پائی جاتی ہیں، اس میں کہ تم نے زمین سے باغات نکال دیے ہیں، اور اپنے دل کو خدا کی تلاش کے لیے تیار کیا ہے۔\n4۔ اور یہوشافاط یروشلم میں رہا: اور وہ دوبارہ بیئرشبع سے لوگوں کے راستے افرایم کے کوہ پر گیا، اور انہیں ان کے باپ و اجداد کے خداوند خدا کے پاس واپس لے آیا۔ {وہ کہتا ہے...: عببرانی۔ وہ واپس آیا اور باہر چلا گیا}\n5۔ اور اس نے یہوداہ کے تمام باڑ والے شہروں میں شہر بہ شہر منصف مقرر کیے،\n6۔ اور ججوں سے کہا، جو تم کرتے ہو اس پر دھیان رکھو، کیونکہ تم انسان کے لیے نہیں بلکہ خداوند کے لیے فیصلہ کرتے ہو، جو تمہارے ساتھ ہے فیصلے میں۔ {میں...: عبرانی فیصلے کے معاملے میں}\n7۔ اب خداوند کا خوف تم پر نازل ہو؛ ہوشیار رہو اور عمل کرو: کیونکہ خداوند ہمارے خدا کے ساتھ کوئی گناہ نہیں، نہ لوگوں کی عزت ہے، نہ تحفے لینا ہے۔\n8۔ مزید یہ کہ یروشلم میں یہوشافات نے لاویوں کو، اور کاہنوں، اور اسرائیل کے بزرگوں کے سردار کو خداوند کے فیصلے اور جب وہ یروشلم واپس آئے تو جھگڑوں کے لیے مقرر کیا۔\n9۔ اور اس نے انہیں حکم دیا، کہا، \"ایسا ہی کرو گے خداوند کے خوف میں، وفاداری اور کامل دل کے ساتھ۔\n10۔ اور جو بھی وجہ آپ کے بھائیوں میں سے آئے جو اپنے شہروں میں رہتے ہیں، خون اور خون کے درمیان، قانون و حکم، قوانین اور فیصلوں کے درمیان، آپ انہیں خبردار بھی کریں گے کہ وہ خداوند کے خلاف جرم نہیں کرتے، اور {لہٰذا} آپ پر اور آپ کے بھائیوں پر غصہ آئے: یہ کریں، اور آپ گناہ نہیں کریں گے۔\n11۔ اور دیکھو، امریاہ سردار کاہن خداوند کے تمام معاملات میں تم پر حکمرانی کرتا ہے؛ اور زبادیہ، یسماعیل کا بیٹا، یہوداہ خاندان کا حکمران، بادشاہ کے تمام معاملات کے لیے: اور لاوی بھی تمہارے سامنے افسر ہوں گے۔ بہادری سے معاملہ کرو، اور خداوند اچھے لوگوں کے ساتھ ہوگا۔ {معاہدہ...: عبرانی۔ ہمت کرو اور کرو۔","1۔ اس کے بعد یہ بھی ہوا کہ موآب کے بچے اور آمون کے بچے اور ان کے ساتھ عمونیوں کے علاوہ یہوشافات کے خلاف جنگ کے لیے آئے۔\n2۔ پھر کچھ لوگ آئے جنہوں نے یہوشافاط کو کہا، \"سمندر کے پار اس طرف شام سے تمہارے خلاف بڑی فوج آ رہی ہے؛ اور دیکھو، وہ {ہازازونتامار} میں ہیں، جو {ہے} اینگیدی۔\n3۔ اور یہوشافاط ڈر گیا، اور خداوند کی تلاش میں خود کو تیار کیا، اور پورے یہوداہ میں روزہ رکھا۔ {خود: عبرانی۔ اس کا چہرہ}\n4۔ اور یہوداہ نے اکٹھا ہو کر خداوند سے {مدد} مانگی: یہاں تک کہ یہوداہ کے تمام شہروں میں سے وہ خداوند کی تلاش کے لیے آئے تھے۔\n5۔ اور یہوشافاط یہوداہ اور یروشلم کی جماعت میں، خداوند کے گھر میں، نئے دربار کے سامنے کھڑا تھا،\n6۔ اور کہا، اے خداوند، ہمارے آباؤ اجداد کے خدا، کیا تو آسمانوں میں خدا نہیں؟ اور کیا تم کافروں کی تمام سلطنتوں پر حکمرانی نہیں کرتے؟ اور تمہارے ہاتھ میں {کیا کوئی طاقت نہیں} کہ کوئی تمہارا مقابلہ نہ کر سکے؟\n7۔ کیا تو ہمارے خدا نہیں ہو، جس نے اس زمین کے باشندوں کو اپنے قوم اسرائیل سے پہلے نکالا اور اسے ہمیشہ کے لیے اپنے دوست ابراہیم کی نسل میں دیا؟ {کون: عبرانی۔ تم}\n8۔ اور وہ وہاں رہے، اور تمہارے نام کے لیے وہاں ایک پناہ گاہ بنائی، اور کہا،\n9۔ اگر، {جب} ہم پر کوئی برائی آئے، {جیسے تلوار، فیصلہ، یا وبا، یا قحط، تو ہم اس گھر کے سامنے کھڑے ہوں، اور تیری حضور، (کیونکہ تیرا نام {ہے} اس گھر میں،) اور اپنی مصیبت میں تجھ سے پکار رہے ہوں، تو تم سنو گے اور مدد کرو گے۔\n10۔ اور اب، دیکھو، آمون اور موآب اور ماؤنٹ سعیر کے بیٹے، جن پر تم نے اسرائیل کو حملہ کرنے نہیں دیا، جب وہ مصر کی سرزمین سے نکلے، لیکن وہ ان سے منہ موڑ گئے، اور انہیں تباہ نہیں کیا؛\n11۔ دیکھو، {میں کہتا ہوں، وہ ہمیں کیسے انعام دیتے ہیں، کہ وہ ہمیں اپنی ملکیت سے نکال دیتے ہیں، جو تم نے ہمیں وراثت میں دی ہے۔\n12. اے ہمارے خدا، کیا تم ان کا فیصلہ نہیں کرو گے؟ کیونکہ ہمارے پاس اس عظیم جماعت کے خلاف کوئی طاقت نہیں جو ہمارے خلاف آتی ہے؛ ہم نہیں جانتے کہ کیا کرنا ہے: لیکن ہماری نظریں تم پر ہیں۔\n13۔ اور تمام یہوداہ خداوند کے سامنے کھڑے تھے، اپنے بچوں، بیویوں اور بچوں کے ساتھ۔\n14۔ پھر زکریا کا بیٹا جہازئیل، بنایا کا بیٹا، یئیل کا بیٹا، متانیاہ کا بیٹا، جو آساف کے بیٹوں کا لاوی تھا، جماعت کے درمیان خداوند کی روح آیا؛\n15۔ اور اس نے کہا، اے تمام یہوداہ، اور یروشلم کے باشندو، اور تو بادشاہ یہوشافاط کو سنو، خداوند تم سے فرماتا ہے، اس بڑی تعداد سے نہ ڈرو نہ ڈرو؛ کیونکہ یہ جنگ تمہاری نہیں، بلکہ خدا کی ہے۔\n16. کل تم ان کے خلاف نیچے جاؤ: دیکھو، وہ زیز کی چٹان سے اوپر آتے ہیں؛ اور تم انہیں ندی کے آخر میں، یروئل کے بیابان کے سامنے پاؤ گے۔ {کلف: عبرانی۔ چڑھائی} {نالی: یا، وادی}\n17. تمہیں اس {جنگ} میں لڑنے کی ضرورت نہیں: خود کو تیار کرو، کھڑے ہو جاؤ، اور خداوند کی نجات کو اپنے ساتھ دیکھو، اے یہوداہ اور یروشلم: نہ ڈرو، نہ ڈرو؛ کل ان کے خلاف جاؤ: کیونکہ خداوند تمہارے ساتھ ہوگا۔\n18۔ اور یہوشافاط نے اپنا سر جھکا کر زمین پر منہ رکھ لیا: اور تمام یہوداہ اور یروشلم کے باشندے خداوند کے سامنے گر گئے، خدا کی عبادت کرنے لگے۔\n19۔ اور لاویوں، کوہاتیوں کے بچوں اور قرحیوں کے بچوں میں، بلند آواز میں اسرائیل کے خداوند خدا کی تعریف کرنے کے لیے کھڑے ہوئے۔\n20۔ اور وہ صبح سویرے اٹھے اور ٹیکوا کے بیابان میں نکلے، اور جب وہ باہر نکلے، یہوشافات کھڑا ہوا اور کہا، اے یہوداہ، اور یروشلم کے باشندو، میری بات سنو؛ خداوند اپنے خدا پر ایمان لاؤ، تاکہ تم مستحکم ہو جاؤ؛ اس کے نبیوں پر ایمان لاؤ، تم بھی خوشحال ہو گے۔\n21۔ اور جب اس نے لوگوں سے مشورہ کیا، تو اس نے خداوند کے لیے گانے مقرر کیے، جو پاکیزگی کی خوبصورتی کی تعریف کریں، جب وہ فوج کے سامنے نکلیں، اور کہیں، خداوند کی تعریف کرو؛ اس کی رحمت {ہمیشہ کے لیے} کے لیے۔ {وہ...: عببرانی۔ تعریف کرنے والے}\n22۔ اور جب وہ گانے اور تعریف کرنے لگے، تو خداوند نے عمون، موآب اور پہاڑ سعیر کے بچوں پر گھات لگا کر حملہ کیا، جو یہوداہ کے خلاف آئے تھے؛ اور وہ اس پر فدا ہو گئے۔ {اور جب...: عبرانی۔ اور اس وقت میں جب وہ، وغیرہ} {گانے کے لیے...: عبرانی۔ گانے اور تعریف میں} {وہ تھے...: یا، وہ ایک دوسرے کو مارتے تھے}\n23۔ کیونکہ آمون اور موآب کے بچے سعیر پہاڑ کے باشندوں کے خلاف کھڑے ہوئے، تاکہ انہیں مکمل طور پر قتل اور تباہ کر دیں: اور جب انہوں نے سعیر کے باشندوں کا خاتمہ کیا، تو ہر ایک نے ایک دوسرے کو تباہ کرنے میں مدد کی۔ {تباہ کرنے کے لیے: عبرانی۔ تباہی کے لیے}\n24۔ اور جب یہوداہ ویرانے میں نگرانی کے مینار کی طرف آیا، تو انہوں نے ہجوم کی طرف دیکھا، اور دیکھتے ہوئے وہ مردہ جسم تھے جو زمین پر گرے ہوئے تھے، اور کوئی بچ نہ سکا۔ {کوئی نہیں...: عبرانی۔ کوئی فرار نہیں تھا}\n25۔ اور جب یہوشافاط اور اس کے لوگ ان کی مال غنیمت لینے آئے، تو انہوں نے ان میں مردہ جسموں کے ساتھ دولت اور قیمتی زیورات وافر مقدار میں دیکھے، جنہیں انہوں نے اپنے لیے اتنے اتار دیے جنہیں وہ لے جا سکتے تھے: اور وہ تین دن تک مال غنیمت جمع کرنے میں لگے، یہ بہت زیادہ تھا۔\n26۔ اور چوتھے دن وہ وادی براخا میں جمع ہوئے؛ کیونکہ وہاں انہوں نے خداوند کو برکت دی: اسی لیے اسی جگہ کا نام آج تک 'وادی بیراخا' کہا جاتا ہے۔ {براچا: یعنی، برکت}\n27۔ پھر وہ واپس آئے، یہوداہ اور یروشلم کے ہر آدمی، اور ان کے سامنے یہوشافاط، تاکہ خوشی سے یروشلم واپس جائیں؛ کیونکہ خداوند نے انہیں اپنے دشمنوں پر خوشی منائی تھی۔ {سب سے پہلے: عبرانی۔ سر}\n28۔ اور وہ یروشلم میں زبور، ہارپ اور بگل لے کر خداوند کے گھر آئے۔\n29۔ اور خدا کا خوف ان تمام ملکوں کی بادشاہتوں پر تھا، جب انہوں نے سنا کہ خداوند نے اسرائیل کے دشمنوں کے خلاف جنگ کی۔\n30۔ یوں یہوشافاط کی سلطنت خاموش رہی: کیونکہ اس کے خدا نے اسے آس پاس آرام دیا۔\n31۔ اور یہوشافاط نے یہوداہ پر حکومت کی: جب اس نے حکومت شروع کی تو اس کی عمر پینتیس سال تھی، اور اس نے یروشلم میں پچیس سال حکومت کی۔ اور ان کی والدہ کا نام ازوبہ تھا، جو شیلی کی بیٹی تھیں۔\n32۔ اور وہ اپنے والد آسا کے راستے میں چلا اور اس سے نہ ہٹا، اور خداوند کی نظر میں وہ سب کچھ کیا۔\n33۔ تاہم، اونچی جگہیں چھین لی نہیں گئیں: کیونکہ ابھی تک لوگوں نے اپنے دل اپنے باپ اجداد کے خدا کے لیے تیار نہیں کیے تھے۔\n34۔ اب یہوشافاط کے باقی اعمال، سب سے پہلے اور آخری، دیکھیں، وہ حنانی کے بیٹے یہو کی کتاب میں لکھے گئے ہیں، جو اسرائیل کے بادشاہوں کی کتاب میں ذکر ہے۔ {کتاب یہو: عبرانی۔ الفاظ، وغیرہ} {ذکر کیا گیا ہے: عبرانی۔ اوپر جانے کے لیے بنایا گیا تھا}\n35۔ اور اس کے بعد یہوداہ کے بادشاہ یہوشافاط نے اسرائیل کے بادشاہ اخزیا کے ساتھ اتحاد کیا، جس نے بہت برا کیا:\n36۔ اور اس نے اس کے ساتھ مل کر ترشیش جانے کے لیے جہاز بنائے: اور انہوں نے ایزیونگبر میں جہاز بنائے۔\n37۔ پھر مریشا کے دودوہ کے بیٹے الیعزر نے یہوشافاط کے خلاف پیش گوئی کی، کہا، کیونکہ تم نے آہزیاہ کے ساتھ اتحاد کر لیا ہے، خداوند نے تمہارے اعمال توڑ دیے ہیں۔ اور جہاز ٹوٹ چکے تھے، کہ وہ ترشیش نہیں جا سکے۔","1۔ اب یہوشافاط نے اپنے باپ دادا کے ساتھ سونا اور اپنے آباؤ اجداد کے ساتھ داؤد شہر میں دفن ہوا۔ اور اس کا بیٹا یہورام نے اس کی جگہ حکومت کی۔\n2۔ اور اس کے بھائی تھے: یہوشافاط، عزریہ، یہیئیل، زکریا، عزریا، مائیکل، اور شفطیہ کے بیٹے: یہ سب اسرائیل کے بادشاہ یہوشافات کے بیٹے تھے۔\n3۔ اور ان کے والد نے انہیں چاندی، سونا اور قیمتی چیزوں کے بڑے تحفے دیے، جن کے ساتھ یہوداہ کے باڑ والے شہر تھے، لیکن بادشاہی نے یہورام کو دیا؛ کیونکہ وہ سب سے بڑا تھا۔\n4۔ اب جب یہورام اپنے باپ کی بادشاہت میں اٹھا تو اس نے خود کو مضبوط کیا، اور اپنے تمام بھائیوں کو تلوار سے مار ڈالا، اور اسرائیل کے شہزادوں کو بھی۔\n5۔ یہورام جب اس نے حکومت شروع کی تو اس کی عمر تیس سال اور دو سال تھی، اور اس نے یروشلم میں آٹھ سال حکومت کی۔\n6۔ اور وہ اسرائیل کے بادشاہوں کے راستے میں چلتا رہا، جیسے اخاب خاندان نے کیا: کیونکہ اس نے اخاب کی بیٹی کو بیوی بنایا اور خداوند کی نظر میں برا کیا۔\n7۔ تاہم خداوند داؤد کے گھر کو تباہ نہیں کرے گا، اس عہد کی وجہ سے جو اس نے داؤد کے ساتھ کیا تھا، اور جیسا کہ اس نے وعدہ کیا تھا کہ وہ اسے اور اس کے بیٹوں کو ہمیشہ کے لیے روشنی دے گا۔ {روشنی: عبرانی۔ لیمپ، یا، موم بتی}\n8۔ اس کے زمانے میں ایڈومیوں نے یہوداہ کی حکمرانی سے بغاوت کی اور خود کو بادشاہ بنا لیا۔ {ڈومینین: ہیب۔ ہاتھ}\n9۔ پھر یہورام اپنے شہزادوں کے ساتھ روانہ ہوا، اور اپنی تمام رتھ اس کے ساتھ، اور رات کو اٹھا، اور اس کے گرد گھیرے ہوئے ایڈومیوں اور رتھوں کے کپتانوں کو شکست دی۔\n10. یوں ادومی یہوداہ کے ہاتھوں سے آج تک بغاوت کرتے رہے۔ اسی وقت {اسی وقت} لبنہ نے اس کے ہاتھ سے بغاوت کی؛ کیونکہ اس نے اپنے باپ و اجداد کے خداوند خدا کو چھوڑ دیا تھا۔\n11۔ اس کے علاوہ اس نے یہوداہ کے پہاڑوں میں اونچی جگہیں بنائیں، اور یروشلم کے باشندوں کو کرنے پر مجبور کیا، اور یہوداہ کو مجبور کیا۔\n12۔ اور اسے ایلیاہ نبی کی طرف سے ایک خط آیا، جس میں لکھا تھا، یہی فرماتا ہے خداوند داؤد کا خدا، تمہارا باپ، کیونکہ تم نے اپنے باپ یہوشافات کے راستوں پر نہیں چلی، اور نہ ہی یہوداہ کے بادشاہ آسا کے راستوں پر،\n13۔ لیکن اس نے اسرائیل کے بادشاہوں کے راستے میں چلنا شروع کیا، اور یہوداہ اور یروشلم کے باشندوں کو آہاب خاندان کی بدکاری کی طرح بدکار بنا دیا، اور اپنے باپ کے گھرانے کے اپنے بھائیوں کو بھی قتل کیا، جو تم سے بہتر تھے:\n14۔ دیکھو، خداوند تمہارے لوگ، تمہارے بچوں، بیویوں اور تمہارے تمام مال کو ایک بڑی آفت کے ساتھ لعنت بھیجے گا: {ایک عظیم...: عبرانی۔ زبردست فالج}\n15۔ اور تمہیں اپنی آنتوں کی بیماری سے بڑی بیماری لگے گی، جب تک کہ تمہاری آنتیں بیماری کی وجہ سے دن بہ دن باہر نہ نکل جائیں۔\n16۔ مزید یہ کہ خداوند نے یہورام کے خلاف فلسطینیوں اور عربوں کی روح کو جگایا، جو حبوشیوں کے قریب تھے:\n17۔ اور وہ یہوداہ کے اندر آئے، وہاں توڑ کر بادشاہ کے گھر میں ملنے والی تمام چیزیں، اس کے بیٹوں اور اس کی بیویوں کو بھی لے گئے؛ تاکہ اس کا کوئی بیٹا نہ رہا، سوائے یہوآہاز کے، جو اس کے سب سے چھوٹے بیٹے تھے۔ {اٹھایا گیا...: عبرانی۔ قیدی میں لے جایا گیا} {یہوآحاز: جسے اخزیا یا عزریاہ بھی کہا جاتا ہے}\n18۔ اور اس سب کے بعد خداوند نے اسے ایک لاعلاج بیماری سے اس کے پیٹ میں مارا دیا۔\n19۔ اور ایسا ہوا کہ وقت کے ساتھ، دو سال گزرنے کے بعد، ان کی آنتیں بیماری کی وجہ سے گر گئیں: یوں وہ شدید بیماریوں کی وجہ سے فوت ہو گئے۔ اور اس کے لوگوں نے اس کے لیے کوئی آگ نہیں لگائی، جیسے اس کے باپوں کو جلانا۔\n20۔ وہ تیس اور بائیس سال کا تھا جب اس نے حکومت شروع کی، اور یروشلم میں آٹھ سال حکومت کی، اور بغیر کسی خواہش کے چلا گیا۔ تاہم انہیں داؤد کے شہر میں دفن کیا گیا، لیکن بادشاہوں کی قبروں میں نہیں۔ {بغیر...: عبرانی۔ بغیر خواہش کے}","1۔ اور یروشلم کے باشندوں نے احزیاہ کو اس کی جگہ اپنا سب سے چھوٹا بیٹا بادشاہ بنایا: کیونکہ عربوں کے ساتھ جو لوگ کیمپ میں آئے تھے، انہوں نے سب سے بڑے کو مار ڈالا۔ یوں یہوداہ کے بادشاہ یہورام کے بیٹے آخزیاہ نے حکومت کی۔\n2۔ چالیس سال اور بیالیس سال کا تھا جب اس نے حکومت شروع کی، اور یروشلم میں ایک سال حکومت کی۔ ان کی والدہ کا نام بھی اتالیہ تھا، جو عمری کی بیٹی تھیں۔\n3۔ وہ آہاب خاندان کے راستوں پر بھی چلتا رہا: کیونکہ اس کی ماں اس کی مشیر تھی کہ وہ برے کام کرے۔\n4۔ اسی لیے اس نے خداوند کے سامنے آہاب خاندان کی طرح برا کیا: کیونکہ وہ اس کے والد کی موت کے بعد اس کے مشیر تھے۔\n5۔ وہ بھی ان کی نصیحت کے بعد چلتا رہا، اور اسرائیل کے بادشاہ اخاب کے بیٹے یہورام کے ساتھ شام کے بادشاہ حزائیل کے خلاف راموتجلعاد میں جنگ کے لیے گیا: اور شامیوں نے جورام کو شکست دی۔\n6۔ اور وہ یزرئیل واپس آیا تاکہ شفا پائے، کیونکہ اسے رامہ میں لگے زخموں کی وجہ سے، جب اس نے شام کے بادشاہ حزائیل سے لڑائی کی تھی۔ اور عزریاہ، یہوداہ کے بادشاہ یہورام کا بیٹا، یہورام کے بیٹے سے ملنے یزریل میں گیا، کیونکہ وہ بیمار تھا۔ {جو کہ...: عبرانی جس سے انہوں نے اسے زخمی کیا} {عزریا: جسے آہزیا یا یہوآہاز بھی کہا جاتا ہے}\n7۔ اور اخزیا کی تباہی خدا کی طرف سے تھی جب وہ یورام آیا، کیونکہ جب وہ آیا تو وہ یہورام کے ساتھ نمشیوں کے بیٹے یہو کے خلاف نکلا، جسے خداوند نے مسح کیا تھا تاکہ وہ اہاب کے گھر کو کاٹ سکے۔ {تباہی: عبرانی۔ نیچے قدم رکھنا}\n8۔ اور ایسا ہوا کہ جب یہو اخاب خاندان پر فیصلہ کر رہا تھا، اور اس نے یہوداہ کے شہزادوں اور آحزیا کے بھائیوں کے بیٹوں کو پایا جو آہزیا کی خدمت کرتے تھے، تو اس نے انہیں قتل کر دیا۔\n9۔ اور اس نے اخزیاہ کی تلاش کی: اور انہوں نے اسے پکڑ لیا، (کیونکہ وہ سامریہ میں چھپا ہوا تھا) اور اسے یہو کے پاس لے گئے: اور جب اسے قتل کر دیا تو اسے دفن کر دیا: کیونکہ انہوں نے کہا، وہ یہوشافاط کا بیٹا ہے، جس نے پورے دل سے خداوند کی تلاش کی۔ لہٰذا اخزیاہ خاندان کے پاس سلطنت کو قابو میں رکھنے کی طاقت نہیں تھی۔\n10۔ لیکن جب اتالیا، اخزیا کی والدہ نے دیکھا کہ اس کا بیٹا مر چکا ہے، تو وہ اٹھی اور یہوداہ خاندان کے تمام شاہی نسل کو تباہ کر دیا۔\n11۔ لیکن یہوشابیت، بادشاہ کی بیٹی، نے اخزیاہ کے بیٹے یوآش کو لے کر بادشاہ کے مارے گئے بیٹوں میں سے اسے چرا لیا، اور اسے اور اس کی نرس کو ایک کمرے میں رکھ دیا۔ لہٰذا یہوشابیع، بادشاہ یہورام کی بیٹی، جو یہوعیعیہ کاهن کی بیوی تھی، (کیونکہ وہ آحزیاہ کی بہن تھی)، نے اسے اتلیاہ سے چھپا دیا تاکہ اسے قتل نہ کرے۔ {یہوشبع: جسے یہوشبع بھی کہا جاتا ہے}\n12۔ اور وہ چھ سال ان کے ساتھ خدا کے گھر میں چھپا رہا: اور اتالیاہ نے زمین پر حکومت کی۔","1۔ اور ساتویں سال یہویادا نے خود کو مضبوط کیا، اور سینکڑوں کے کپتانوں، عزریاہ یروہام کا بیٹا، اسماعیل یہوحنان کا بیٹا، عزریاہ عبید کا بیٹا، عضیا کا بیٹا ماسیہ، اور زکری کا بیٹا الیشفاط کو اپنے ساتھ معاہدہ کیا۔\n2۔ اور وہ یہوداہ میں گھومے، اور یہوداہ کے تمام شہروں سے لاویوں اور اسرائیل کے آبا کے سردار کو جمع کیا، اور وہ یروشلم پہنچے۔\n3۔ اور تمام جماعت نے خدا کے گھر میں بادشاہ کے ساتھ عہد کیا۔ اور اس نے ان سے کہا، دیکھو، بادشاہ کا بیٹا حکومت کرے گا، جیسا کہ خداوند نے داؤد کے بیٹوں کے بارے میں فرمایا۔\n4. یہی وہ کام ہے جو تم کرو گے؛ تم میں سے ایک تیسرا حصہ جو سبت کے دن داخل ہوتا ہے، کاہنوں اور لاویوں کا {ہوگا} دروازوں کے محافظ ہوں گے؛ {دروازے: عبوری۔ تھریش ہولڈز}\n5۔ اور تیسرا حصہ {بادشاہ کے گھر ہوگا}؛ اور ایک تیسرا حصہ بنیاد کے دروازے پر: اور تمام لوگ خداوند کے گھر کے درباروں میں ہوں گے۔\n6۔ لیکن کوئی بھی خداوند کے گھر میں نہ آئے، سوائے کاہنوں اور لاویوں کے خادم کے؛ وہ اندر جائیں گے، کیونکہ وہ مقدس ہیں: لیکن تمام لوگ خداوند کی نگرانی کریں گے۔\n7۔ اور لاوی بادشاہ کے گرد گھیریں گے، ہر آدمی اپنے ہتھیار ہاتھ میں لیے گا؛ اور جو بھی گھر میں آئے گا، اسے قتل کر دیا جائے گا، لیکن بادشاہ کے ساتھ رہو جب وہ آئے اور جب وہ باہر جائے۔\n8۔ تو لاویوں اور تمام یہوداہ نے وہ سب کچھ کیا جو یہوعیدہ کاهن نے حکم دیا تھا، اور ہر آدمی کو جو سبت کے دن آنا تھا، ان کے ساتھ لے گئے، کیونکہ یہویادا کاہن نے کورسز کو مسترد نہیں کیا۔\n9۔ مزید یہ کہ یہوعیادا پادری نے سینکڑوں نیزے، بکلر اور ڈھالیں کپتانوں کو دی، جو {بادشاہ} داؤد کے تھے، جو {خدا کے گھر} میں تھے۔\n10۔ اور اس نے سب لوگوں کو، ہر آدمی کے ہاتھ میں ہتھیار لیے، مندر کے دائیں جانب سے بائیں طرف، قربان گاہ اور مندر کے پاس، بادشاہ کے ارد گرد کھڑا کر دیا۔ {سائیڈ: عبوری۔ کندھے} {مندر: عبرانی۔ گھر}\n11۔ پھر انہوں نے بادشاہ کے بیٹے کو باہر نکالا، اس پر تاج پہنایا، اور اسے گواہی دی، اور اسے بادشاہ بنایا۔ اور یہوعیادا اور اس کے بیٹوں نے اسے مسح کیا اور کہا، خدا بادشاہ کی حفاظت کرے۔ {خدا...: عبرانی۔ بادشاہ کو زندہ رہنے دو}\n12۔ اب جب اتھالیاہ نے لوگوں کی دوڑنے اور بادشاہ کی تعریف کرنے کی آواز سنی، تو وہ لوگوں کے پاس خداوند کے گھر آئی:\n13۔ اور اس نے دیکھا، اور دیکھو، بادشاہ اپنے ستون کے پاس کھڑا تھا، اور بادشاہ نے شہزادے اور بگل بجائے: اور ملک کے تمام لوگ خوش ہوئے، بگل بجائے، گانے والے بھی موسیقی کے آلات اور وہ لوگ جو تعریف کے گانے سکھائے گئے تھے۔ پھر اتھالیاہ نے اس کے کپڑے پھاڑ دیے اور کہا، غداری، غداری۔ {غداری: عبرانی۔ سازش}\n14۔ پھر یہویادا پادری نے سینکڑوں فوجیوں کے کپتانوں کو لشکر پر رکھا اور کہا، اسے پہاڑوں سے نکالو، اور جو بھی اس کے پیچھے جائے گا، اسے تلوار سے مارا جائے۔ کیونکہ پادری نے کہا، خدا کے گھر میں اسے قتل نہ کرو۔\n15۔ تو انہوں نے اس پر ہاتھ رکھا؛ اور جب وہ بادشاہ کے گھر کے پاس گھوڑے کے دروازے کے دروازے پر پہنچی، تو وہاں اسے قتل کر دیا گیا۔\n16۔ اور یہوعیادا نے اس کے درمیان، اور تمام لوگوں کے درمیان، اور بادشاہ کے درمیان، ایک عہد کیا کہ وہ خداوند کے لوگ ہوں گے۔\n17۔ پھر سب لوگ بعل کے گھر گئے، اسے توڑ دیا، اس کے قربان گاہوں اور مجسموں کو ٹکڑوں میں توڑ دیا، اور بعل کے کاهن متان کو قربان گاہوں کے سامنے قتل کر دیا۔\n18۔ اسی طرح یہویادا نے خداوند کے گھر کے دفاتر کو کاہنوں کے ہاتھوں لاویوں کے ہاتھوں مقرر کیا، جنہیں داؤد نے خداوند کے گھر میں تقسیم کیا تھا، تاکہ وہ خداوند کی جلنے والی قربانیاں پیش کریں، جیسا کہ موسیٰ کی شریعت میں لکھا ہے، خوشی اور گانے کے ساتھ، جیسا کہ داؤد نے مقرر کیا تھا۔ {جیسا کہ تھا...: عبرانی۔ داؤد کے ہاتھوں سے}\n19۔ اور اس نے دربانوں کو خداوند کے گھر کے دروازے پر کھڑا کیا تاکہ کوئی بھی {جو کسی چیز میں ناپاک ہو} داخل نہ ہو۔\n20۔ اور اس نے سینکڑوں کے کپتانوں، اشرافیہ، عوام کے حکمرانوں اور ملک کے تمام لوگوں کو لے کر بادشاہ کو خداوند کے گھر سے نیچے اتارا: اور وہ بلند دروازے سے بادشاہ کے گھر میں آئے، اور بادشاہ کو بادشاہت کے تخت پر بٹھایا۔\n21۔ اور زمین کے تمام لوگ خوش ہوئے: اور شہر خاموش ہو گیا، اس کے بعد انہوں نے اتالیاہ کو تلوار سے مار ڈالا۔","1. یوآش سات سال کا تھا جب اس نے حکومت شروع کی، اور یروشلم میں چالیس سال حکومت کی۔ ان کی والدہ کا نام بھی بئر السبع کی زیبیہ تھا۔\n2۔ اور یوآش نے خداوند کی نظر میں یہوعیدہ کاہن کے تمام دنوں میں جو کچھ تھا، کیا۔\n3۔ اور یہوعیدع نے اپنے لیے دو بیویاں رکھیں؛ اور اس نے بیٹے اور بیٹیاں پیدا کیں۔\n4۔ اور اس کے بعد ہوا کہ یوآش نے خداوند کے گھر کی مرمت کا ارادہ کیا۔ {مرمت کے لیے: عبرانی۔ تجدید کے لیے}\n5۔ اور اس نے کاہنوں اور لاویوں کو اکٹھا کیا اور ان سے کہا، یہوداہ کے شہروں میں جاؤ، اور تمام اسرائیلیوں سے پیسے جمع کرو تاکہ اپنے خدا کے گھر کی مرمت سال بہ سال کرو، اور دیکھو کہ تم اس معاملے کو جلدی کرو۔ تاہم لاویوں نے جلدی نہیں کی۔\n6۔ اور بادشاہ نے یہویادا سردار کو بلایا اور کہا، \"تم نے لاویوں سے یہوداہ اور یروشلم سے حکم کیوں نہیں دیا کہ وہ موسیٰ خداوند کے بندے اور اسرائیل کی جماعت کے مجموعے کو گواہی کے خیمے کے لیے {حکم کے مطابق} لے آئیں؟\n7۔ کیونکہ اتالیاہ کے بیٹے، وہ بدکار عورت، نے خدا کے گھر کو توڑ دیا تھا؛ اور خداوند کے گھر کی تمام وقف شدہ چیزیں انہوں نے بعلیم کو عطا کیں۔\n8۔ اور بادشاہ کے حکم پر انہوں نے ایک صندوق بنایا، اور اسے خداوند کے گھر کے دروازے کے بغیر رکھ دیا۔\n9۔ اور انہوں نے یہوداہ اور یروشلم کے ذریعے اعلان کیا کہ خداوند کے سامنے وہ مجموعہ لائیں جو موسیٰ خدا کے خادم نے بیابان میں اسرائیل پر رکھا تھا۔ {ایک اعلان: عبرانی۔ ایک آواز}\n10۔ اور تمام شہزادے اور تمام لوگ خوش ہوئے، اندر لائے گئے، اور صندوق میں پھینک دیے گئے، یہاں تک کہ ان کا انجام ہو گیا۔\n11۔ اب یہ ہوا کہ جب صندوق لاویوں کے ہاتھوں بادشاہ کے دفتر میں لایا گیا، اور جب انہوں نے دیکھا کہ وہاں بہت پیسہ ہے، تو بادشاہ کا کاتب اور اعلیٰ کاهن کا افسر آئے اور صندوق خالی کیا، اسے لے کر دوبارہ اپنے پاس لے گئے۔ یوں وہ دن بہ دن کرتے رہے، اور وافر مقدار میں پیسہ جمع کرتے رہے۔\n12۔ اور بادشاہ اور یہوعیادا نے اسے ان لوگوں کو دیا جنہوں نے خداوند کے گھر کی خدمت کا کام کیا، اور مزدوروں اور بڑھئیوں کو خداوند کے گھر کی مرمت کے لیے رکھا، اور لوہا اور پیتل کے کام کو خداوند کے گھر کی مرمت کے لیے بھی۔\n13۔ یوں مزدوروں نے کام کیا، اور انہوں نے کام مکمل کیا، اور انہوں نے خدا کے گھر کو اس کی حالت میں رکھا اور اسے مضبوط کیا۔ {یہ کام...: عبرانی۔ کام کے ساتھ شفا کا عمل بڑھا}\n14۔ اور جب وہ ختم ہو گئے، تو باقی رقم بادشاہ اور یہویادع کے سامنے لے آئے، جن میں سے خداوند کے گھر کے لیے برتن بنائے گئے، {حتیٰ کہ} برتن بھی تھے تاکہ خدمت کی جا سکے، اور چمچ، اور سونے اور چاندی کے برتن پیش کیے جا سکیں۔ اور انہوں نے خداوند کے گھر میں یہویادع کے تمام دنوں میں مسلسل نذرانہ پیش کیا۔ {پیش کرنے کے لیے...: یا، وبا کے لیے}\n15۔ لیکن یہوعیادا بوڑھا ہو گیا، اور جب وہ فوت ہوا تو وہ دنوں سے بھرا ہوا تھا؛ وہ ایک سو تیس سال کے تھے جب وہ فوت ہوئے۔\n16۔ اور انہوں نے اسے داؤد کے شہر میں بادشاہوں کے درمیان دفن کیا، کیونکہ اس نے اسرائیل میں خدا اور اپنے گھر دونوں کے لیے بھلائی کی تھی۔\n17۔ یہوعیادا کی موت کے بعد یہوداہ کے شہزادے آئے اور بادشاہ کے سامنے سجدہ کیا۔ پھر بادشاہ نے ان کی بات مانی۔\n18۔ اور وہ اپنے آباؤ اجداد کے خداوند خدا کے گھر سے نکل گئے، اور باغات اور بتوں کی خدمت کرنے لگے: اور یہوداہ اور یروشلم پر ان کی اس غلطی پر غصہ آیا۔\n19۔ پھر بھی اس نے ان کے پاس نبی بھیجے، تاکہ انہیں دوبارہ خداوند کے پاس لے آئیں؛ اور انہوں نے ان کے خلاف گواہی دی، لیکن وہ سننے کو تیار نہیں تھے۔\n20۔ اور خدا کی روح زکریا پر آیا، جو یہویادا کاہن کا بیٹا تھا، جو لوگوں کے اوپر کھڑا تھا، اور ان سے کہا، خدا نے یوں فرمایا، تم خداوند کے احکامات کی خلاف ورزی کیوں کرتے ہو، تاکہ تم کامیاب نہ ہو سکتے؟ کیونکہ تم نے خداوند کو چھوڑ دیا ہے، اس نے بھی تمہیں چھوڑ دیا ہے۔ {آیا...: عبوری۔ کپڑوں میں}\n21۔ اور انہوں نے اس کے خلاف سازش کی، اور بادشاہ کے حکم پر خداوند کے گھر کے دربار میں اسے پتھر مارے۔\n22۔ یوں بادشاہ یوآش نے اپنے والد کی مہربانی کو یاد نہیں رکھا جو اس کے والد نے اس کے ساتھ کی تھی، بلکہ اس نے اپنے بیٹے کو قتل کر دیا۔ اور جب وہ فوت ہوا، اس نے کہا، خداوند دیکھو {اسے}، اور {اسے} کا تقاضا کرے۔\n23۔ اور سال کے آخر میں ایسا ہوا کہ شام کی فوج اس کے خلاف آئی: اور وہ یہوداہ اور یروشلم پہنچے، اور قوم کے تمام شہزادوں کو تباہ کر دیا، اور ان کی تمام مال غنیمت دمشق کے بادشاہ کو بھیج دی۔ {پر...: عبرانی۔ سال کے انقلاب میں} {دمشق: عبرانی۔ دارمیسیک}\n24۔ کیونکہ شامیوں کی فوج ایک چھوٹے گروہ کے ساتھ آئی، اور خداوند نے ان کے ہاتھ میں ایک بہت بڑی فوج دی، کیونکہ انہوں نے اپنے باپ و اجداد کے خداوند خدا کو چھوڑ دیا تھا۔ لہٰذا انہوں نے یواش کے خلاف فیصلہ نافذ کیا۔\n25۔ اور جب وہ اس سے جدا ہو گئے، (کیونکہ انہوں نے اسے بڑی بیماریوں میں چھوڑ دیا،) تو اس کے اپنے خادموں نے یہوعیدہ پادری کے بیٹوں کے خون کے لیے اس کے خلاف سازش کی، اسے اس کے بستر پر مار ڈالا، اور وہ مر گیا، اور اسے داؤد کے شہر میں دفن کیا، لیکن بادشاہوں کی قبروں میں نہیں دفنایا گیا۔\n26۔ اور یہ وہ لوگ ہیں جنہوں نے اس کے خلاف سازش کی؛ زباد، شمیث ایک عمونیتیس کا بیٹا، اور یہوزآباد، شمرتھ جو موآبیس کا بیٹا تھا، اور یہوزآباد۔ {زباد: یا، جوزاخر} {شمریتھ: یا، شومر}\n27۔ اب {اس کے بیٹوں کے بارے میں}، اور اس پر ڈالے گئے بوجھ کی عظمت، اور خدا کے گھر کی مرمت کے بارے میں، دیکھو، یہ {بادشاہوں کی کتاب کی کہانی میں لکھے گئے ہیں}۔ اور اس کے بیٹے امازیا نے اس کی جگہ حکومت کی۔ {مرمت: عبرانی۔ بنیاد} {کہانی: یا، تبصرہ}","1. امازیہ {تھا} بیس پچیس سال کا تھا {جب} اس نے حکومت شروع کی، اور یروشلم میں انتیس سال حکومت کی۔ اور اس کی والدہ کا نام یروشلم کا یہودان تھا۔\n2۔ اور اس نے وہ کیا جو خداوند کے سامنے درست تھا، لیکن کامل دل سے نہیں۔\n3۔ جب بادشاہت اس کے پاس قائم ہوئی تو اس نے اپنے ان خادموں کو قتل کر دیا جنہوں نے بادشاہ کو اس کے باپ کو قتل کیا تھا۔ {قائم...: عبرانی۔ اس پر تصدیق ہو گئی}\n4۔ لیکن اس نے ان کے بچوں کو نہیں مارا، بلکہ {کیا} جیسا {موسیٰ کی کتاب میں شریعت میں لکھا ہے}، جہاں خداوند نے حکم دیا تھا، کہتا ہے: باپ بچوں کے لیے نہیں مریں گے، نہ بچے باپ کے لیے مریں گے، بلکہ ہر انسان اپنے گناہ کے لیے مرے گا۔\n5۔ مزید یہ کہ امازیہ نے یہوداہ کو اکٹھا کیا، اور انہیں ہزاروں پر کپتان اور سینکڑوں کے کپتان بنایا، جیسا کہ {ان} آباؤ اجداد کے گھروں کے مطابق، پورے یہوداہ اور بنیامین میں: اور اس نے انہیں بیس سال اور اس سے زیادہ عمر سے گنایا، اور انہیں تین لاکھ منتخب {مرد} پایا جو جنگ میں جانے کے قابل تھے، جو نیزہ اور ڈھال سنبھال سکتے تھے۔\n6۔ اس نے اسرائیل سے ایک لاکھ بہادر آدمیوں کو ایک سو ٹیلنٹ چاندی کے عوض کرائے پر لیا۔\n7۔ لیکن خدا کا ایک آدمی اس کے پاس آیا اور کہا، اے بادشاہ، اسرائیل کی فوج کو اپنے ساتھ نہ لے جائے؛ کیونکہ خداوند اسرائیل کے ساتھ نہیں ہے، یعنی افریم کے تمام بچوں کے ساتھ۔\n8۔ لیکن اگر تم جانا چاہتے ہو تو جنگ کے لیے مضبوط رہو: خدا تمہیں دشمن کے سامنے گرا دے گا: کیونکہ خدا کے پاس مدد کرنے اور گرانے کی طاقت ہے۔\n9۔ اور امازیہ نے خدا کے بندے سے کہا، لیکن ہم ان سو ٹیلنٹس کے لیے کیا کریں جو میں نے اسرائیل کی فوج کو دیے ہیں؟ اور خدا کے بندے نے جواب دیا، خداوند تمہیں اس سے کہیں زیادہ دے سکتا ہے۔ {فوج: عبرانی بینڈ}\n10۔ پھر امازیا نے انہیں جدا کر دیا، یعنی وہ فوج جو افرایم سے اس کے پاس آئی تھی، تاکہ وہ واپس گھر جا سکے، جس کی وجہ سے ان کا غصہ یہوداہ کے خلاف بھڑک اٹھا، اور وہ شدید غصے میں واپس آئے۔ {دوبارہ گھر: عبرانی۔ ان کی جگہ پر} {عظیم...: عبرانی میں۔ غصے کی شدت میں}\n11۔ اور امازیہ نے خود کو مضبوط کیا، اپنے لوگوں کی قیادت کی، اور نمک کی وادی میں گیا، اور سعیر کے دس ہزار بچوں کو شکست دی۔\n12۔ اور {باقی} دس ہزار زندہ بچے یہوداہ کے بچوں نے قیدی اٹھا کر چٹان کی چوٹی پر لے جا کر چٹان کی چوٹی سے نیچے پھینک دیا، یہاں تک کہ وہ سب ٹکڑے ٹکڑے ہو گئے۔\n13۔ لیکن وہ فوج کے سپاہی جنہیں عمصیہ نے واپس بھیجا تھا، تاکہ وہ اس کے ساتھ جنگ میں نہ جائیں، انہوں نے یہوداہ کے شہروں پر حملہ کیا، سامریہ سے لے کر بیت حورون تک، اور تین ہزار کو شکست دی اور بہت لوٹ مار کر لیا۔ {سپاہی...: عبرانی۔ بینڈ کے بیٹے}\n14۔ اب یہ ہوا کہ جب امازیا ایڈومیوں کے قتل عام سے آیا، تو اس نے سعیر کے بچوں کے دیوتاؤں کو لایا، انہیں اپنے دیوتا بنا دیا، ان کے سامنے جھک کر ان کے سامنے لوبان جلائی۔\n15۔ اسی لیے خداوند کا غصہ اماصیا کے خلاف بھڑکا، اور اس نے اس کے پاس ایک نبی بھیجا جس نے کہا، تم نے لوگوں کے دیوتاؤں کی تلاش کیوں کی، جو اپنے لوگوں کو تیرے ہاتھوں سے آزاد نہیں کر سکے؟\n16۔ اور جب وہ اس سے بات کر رہا تھا تو {بادشاہ} نے اس سے کہا، کیا تم بادشاہ کے مشورے سے بنے ہو؟ فوربیئر؛ تمہیں کیوں پسند آئے گا؟ پھر نبی نے کہا، میں جانتا ہوں کہ خدا نے تمہیں تباہ کرنے کا ارادہ کیا ہے، کیونکہ تم نے یہ کیا ہے اور میری نصیحت نہیں مانی۔ {متعین: عبرانی زبان۔ مشورہ دیا گیا}\n17۔ پھر یہوداہ کے بادشاہ امازیاہ، نے نصیحت کی اور یہوآہاز کے بیٹے، یہو کے بیٹے، اسرائیل کے بادشاہ یوآش کو بھیجا، اور کہا، آؤ، آؤ ایک دوسرے کے سامنے دیکھیں۔\n18۔ اور اسرائیل کے بادشاہ یوآش نے یہوداہ کے بادشاہ امازیا کو بھیجا، کہنے پر، لبنان میں جو کانٹا تھا اس نے لبنان میں اس دیودار کے پاس بھیجا جو {تھا} اور کہا، اپنی بیٹی میرے بیٹے کو بیوی کے حوالے کر دو۔ اور وہاں لبنان میں ایک جنگلی جانور کے پاس سے گزرا اور کانٹے پر چل پڑا۔ {تھسل: یا، فرز بش، یا، کانٹا} {ایک وحشی...: عبرانی۔ میدان کا ایک درندہ}\n19۔ تم کہتی ہو، دیکھو، تم نے ایڈومیوں کو مارا ہے؛ اور تمہارا دل تمہیں فخر سے اٹھاتا ہے: اب گھر پر رہو؛ تم کیوں اپنے نقصان میں مداخلت کرو گے، تاکہ تم گر جاؤ، حتیٰ کہ تم بھی، اور یہوداہ بھی تمہارے ساتھ؟\n20۔ لیکن امازیہ نے سننا نہیں چاہا؛ کیونکہ یہ خدا کی طرف سے آیا تھا تاکہ وہ انہیں ان کے دشمنوں کے ہاتھ میں دے سکے، کیونکہ وہ ایڈوم کے دیوتاؤں کی تلاش میں تھے۔\n21۔ یوں اسرائیل کا بادشاہ یواش اوپر گیا؛ اور انہوں نے ایک دوسرے کے چہرے پر دیکھا، {دونوں} وہ اور یہوداہ کے بادشاہ امازیہ، بیت شمش میں، جو {یہوداہ کا ہے}۔\n22۔ اور یہوداہ کو اسرائیل کے سامنے بدترین حالت میں ڈال دیا گیا، اور وہ ہر آدمی کو اس کے خیمے کی طرف بھاگ گئے۔ {put...: عبرانی۔ عاشق}\n23۔ اور یوآش بادشاہ اسرائیل نے یہوداہ کے بادشاہ امازیاہ، یوآش کے بیٹے، یہوآہاز کے بیٹے، کو بیت شمش میں لے کر یروشلم لے آیا، اور یروشلم کی دیوار کو افرایم کے دروازے سے چار سو ہاتھ تک توڑ دیا۔ {کونا...: عبرانی۔ اس کا دروازہ جو دیکھتا ہے}\n24۔ اور {اس نے} تمام سونا اور چاندی، اور وہ تمام برتن جو خدا کے گھر میں اوبیدم کے ساتھ ملے تھے، اور بادشاہ کے گھر کے خزانے اور یرغمالیوں کو بھی، لے کر سامریہ واپس آ گیا۔\n25۔ اور امازیہ، یہوداہ کے بادشاہ یوآش کے بیٹے کی موت کے بعد پندرہ سال زندہ رہا۔\n26۔ اب امازیہ کے باقی اعمال، سب سے پہلے اور آخری، دیکھیں، کیا وہ یہوداہ اور اسرائیل کے بادشاہوں کی کتاب میں لکھے نہیں گئے؟\n27۔ جب امازیہ نے خداوند کی پیروی سے منہ موڑ لیا تو انہوں نے یروشلم میں اس کے خلاف سازش کی؛ اور وہ لاخیش کے پاس بھاگ گیا: لیکن انہوں نے لاچیش کو اس کے پیچھے بھیجا اور وہاں اسے قتل کر دیا۔ {سے...: عبرانی بعد سے} {بنا...: عبرانی سازش کی}\n28۔ اور انہوں نے اسے گھوڑوں پر سوار کیا اور اس کے آباؤ اجداد کے ساتھ یہوداہ شہر میں دفن کیا۔ {یہوداہ: یعنی داؤد کا شہر}","1۔ پھر یہوداہ کے تمام لوگوں نے عزیاہ کو، جو {سولہ} سال کا تھا، لے کر اسے اس کے والد امازیا کے کمرے میں بادشاہ بنایا۔ {عزیا: یا، عزریہ}\n2۔ اس نے ایلوتھ تعمیر کیا، اور اسے یہوداہ کو واپس کر دیا، اس کے بعد بادشاہ نے اپنے باپ دادا کے ساتھ تعلقات قائم کیے۔\n3. سولہ سال کی عمر میں عزیاہ تھا جب اس نے حکومت شروع کی، اور اس نے یروشلم میں پچاس سال اور دو سال حکومت کی۔ ان کی والدہ کا نام بھی یروشلم کا یکولیاہ تھا۔\n4۔ اور اس نے خداوند کی نظر میں جو کچھ تھا وہ کیا، جیسا کہ اس کے والد اماصیا نے کیا۔\n5۔ اور اس نے زکریا کے زمانے میں خدا کی تلاش کی، جو خدا کے خوابوں میں سمجھدار تھا: اور جب تک وہ خداوند کی تلاش میں رہا، خدا نے اسے خوشحال بنایا۔ {خوابوں میں...: عبرانی۔ خدا کی نظر میں}\n6۔ اور اس نے آگے بڑھ کر فلسطینیوں کے خلاف جنگ کی، اور گت کی دیوار، یبنی کی دیوار اور اشدود کی دیوار کو توڑ دیا، اور اشدود کے ارد گرد اور فلسطینیوں کے درمیان شہر تعمیر کیے۔ {بارے میں...: یا، اشدود کے ملک میں}\n7۔ اور خدا نے اس کی مدد کی فلسطینیوں کے خلاف، اور گربعل میں بسنے والے عربوں اور مہونیموں کے خلاف۔\n8۔ اور عمونیوں نے عزیاہ کو تحفے دیے: اور اس کا نام مصر میں داخل ہونے تک پھیل گیا؛ کیونکہ اس نے خود کو بہت مضبوط کیا۔ {پھیلاؤ...: عببرانی۔ گئے}\n9۔ مزید برآں، عزیہ نے یروشلم میں کونے کے دروازے، وادی کے دروازے پر، اور دیوار کے موڑ پر مینار تعمیر کیے، اور انہیں مضبوط کیا۔ {مضبوط: یا، مرمت شدہ}\n10۔ اس نے صحرا میں مینار بھی بنائے، اور کئی کنویں کھودے: کیونکہ اس کے پاس بہت سے مویشی تھے، نشیبی علاقوں اور میدانوں میں، اور پہاڑوں اور کرمل میں بیل کی مشینیں بھی، کیونکہ وہ مویشی پالنے کا شوقین تھا۔ {کھودا...: یا، بہت سے ٹینکرز کاٹ دینا} {کارمل: یا، زرخیز کھیتیں} {ہزرڈری: عبرانی۔ گراؤنڈ}\n11۔ مزید برآں، عزیاہ کے پاس جنگجوؤں کا ایک دستہ تھا، جو ان کے بیان کے مطابق جئیئل کاتب اور ماسیہ حکمران کے ہاتھوں سے جنگ کے لیے نکلے، جو بادشاہ کے کپتانوں میں سے ایک حنانیاہ کے ہاتھوں تھا۔\n12۔ بہادر مردوں کے بزرگوں میں سے سردار کی کل تعداد دو ہزار چھ سو تھی۔\n13۔ اور ان کے ہاتھوں ایک فوج تھی، تین لاکھ سات ہزار پانچ سو، جو طاقتور طاقت کے ساتھ جنگ کر رہی تھی، تاکہ بادشاہ کی دشمن کے خلاف مدد کر سکے۔ {ایک فوج: عبرانی۔ فوج کی طاقت}\n14۔ اور عزیہ نے ان کے لیے تمام لشکر کے ڈھال، نیزے، خود بند، ہیبرجن، کمانیں اور پتھر پھینکنے کے لیے تیار کیا۔ {سلنگز...: عبرانی۔ سلنگز کے پتھر}\n15۔ اور اس نے یروشلم میں ایسے انجن بنائے، جو چالاک لوگوں نے ایجاد کیے، تاکہ وہ میناروں اور دیواروں پر تیر اور بڑے پتھر چلا سکیں۔ اور اس کا نام دور دور تک پھیل گیا؛ کیونکہ اسے حیرت انگیز مدد ملی، یہاں تک کہ وہ مضبوط ہو گیا۔ {پھیلاؤ: ہیب۔ آگے بڑھا}\n16۔ لیکن جب وہ مضبوط ہوا، اس کا دل تباہی کے لیے اٹھ گیا: کیونکہ اس نے خداوند اپنے خدا کے خلاف سرکشی کی، اور خداوند کے مندر میں جا کر لوبان کی قربان گاہ پر لوبان جلائی۔\n17۔ اور عزریاہ کاهن اس کے پیچھے اندر گیا، اور اس کے ساتھ خداوند کے چالیس کاہن، جو بہادر لوگ تھے:\n18۔ اور انہوں نے بادشاہ عزیاہ کا مقابلہ کیا اور اسے کہا، عزیاہ، یہ تمہارے لیے نہیں کہ خداوند کے لیے لوبان جلاؤ، بلکہ ان کاہنوں کے لیے جو ہارون کے بیٹے ہیں، جو لوبان جلانے کے لیے وقف ہیں: مقدس مقام سے باہر نکل جاؤ؛ کیونکہ تم نے گناہ کیا ہے؛ نہ ہی یہ {ہو گا} خداوند خدا کی طرف سے تیری عزت کے لیے۔\n19۔ پھر عزیاہ غصے میں آ گیا، اور اس کے ہاتھ میں خوشبو جلانے کے لیے ایک بخور تھی: اور جب وہ کاہنوں پر غصہ تھا، تو کوڑھ اس کے ماتھے پر خداوند کے گھر میں کاہنوں کے سامنے، دھوپ کے قربان گاہ کے پاس سے اٹھ گیا۔\n20۔ اور عزریاہ سردار کاہن، اور تمام کاہنوں نے اسے دیکھا، اور دیکھتے ہی وہ اپنے ماتھے پر کوڑھ کا شکار تھا، اور اسے وہاں سے باہر نکال دیا؛ ہاں، خود بھی باہر جانے کے لیے جلدی کیا، کیونکہ خداوند نے اسے متاثر کیا تھا۔\n21۔ اور عزیہ بادشاہ اپنی موت تک کوڑھی رہا، اور کئی گھروں میں رہتا رہا، {جذام} تھا؛ کیونکہ وہ خداوند کے گھر سے کٹ گیا تھا: اور اس کا بیٹا یوتھم بادشاہ کے گھر پر تھا، جو زمین کے لوگوں کا فیصلہ کرتا تھا۔ {کئی: عبوری۔ مفت}\n22۔ اب، عزیاہ کے باقی اعمال سب سے پہلے اور آخر، یسعیاہ نبی، اموز کے بیٹے نے لکھا۔\n23۔ یوں عزیاہ اپنے آبا و اجداد کے ساتھ سو گیا، اور انہوں نے اسے اس کے آباؤ اجداد کے ساتھ اس تدفین کے میدان میں دفن کیا جو {بادشاہوں} کی ملکیت تھا؛ کیونکہ انہوں نے کہا، وہ کوڑھی ہے: اور اس کا بیٹا یوتھم اس کی جگہ حکومت کرنے لگا۔","1۔ یوتھم {تھا} کی عمر پچیس سال تھی جب اس نے حکومت شروع کی، اور اس نے یروشلم میں سولہ سال حکومت کی۔ ان کی والدہ کا نام بھی یروشہ تھا، جو زادوک کی بیٹی تھیں۔\n2۔ اور اس نے خداوند کی نظر میں جو کچھ تھا کیا، جیسا کہ اس کے باپ عزیہ نے کیا: لیکن وہ خداوند کے مندر میں داخل نہیں ہوا۔ اور لوگوں نے پھر بھی کرپٹ کر دیا۔\n3۔ اس نے خداوند کے گھر کا بلند دروازہ بنایا، اور اوفیل کی دیوار پر بہت کچھ تعمیر کیا۔ {اوفل: یا، مینار}\n4۔ اس کے علاوہ اس نے یہوداہ کے پہاڑوں میں شہر تعمیر کیے، اور جنگلات میں قلعے اور مینار بنائے۔\n5۔ اس نے عمونیوں کے بادشاہ سے بھی لڑائی کی اور ان پر غالب آ گیا۔ اور آمون کے بچوں نے اسی سال اسے سو ٹیلنٹ چاندی، دس ہزار گندم اور دس ہزار جو دیے۔ آمون کے بچوں نے اس کے لیے اتنا کچھ ادا کیا، دوسرے سال اور تیسرے سال دونوں۔ {تو...: عبرانی۔ یہی بات ہے}\n6۔ یوں یوتھم طاقتور ہو گیا، کیونکہ اس نے خداوند اپنے خدا کے سامنے اپنے راستے تیار کیے۔ {تیار: یا، قائم}\n7۔ اب یوتھم کے باقی اعمال، اس کی تمام جنگیں اور اس کے طریقے، یہ سب اسرائیل اور یہوداہ کے بادشاہوں کی کتاب میں لکھے گئے ہیں۔\n8۔ وہ پانچ بیس سال کے تھے جب انہوں نے حکومت شروع کی، اور یروشلم میں سولہ سال حکومت کی۔\n9۔ اور یوتام اپنے باپ و اجداد کے ساتھ سویا، اور انہوں نے اسے داؤد کے شہر میں دفن کیا: اور اس کا بیٹا آحاز اس کی جگہ بادشاہی کرنے لگا۔","1۔ آحاز بیس سال کا تھا جب اس نے حکومت شروع کی، اور یروشلم میں سولہ سال حکومت کی: لیکن اس نے خداوند کی نظر میں جو تھا، جیسا کہ داؤد اپنے باپ کی طرح درست تھا، وہ درست نہیں تھا:\n2۔ کیونکہ وہ اسرائیل کے بادشاہوں کے راستوں پر چلتا رہا، اور بعلیم کے لیے پگھلے ہوئے مجسمے بھی بنایا۔\n3۔ اس کے علاوہ اس نے ہنوم کے بیٹے کی وادی میں لوبان جلائی، اور اس کے بچوں کو آگ میں جلا دیا، ان کافروں کی گناہوں کے بعد جنہیں خداوند نے بنی اسرائیل کے سامنے نکال دیا تھا۔ {جلایا گیا...: یا، قربانی دی گئی}\n4۔ اس نے اونچی جگہوں، پہاڑیوں پر، اور ہر سبز درخت کے نیچے بھی قربانی دی اور لوبان جلائی۔\n5۔ اسی لیے خداوند نے اسے شام کے بادشاہ کے ہاتھ میں دیا؛ اور انہوں نے اسے مارا، اور بہت سے قیدیوں کو لے کر دمشق لے آئے۔ اور اسے اسرائیل کے بادشاہ کے ہاتھ میں بھی دے دیا گیا، جس نے اسے زبردست قتل عام سے شکست دی۔ {دمشق: عبرانی۔ دارمیسیک}\n6۔ کیونکہ رملیاہ کے بیٹے پیکاہ نے یہوداہ میں ایک لاکھ بیس ہزار کو ایک دن میں قتل کیا، {جو سب بہادر تھے}؛ کیونکہ انہوں نے اپنے باپ دادا کے خداوند خدا کو چھوڑ دیا تھا۔ {بہادر...: عبرانی۔ بہادری کے بیٹے}\n7۔ اور زکری، افرائیم کا ایک طاقتور آدمی، نے بادشاہ کے بیٹے ماسیہ کو قتل کیا، اور گھر کے گورنر عزریکم کو، اور بادشاہ کے ساتھ والے الکانہ کو۔ {اگلا...: عبرانی۔ دوسرا بادشاہ کے لیے}\n8۔ اور بنی اسرائیل نے اپنے بھائیوں میں سے دو لاکھ عورتیں، بیٹے اور بیٹیاں قید کر لیں، ان سے بہت سا مال چھین لیا اور مال غنیمت سامریہ لے آئے۔\n9۔ لیکن خداوند کا ایک نبی وہاں تھا، جس کا نام {اودید} تھا: اور وہ اس لشکر کے سامنے گیا جو سامریہ آئی تھی، اور ان سے کہا، دیکھو، کیونکہ تمہارے آباؤ اجداد کے خداوند خدا نے یہوداہ پر غصہ کیا، اس نے انہیں تمہارے ہاتھ میں دے دیا، اور تم نے انہیں غصے میں مار ڈالا {جو آسمان تک پہنچتا ہے}۔\n10۔ اور اب تم چاہتے ہو کہ یہوداہ اور یروشلم کے بچوں کے تحت اپنے غلام اور غلام رہیں: {لیکن کیا تمہارے ساتھ بھی، حتیٰ کہ تمہارے ساتھ بھی، خداوند تمہارے خدا کے خلاف گناہ نہیں ہیں؟\n11۔ اب میری بات سنو، اور قیدیوں کو دوبارہ آزاد کرو، جنہیں تم نے اپنے بھائیوں میں قید کیا ہے: کیونکہ خداوند کا شدید غضب تم پر ہے۔\n12۔ پھر افرائیم کے بچوں کے کچھ سروں، عزریاہ یوحنان کا بیٹا، بریخیاہ مشیلموت کا بیٹا، اور یحزقیاہ شلم کا بیٹا، اور عماسہ ہدلائی کا بیٹا، ان کے خلاف کھڑے ہو گئے جو جنگ سے آئے تھے،\n13۔ اور میں نے ان سے کہا، تم قیدیوں کو یہاں نہیں لاؤ گے، کیونکہ جب ہم نے خداوند کے خلاف پہلے ہی گناہ کیا ہے، تم ہمارے گناہوں اور گناہوں میں مزید اضافہ کرنا چاہتے ہو: کیونکہ ہمارا گناہ بہت بڑا ہے، اور اسرائیل کے خلاف شدید غضب ہے۔\n14۔ یوں مسلح افراد نے قیدیوں اور مال غنیمت کو شہزادوں اور تمام جماعت کے سامنے چھوڑ دیا۔\n15۔ اور جن لوگوں کے نام بیان کیے گئے تھے، وہ اٹھ کھڑے ہوئے، قیدیوں کو لے گئے، اور مال غنیمت سے ان میں سے تمام ننگے لوگوں کو کپڑے پہنائے، انہیں سجاوٹے، جوتے باندھوئے، انہیں کھانا اور پینا دیا، مسح کیا، اور کمزور سب کو گدھوں پر اٹھا کر یریحو لے گئے،  کھجور کے درختوں کا شہر، اپنے بھائیوں کے لیے: پھر وہ سامریہ واپس چلے گئے۔\n16۔ اسی وقت بادشاہ آحاز نے آشور کے بادشاہوں کو اس کی مدد کے لیے بھیجا۔\n17۔ کیونکہ ایک بار پھر ایڈومی آئے اور یہوداہ کو مارا، اور قیدیوں کو لے گئے۔ {قیدی: عبرانی۔ ایک قید}\n18۔ فلسطینیوں نے نچلے علاقے کے شہروں اور یہوداہ کے جنوب پر بھی حملہ کیا، اور بیت شمش، اجالون، گیدروت، شوخو اور ان کے دیہات کے ساتھ، تیمنا پر قبضہ کر لیا، جن کے گاؤں بھی گمزو اور ان کے گاؤں تھے: اور وہ وہاں آباد ہوئے۔\n19۔ کیونکہ خداوند نے یہوداہ کو اسرائیل کے بادشاہ آحاز کی وجہ سے نیچا دکھایا؛ کیونکہ اس نے یہوداہ کو ننگا بنایا، اور خداوند کے خلاف گناہ کیا۔\n20۔ اور آشور کا بادشاہ ٹلگاتپلنیسر اس کے پاس آیا، اسے پریشان کیا، لیکن اسے مضبوط نہ کیا۔\n21۔ کیونکہ آحاز نے خداوند کے گھرانے کا ایک حصہ اور بادشاہ کے گھرانے اور شہزادوں کا حصہ چھین لیا، اور اسے آشور کے بادشاہ کو دے دیا، لیکن اس نے اس کی مدد نہیں کی۔\n22۔ اور اپنی مصیبت کے وقت اس نے خداوند کے خلاف مزید زیادتی کی: یہ {وہ} بادشاہ آہاز ہے۔\n23۔ کیونکہ اس نے دمشق کے دیوتاؤں کو قربانی دی، جنہوں نے اسے مارا: اور اس نے کہا، چونکہ شام کے بادشاہوں کے دیوتا ان کی مدد کرتے ہیں، {لہٰذا} میں ان کے لیے قربانی دوں گا تاکہ وہ میری مدد کریں۔ لیکن وہ اس کی تباہی تھے، اور پورے اسرائیل کی۔ {دمشق: عبرانی۔ دارمیسیک}\n24۔ اور آحاز نے خدا کے گھر کے برتن جمع کیے، خدا کے گھر کے برتن ٹکڑوں میں کاٹ دیے، اور خداوند کے گھر کے دروازے بند کر دیے، اور اسے یروشلم کے ہر کونے میں قربان گاہ بنا دی۔\n25۔ اور یہوداہ کے ہر کئی شہروں میں اس نے اونچی جگہیں بنائیں تاکہ دوسرے دیوتاؤں کے لیے خوشبو جلائی جا سکے، اور اپنے آباؤ اجداد کے خداوند خدا کو ناراض کروایا۔ {جلانا: یا، پیش کرنا}\n26۔ اب اس کے باقی اعمال اور اس کے تمام راستے، سب سے پہلے اور آخری، دیکھیں، وہ یہوداہ اور اسرائیل کے بادشاہوں کی کتاب میں لکھے گئے ہیں۔\n27۔ اور آحاز اپنے باپ اجداد کے ساتھ سو گیا، اور انہوں نے اسے شہر میں دفن کیا، {حتیٰ کہ} یروشلم میں: لیکن اسے اسرائیل کے بادشاہوں کی قبروں میں نہیں لے گئے، اور حزقیاہ اس کے بیٹے نے اس کی جگہ حکومت کی۔","1۔ حزقیاہ نے {جب وہ تھا} پانچ بیس سال کا تھا، حکومت شروع کی، اور یروشلم میں نو بیس سال حکومت کی۔ اور اس کی والدہ کا نام ابیجہ تھا، زکریا کی بیٹی۔\n2۔ اور اس نے وہ کیا جو خداوند کے سامنے تھا، جیسا کہ اس کے باپ نے داؤد نے کیا تھا۔\n3۔ اس نے اپنی حکومت کے پہلے سال میں، پہلے مہینے میں، خداوند کے گھر کے دروازے کھولے اور انہیں مرمت کیا۔\n4۔ اور اس نے کاہنوں اور لاویوں کو بلایا اور انہیں مشرقی گلی میں جمع کیا،\n5۔ اور ان سے کہا، اے لاویو، میری بات سنو، اب اپنے آپ کو پاک کرو، اور اپنے آباؤ اجداد کے خداوند خدا کے گھر کو پاک کرو، اور گندگی کو مقدس جگہ سے نکالو۔\n6۔ کیونکہ ہمارے آباؤ اجداد نے گناہ کیا ہے، اور وہ سب کچھ کیا جو خداوند ہمارے خدا کی نظر میں برا تھا، اور اسے چھوڑ دیا، اور اپنے چہرے خداوند کے گھر سے موڑ لیے، اور اپنی پیٹھ موڑ لی۔ {ان کا...: عبرانی۔ گردن کو دیا گیا}\n7۔ انہوں نے برآمدے کے دروازے بند کر دیے ہیں، چراغ بجھا دیے ہیں، اور نہ لوبان جلایا ہے اور نہ ہی مقدس جگہ پر اسرائیل کے خدا کو نذرانہ پیش کیا ہے۔\n8۔ اسی لیے خداوند کا غضب یہوداہ اور یروشلم پر تھا، اور اس نے انہیں مصیبت، حیرت اور پھونکنے میں مبتلا کر دیا، جیسا کہ تم اپنی آنکھوں سے دیکھتے ہو۔ {مسئلہ: عبوری۔ ہنگامہ}\n9۔ کیونکہ دیکھو، ہمارے باپ تلوار کے ہاتھوں مارے گئے ہیں، اور ہمارے بیٹے، بیٹیاں اور بیویاں اس کے لیے قید میں ہیں۔\n10. اب میرے دل میں یہ ہے کہ میں اسرائیل کے خداوند خدا سے عہد کروں، تاکہ اس کا شدید غضب ہم سے دور ہو جائے۔\n11۔ میرے بیٹو، اب غفلت نہ کرو، کیونکہ خداوند نے تمہیں اس کے سامنے کھڑے ہونے کے لیے چنا ہے، اس کی خدمت کرنے کے لیے اور اس کی خدمت کرنے اور لوبان جلانا ہے۔ {نہ ہو...: یا، اب دھوکہ نہ کھانا} {جلانا...: یا، قربانی پیش کرنا}\n12۔ پھر لاوی ابھرے، ماہتھ اماسائی کا بیٹا، اور جوئیل عزریاہ کا بیٹا، کوہثیوں کے بیٹوں سے؛ اور مراری کے بیٹوں کیش کے بیٹے، عبدی کا بیٹا، اور عزریاہ جہلیل کا بیٹا؛ اور گرشونیوں کے بیٹے۔ جواہ، زیمہ کا بیٹا، اور عدن جو جوح کا بیٹا تھا:\n13۔ اور الیزافان کے بیٹوں سے؛ شمری، اور جیئل: اور آساف کے بیٹوں سے؛ زکریا اور متانیا:\n14۔ اور ہیمن کے بیٹوں کی؛ یہیئل، اور شمعی: اور یدوتون کے بیٹوں سے؛ شیمایہ، اور اوزیئل۔\n15۔ اور انہوں نے اپنے بھائیوں کو جمع کیا، خود کو پاک کیا، اور بادشاہ کے حکم کے مطابق، خداوند کے الفاظ کے مطابق، گھر کو خداوند سے پاک کرنے آئے۔ {الفاظ کے ذریعے...: یا، خداوند کے کاروبار میں}\n16۔ اور کاہنوں نے خداوند کے گھر کے اندرونی حصے میں جا کر اسے پاک کیا، اور خداوند کے مندر میں پائی جانے والی تمام ناپاکی کو خداوند کے گھر کے صحن میں نکال دیا۔ اور لاویوں نے {اسے} کو لے کر بیرون ملک دریا کیدرون میں لے گئے۔\n17۔ اب وہ پہلے مہینے کے پہلے دن کو تقدیس کے لیے روانہ ہوئے، اور مہینے کے آٹھویں دن خداوند کے برآمدے پر آئے: یوں انہوں نے خداوند کے گھر کو آٹھ دنوں میں مقدس کیا؛ اور پہلے مہینے کے سولہویں دن ان کا اختتام ہوا۔\n18۔ پھر وہ حزقیاہ بادشاہ کے پاس گئے اور کہا، \"ہم نے خداوند کے سارے گھر، اور سلائی کی قربان گاہ کو اس کے تمام برتنوں سمیت اور روٹی کی میز اور اس کے تمام برتنوں سے پاک کر دیا ہے۔\n19۔ مزید برآں، وہ تمام برتن جنہیں بادشاہ آحاز نے اپنی گناہ میں پھینک دیا، ہم نے تیار اور مقدس کیا ہے، اور دیکھو، وہ خداوند کے قربان گاہ کے سامنے ہیں۔\n20۔ پھر حزقیاہ بادشاہ صبح سویرے اٹھا، شہر کے حکمرانوں کو جمع کیا اور خداوند کے گھر چلا گیا۔\n21۔ اور انہوں نے سات بیل، سات مینڈے، سات بھیڑ اور سات بکریاں لائیں، گناہ کی قربانی کے طور پر بادشاہی، مقدس مقام کے لیے، اور یہوداہ کے لیے۔ اور اس نے کاہنوں، ہارون کے بیٹوں کو حکم دیا کہ وہ انہیں خداوند کے مذبح پر پیش کریں۔\n22۔ تو انہوں نے بیل مارے، اور پجاریوں نے خون وصول کیا، اور قربان گاہ پر چھڑک دیا: اسی طرح جب انہوں نے مینڈھے مارے، تو انہوں نے خون قربان گاہ پر چھڑکا: بھیڑوں کو بھی مارا، اور خون قربان گاہ پر چھڑکا۔\n23۔ اور انہوں نے بادشاہ اور جماعت کے سامنے گناہ کی قربانی کے لیے بکریاں پیش کیں؛ اور انہوں نے ان پر ہاتھ رکھا: {آوارہ: عبرانی۔ قریب}\n24۔ اور کاہنوں نے انہیں قتل کر دیا، اور انہوں نے اپنے خون سے قربان گاہ پر صلح کی، تاکہ تمام اسرائیل کے لیے کفارہ بن سکیں: کیونکہ بادشاہ نے حکم دیا کہ تمام اسرائیل کے لیے جلنے کی قربانی اور گناہ کی قربانی پیش کی جائے۔\n25۔ اور اس نے لاویوں کو خداوند کے گھر میں جھنجوں، زبوروں اور ہارپ کے ساتھ رکھا، جیسا کہ داؤد اور گاد بادشاہ کا بصیرت کرنے والے اور ناتھن نبی کے حکم کے مطابق تھا: کیونکہ خداوند کا حکم بھی اس کے نبیوں کے ذریعے تھا۔ {خداوند کا حکم: عبرانی۔ خداوند کے ہاتھ سے حکم دیا گیا ہے} {از: عبرانی ہاتھوں سے}\n26۔ اور لاوی داؤد کے آلات کے ساتھ کھڑے تھے، اور کاہنوں نے بگل بجایا۔\n27۔ اور حزقیاہ نے حکم دیا کہ قربانی قربان گاہ پر پیش کی جائے۔ اور جب جلانے کی قربانی شروع ہوئی، تو خداوند کا گیت بھی بگل بجانے اور اسرائیل کے بادشاہ داؤد کے مقرر کردہ آلات سے شروع ہوا۔ {جب: عبرانی ان دی ٹائم} {آلات: عبرانی۔ آلات کے ہاتھ}\n28۔ اور تمام جماعت نے عبادت کی، گلوکار گانے لگے، اور بگل بجانے والوں نے بجایا: {اور} سب {یہ سلسلہ جاری رہا} جب تک کہ نذرانہ ختم نہ ہو گیا۔ {گلوکار: عبرانی۔ گانا}\n29۔ اور جب انہوں نے نذرانہ ختم کیا، بادشاہ اور اس کے ساتھ موجود سب نے جھک کر عبادت کی۔ {موجود: عبرانی مل گیا}\n30۔ مزید برآں، حزقیاہ بادشاہ اور شہزادوں نے لاویوں کو حکم دیا کہ وہ داؤد کے الفاظ سے خداوند کی حمد و ثمر گائیں، اور عصفہ پیش گو کے الفاظ سے۔ اور وہ خوشی سے تعریفیں گاتے، سر جھکاتے اور عبادت کرتے۔\n31۔ پھر حزقیاہ نے جواب دیا اور کہا، \"اب تم نے خود کو خداوند کے لیے وقف کر لیا ہے، قریب آؤ اور قربانیاں اور شکریہ ادا کرو خداوند کے گھر میں۔ اور جماعت قربانیاں اور شکریہ کی قربانیاں لاتی رہی؛ اور جتنے بھی مفت دل کی نذرانے تھے۔ {تقدیس...: یا، تمہارا ہاتھ بھر دیا}\n32۔ اور جماعت نے جو سلائی ہوئی قربانیوں کی تعداد لائی تھی، وہ تین سو بیل، سو مینڈے، اور دو سو بکری تھے: یہ سب خداوند کے لیے جلانے کی قربانی کے لیے تھے۔\n33۔ اور مقدس چیزیں چھ سو بیل اور تین ہزار بھیڑیں تھیں۔\n34۔ لیکن کاہن بہت کم تھے، اس لیے وہ تمام جلانے والے نذرانہ نہیں اتار سکتے تھے: اسی لیے ان کے بھائی لاوی نے ان کی مدد کی، جب تک کام ختم نہ ہو گیا، اور جب تک {دیگر} کاہنوں نے خود کو پاک نہ کر لیا: کیونکہ لاوی اپنے آپ کو پاکیزہ کرنے کے لیے زیادہ سیدھے دل والے تھے بنسبت کاہنوں کے۔ {مدد کی...: عبرانی۔ انہیں مضبوط کیا}\n35۔ اور سلائی کی قربانیاں بھی وافر مقدار میں تھیں، صلح کی نذرانے کی چربی کے ساتھ، اور ہر جلانے کی قربانی کے لیے شراب کی قربانی۔ یوں خداوند کے گھر کی خدمت ترتیب دی گئی۔\n36۔ اور حزقیاہ اور تمام لوگ خوش ہوئے کہ خدا نے لوگوں کو تیار کیا: کیونکہ یہ کام اچانک ہو گیا۔","1۔ اور حزقیاہ نے تمام اسرائیل اور یہوداہ کو بھیجا، اور افرائیم اور منسی کو بھی خطوط لکھے کہ وہ یروشلم میں خداوند کے گھر آئیں، تاکہ اسرائیل کے خداوند خدا کے پاس پاس منائیں۔\n2۔ کیونکہ بادشاہ نے، اپنے شہزادوں، اور یروشلم کی تمام جماعت سے مشورہ کیا تھا کہ دوسرے مہینے میں فسح منایا جائے۔\n3۔ کیونکہ اس وقت وہ اسے برقرار نہیں رکھ سکتے تھے، کیونکہ کاہنوں نے خود کو مناسب طور پر مقدس نہیں کیا تھا، اور نہ ہی لوگ یروشلم میں جمع ہوئے تھے۔\n4۔ اور یہ بات بادشاہ اور تمام جماعت کو پسند آئی۔ {خوش...: عبرانی۔ بادشاہ کی نظر میں درست تھا}\n5۔ چنانچہ انہوں نے ایک فرمان جاری کیا کہ پورے اسرائیل میں، بیرشبع سے لے کر دان تک، یہ اعلان کیا جائے کہ وہ یروشلم میں اسرائیل کے خداوند کے پاس پاس منانے آئیں: کیونکہ انہوں نے اتنے عرصے سے ایسا نہیں کیا تھا جیسا کہ لکھا گیا تھا۔\n6۔ تو یہ خطوط بادشاہ اور اس کے شہزادوں کے خطوط کے ساتھ پورے اسرائیل اور یہوداہ میں بھیجے گئے، اور بادشاہ کے حکم کے مطابق، اے بنی اسرائیل کو، ابراہیم، اسحاق اور اسرائیل کے خداوند خدا کی طرف دوبارہ رجوع کرو، اور وہ تمہاری باقیات کے پاس واپس جائے گا جو آشور کے بادشاہوں کے ہاتھوں سے بچ چکے ہیں۔ {از: عبرانی سے۔ ہاتھ سے}\n7۔ اور تم اپنے باپ و اجداد اور اپنے بھائیوں کی طرح مت بنو، جنہوں نے اپنے باپ دادا کے خداوند کے خلاف گناہ کیا، جس نے انہیں برباد کر دیا، جیسا کہ تم دیکھتے ہو۔\n8۔ اب تم اپنے باپ اجداد کی طرح ضد نہ کرو، بلکہ} خداوند کے سامنے سر تسلیم خم کرو، اور اس کے مقدس مقام میں داخل ہو جاؤ، جسے اس نے ہمیشہ کے لیے مقدس قرار دیا ہے: اور اپنے خداوند خدا کی عبادت کرو، تاکہ اس کے غضب کی شدت تم سے دور ہو جائے۔ {بنو...: عبرانی۔ اپنی گردنیں سخت نہ کرو} {ہتھیار ڈالو...: عبرانی۔ ہاتھ دو}\n9۔ اگر تم دوبارہ خداوند کی طرف رجوع کرو، تو تمہارے بھائی اور تمہارے بچے ان کے سامنے رحم پائیں گے جو انہیں قید کرتے ہیں، تاکہ وہ اس زمین میں واپس آئیں: کیونکہ خداوند تمہارا خدا مہربان اور مہربان ہے، اور اگر تم اس کی طرف لوٹ جاؤ تو وہ اپنا چہرہ تم سے نہیں ہٹے گا۔\n10۔ یوں ستون شہر سے شہر تک افرایم اور منسی کے علاقے میں گزرتے رہے، یہاں تک کہ زبولون تک: لیکن وہ ان پر ہنس کر مذاق اڑاتے اور مذاق اڑاتے۔\n11۔ اس کے باوجود آشر، منسی اور زبولون کے مختلف لوگ عاجز ہوئے اور یروشلم آئے۔\n12۔ یہوداہ میں خدا کا ہاتھ انہیں ایک دل دے گا تاکہ وہ بادشاہ اور شہزادوں کے حکم کو خداوند کے کلام سے پورا کریں۔\n13۔ اور وہاں یروشلم میں بہت سے لوگ جمع ہوئے تاکہ دوسرے مہینے میں بغیر خمیر کی روٹی کی دعوت منائی جا سکے، جو بہت بڑی جماعت تھی۔\n14۔ اور وہ اٹھے اور یروشلم میں موجود قربان گاہیں لے گئیں، اور تمام لوبان کے قربان گاہیں ہٹا کر انہیں کدرون نالے میں پھینک دیا۔\n15۔ پھر انہوں نے دوسرے مہینے کے چودہویں دن کو فسح کا دن قربان کر دیا: اور کاهن اور لاوی شرمندہ ہو گئے، خود کو پاک کر کے خدا کے گھر میں جلنے والی قربانیاں لے آئے۔\n16۔ اور وہ اپنی جگہ پر کھڑے ہو گئے، جیسا کہ موسیٰ خدا کے آدمی کے قانون کے مطابق تھا: کاہنوں نے لاویوں کے ہاتھ کا خون چھڑکا۔ {ان کی جگہ: عبرانی۔ ان کی حیثیت}\n17۔ کیونکہ جماعت میں بہت سے ایسے تھے جو پاک نہیں تھے: اس لیے لاویوں پر یہ ذمہ داری دی گئی کہ وہ ہر پاک شخص کے لیے فسح کو قتل کریں، تاکہ انہیں خداوند کے سامنے پاک کیا جا سکے۔\n18۔ کیونکہ بہت سے لوگ، حتیٰ کہ افرائیم، منسیہ، عیساکر، اور زبولون کے بہت سے لوگوں نے خود کو پاک نہیں کیا تھا، پھر بھی انہوں نے فسح کو اس کے بغیر نہیں کھایا۔ لیکن حزقیاہ نے ان کے لیے دعا کی اور کہا، نیک خداوند سب کو معاف کر دے\n19۔ {جو} اپنے دل کو خدا کی تلاش کے لیے تیار کرتا ہے، جو اس کے باپ اجداد کا خداوند ہے، اگرچہ {و} مقدس مقام کی پاکیزگی کے مطابق {پاک نہیں ہو}۔\n20۔ اور خداوند نے حزقیاہ کی بات سنی اور لوگوں کو شفا دی۔\n21۔ اور یروشلم میں موجود بنی اسرائیل نے سات دن بغیر خمیر کی روٹی کی عید بڑی خوشی سے منائی: اور لاوی اور کاہنوں نے روز بہ دن خداوند کی تعریف کی، {بلند آواز میں سازوں کے ساتھ} خداوند کے لیے گاتے رہے۔ {موجود: عبرانی مل گیا} {بلند آواز...: عبرانی۔ طاقت کے آلات}\n22۔ اور حزقیاہ نے ان تمام لاویوں سے تسلی سے بات کی جو خداوند کی اچھی تعلیم دیتے تھے: اور انہوں نے سات دن کے تہوار میں کھانا کھایا، صلح کی قربانیاں پیش کیں اور اپنے باپ و اجداد کے خداوند خدا کے سامنے اعتراف کیا۔ {آرام سے...: عبرانی۔ سب کے دل تک}\n23۔ اور پوری مجمع نے مشورہ کیا کہ باقی سات دن رکھیں: اور انہوں نے خوشی سے سات دن رکھے۔\n24۔ کیونکہ یہوداہ کے بادشاہ حزقیاہ نے جماعت کو ایک ہزار بیل اور سات ہزار بھیڑ دی؛ اور شہزادوں نے جماعت کو ہزار بیل اور دس ہزار بھیڑیں دیں: اور بہت سے پادریوں نے خود کو مقدس کیا۔ {دیا تھا: عبوری۔ اٹھایا گیا، یا، پیش کیا گیا} {دیا: عبرانی۔ اٹھایا گیا، یا، پیش کیا گیا}\n25۔ اور یہوداہ کی تمام جماعت، کاہنوں اور لاویوں کے ساتھ، اور اسرائیل سے نکلنے والی تمام جماعت، اور اسرائیل کی سرزمین سے نکلنے والے اجنبی جو یہوداہ میں بستے تھے، خوشی منائیں۔\n26۔ یوں یروشلم میں بڑی خوشی تھی: کیونکہ سلیمان کے زمانے سے، داؤد کے بیٹے کے وقت سے، یروشلم میں ایسا کچھ نہیں تھا۔\n27۔ پھر کاہن، لاوی، اٹھے اور لوگوں کو برکت دی، اور ان کی آواز سنی گئی، اور ان کی دعا اس کے مقدس گھر تک پہنچی، {حتیٰ کہ} آسمان تک۔ {اس کا مقدس...: عبرانی۔ ان کی پاکیزگی کی رہائش گاہ","1۔ جب یہ سب ختم ہو گیا، تو موجود تمام اسرائیل یہوداہ کے شہروں میں نکل گئے، اور مجسموں کو توڑ دیا، جھنڈوں کو کاٹ دیا، اور یہوداہ اور بنیامین کے تمام اونچی جگہوں اور قربان گاہوں کو گرا دیا، یہاں تک کہ انہوں نے سب کو مکمل طور پر تباہ کر دیا۔ پھر تمام بنی اسرائیل واپس آ گئے، ہر آدمی اس کے قبضے میں، اپنے اپنے شہروں میں۔ {موجود: عبرانی مل گیا} {تصاویر: عبرانی۔ مجسمے} {جب تک...: عبرانی جب تک کہ اختتام نہ ہو}\n2۔ اور حزقیاہ نے کاہنوں اور لاویوں کے راستے مقرر کیے، ہر آدمی اپنی خدمت کے مطابق، کاہنوں اور لاویوں کو جلانے کی قربانیوں اور صلح کی قربانیوں کے لیے، خدمت کرنے، شکر ادا کرنے، اور خداوند کے خیموں کے دروازوں پر تعریف کرنے کے لیے۔\n3۔ {اس نے بادشاہ کے مال کا حصہ بھی مقرر کیا} جلانے والی نذرانوں کے لیے، {یعنی}، صبح اور شام کی جلنے کی قربانیوں، اور سبت کے لیے، نئے چاندوں کے لیے، اور مقررہ تہواروں کے لیے، جیسا کہ {یہ لارڈ کے قانون میں لکھا ہے}۔\n4۔ مزید برآں، اس نے یروشلم میں رہنے والے لوگوں کو حکم دیا کہ وہ کاہنوں اور لاویوں کا حصہ دیں تاکہ وہ خداوند کے قانون میں حوصلہ افزائی کریں۔\n5۔ اور جیسے ہی حکم باہر آیا، بنی اسرائیل نے دانہ، شراب، تیل، شہد اور کھیت کی تمام پیداوار کے پہلے پھل وافر مقدار میں لائے تھے؛ اور تمام چیزوں کا عشر انہیں وافر مقدار میں لاتا تھا۔ {آیا...: عبوری۔ بریک فورتھ} {جان: یا، تاریخیں}\n6۔ اور اسرائیل اور یہوداہ کے بچوں کے بارے میں، جو یہوداہ کے شہروں میں رہتے تھے، انہوں نے بیلوں اور بھیڑوں کی عشر اور مقدس چیزوں کا عشر بھی لایا جو خداوند ان کے خدا کے لیے وقف تھے، اور انہیں ڈھیر کی صورت میں رکھ دیا۔ {ہیپس کے ذریعے: عبرانی بہت زیادہ، بہت زیادہ}\n7۔ تیسرے مہینے میں انہوں نے ڈھیر کی بنیاد رکھنا شروع کی، اور ساتویں مہینے میں مکمل کیا۔\n8۔ اور جب حزقیاہ اور شہزادے آئے اور ڈھیر دیکھے، تو انہوں نے خداوند اور اس کی قوم اسرائیل کو برکت دی۔\n9۔ پھر حزقیاہ نے کاہنوں اور لاویوں سے ڈھیر کے بارے میں سوال کیا۔\n10۔ اور زادوک خاندان کے سردار کاہن عزریاہ نے اس کا جواب دیا اور کہا، جب سے {لوگ} نے خداوند کے گھر میں قربانیاں لانا شروع کیں، ہم نے کافی کھا لیا ہے اور کافی چھوڑ دیا ہے: کیونکہ خداوند نے اپنے لوگوں کو برکت دی ہے؛ اور جو کچھ بچا ہے وہ یہ عظیم دکان ہے۔\n11۔ پھر حزقیاہ نے حکم دیا کہ خداوند کے گھر میں کمرے تیار کیے جائیں؛ اور انہوں نے {ان}، {کمرے: یا، گودام} تیار کیے۔\n12۔ اور نذراں، عشر اور وقف شدہ {چیز} وفاداری سے لائی: جن پر کونونیاہ لاوی {حکمران} تھا، اور شیمئی اس کا بھائی {تھا} اگلے پر۔\n13۔ اور یہیئیل، اور عززیا، اور ناحت، اور اساہیل، اور یریموت، اور یوزآباد، اور ایلیل، اور اسماعیح، اور مہات، اور بنایا، جو کونونیاہ اور شمعی کے ہاتھوں اس کے بھائی کے ماتحت نگران تھے، حزقیاہ بادشاہ کے حکم پر، اور عزریاہ خدا کے گھرانے کا حکمران۔ {نیچے...: عبرانی ہاتھوں پر}\n14۔ اور کورے، امانہ لاوی کا بیٹا، مشرق کی طرف پورٹر، خدا کی آزاد مرضی کی قربانیوں پر تھا، تاکہ خداوند کی قربانیاں اور سب سے مقدس چیزیں تقسیم کرے۔\n15. اور اس کے بعد عدن، منیعین، یشوع، شمعیہ، امریہ، اور شکنیاہ تھے، کاہنوں کے شہروں میں، اپنے مقرر کردہ عہدے میں، تاکہ اپنے بھائیوں کو کورس کے ذریعے دیں، بڑے اور چھوٹے کو بھی: {اگلا...: عبرانی۔ اس کے ہاتھ} {سیٹ...: یا، ٹرسٹ}\n16۔ ان کے مردوں کی نسل کے علاوہ، تین سال کی عمر سے اوپر، {حتیٰ کہ} ہر اس شخص کے لیے جو خداوند کے گھر میں داخل ہوتا ہے، اس کی روزانہ کی خدمت کے لیے ان کے اوقات کے مطابق؛\n17۔ کاهنوں کی نسل نامہ کے بارے میں ان کے باپ و اجداد کے گھرانے کے ذریعے، اور بیس سال سے اس سے زائد عمر کے لاویوں کے لیے، ان کے ارکان کے مطابق تعلیم حاصل کرنا؛\n18۔ اور ان کے تمام ننھے بچوں، ان کی بیویاں، ان کے بیٹوں اور بیٹیوں کی نسب نامہ کے لیے، تمام جماعت کے ذریعے: کیونکہ اپنے مقررہ عہدے میں انہوں نے خود کو پاکیزگی میں پاک کیا: {سیٹ...: یا، ٹرسٹ}\n19۔ ہارون کے بیٹوں کے کاہنوں کے بھی، {جو} اپنے شہروں کے مضافات کے کھیتوں میں، ہر کئی شہروں میں، ان مردوں کو جو نام سے ظاہر کیے جاتے تھے، تاکہ کاہنوں میں سے تمام مردوں کو حصہ دیا جائے، اور لاویوں میں شجرہ نسب کے مطابق شمار کیے جانے والوں کو بھی۔\n20۔ اور اسی طرح حزقیاہ نے پورے یہوداہ میں کیا، اور خداوند کے خدا کے سامنے نیکی، درست اور سچائی کی۔\n21۔ اور ہر اس کام میں جو اس نے خدا کے گھر کی خدمت، قانون اور احکامات میں شروع کیا، اپنے خدا کی تلاش میں، وہ پورے دل سے کیا اور کامیاب ہوا۔","1۔ ان واقعات اور قیام کے بعد، آشور کا بادشاہ سنحریب، آیا، یہوداہ میں داخل ہوا، اور باڑ والے شہروں کے خلاف خیمہ لگایا، اور سوچا کہ وہ انہیں اپنے لیے حاصل کرے گا۔ {جیتنے کے لیے...: عبرانی۔ انہیں توڑنے کے لیے}\n2۔ اور جب حزقیاہ نے دیکھا کہ سنحرب آ گیا ہے، اور وہ یروشلم کے خلاف لڑنے کا ارادہ رکھتا ہے، {وہ...: عبرانی۔ اس کا چہرہ جنگ کے لیے تھا}\n3۔ اس نے اپنے شہزادوں اور طاقتور آدمیوں سے مشورہ کیا کہ وہ ان چشموں کے پانی کو روکا جائے جو شہر سے باہر تھے: اور انہوں نے اس کی مدد کی۔\n4۔ تو بہت سے لوگ جمع ہوئے، جنہوں نے تمام چشمے اور اس ندی کو روک دیا جو زمین کے بیچ سے بہتا تھا، اور کہا، آشور کے بادشاہ کیوں آئیں اور زیادہ پانی تلاش کریں؟ {ران: ہیب۔ اوور فلو}\n5۔ اس نے خود کو مضبوط کیا، اور جو دیوار ٹوٹی تھی اسے تعمیر کیا، اور میناروں تک اور ایک اور دیوار بنائی، اور داؤد کے شہر میں میلو کی مرمت کی، اور ڈارٹس اور ڈھالیں وافر مقدار میں بنائے۔ {ڈارٹس: یا، تلواریں، یا، ہتھیار}\n6۔ اور اس نے لوگوں پر جنگ کے سردار مقرر کیے، انہیں شہر کے دروازے کی گلی میں اپنے پاس جمع کیا، اور آرام سے ان سے کہا، {کہا...: عبرانی۔ اس نے ان کے دل سے بات کی}\n7۔ مضبوط اور بہادر بنو، آشور کے بادشاہ سے نہ ڈرو اور نہ ہی اس کے ساتھ موجود تمام ہجوم سے خوفزدہ ہو: کیونکہ ہمارے ساتھ اس سے زیادہ ہے:\n8۔ اس کے ساتھ گوشت کا بازو ہے؛ بلکہ ہمارے ساتھ خداوند ہمارا خدا ہے جو ہماری مدد کرے گا، اور ہماری لڑائیاں لڑے گا۔ اور لوگوں نے یہوداہ کے بادشاہ حزقیاہ کے الفاظ پر اعتماد کیا۔ {آرام کیا...: عببرانی۔ جھکا}\n9۔ اس کے بعد آشور کے بادشاہ سناخریب نے اپنے خادموں کو یروشلم بھیجا، (لیکن اس نے خود لاخیش اور اپنی پوری طاقت کا محاصرہ کیا)، حزقیاہ بادشاہ یہوداہ کے پاس، اور تمام یہوداہ کے پاس جو یروشلم میں تھے، کہا، {طاقت: عبرانی۔ ڈومینین}\n10۔ ایسا ہی فرماتا ہے آشور کے بادشاہ سنحریب، تم کس پر بھروسہ کرتے ہو کہ تم یروشلم کے محاصرے میں رہو گے؟ {محاصرہ: یا، مضبوط قلعہ}\n11. کیا حزقیاہ تمہیں قائل نہیں کرتا کہ تم خود کو قحط اور پیاس سے مرنے کے لیے قربان کر دو، یہ کہتے ہوئے، ہمارا خداوند ہمیں آشور کے بادشاہ کے ہاتھوں سے نجات دے گا؟\n12. کیا وہی حزقیاہ نے اس کے اونچی مقامات اور قربان گاہیں چھین کر یہوداہ اور یروشلم کو حکم نہیں دیا، یہ کہتے ہوئے کہ تم ایک قربان گاہ کے سامنے عبادت کرو گے اور اس پر لوبان جلاؤ گے؟\n13۔ کیا تم نہیں جانتے کہ میں اور میرے آباؤ اجداد نے {دوسرے} زمینوں کے تمام لوگوں کے ساتھ کیا کیا ہے؟ کیا ان زمینوں کے دیوتا اپنی زمینیں میرے ہاتھ سے نکال سکتے تھے؟\n14. ان تمام دیوتاؤں میں کون تھا جنہیں میرے آباؤ اجداد نے مکمل طور پر تباہ کر دیا، جو اپنے لوگوں کو میرے ہاتھوں سے بچا سکے، کہ تمہارا خدا تمہیں میرے ہاتھوں سے آزاد کر سکے؟\n15۔ لہٰذا حزقیاہ تمہیں دھوکہ نہ دے، نہ تمہیں اس طرح قائل کرے، اور نہ ہی اس پر یقین کرو: کیونکہ کسی بھی قوم یا سلطنت کا کوئی خدا اپنے لوگوں کو میرے ہاتھوں سے اور میرے باپ و اجداد کے ہاتھوں سے بچا نہیں سکا: اور تمہارا خدا تمہیں میرے ہاتھوں سے نجات دے؟\n16۔ اور اس کے بندوں نے خداوند خدا کے خلاف اور اس کے بندے حزقیاہ کے خلاف مزید باتیں کیں۔\n17۔ اس نے اسرائیل کے خداوند خدا پر تنقید کرنے اور اس کے خلاف بولنے کے لیے خطوط بھی لکھے اور کہا، جیسے {دوسرے} ممالک کے دیوتاؤں نے اپنے لوگوں کو میرے ہاتھوں سے آزاد نہیں کیا، ویسے ہی حزقیاہ کا خدا اپنے لوگوں کو میرے ہاتھوں سے نجات نہیں دے گا۔\n18۔ پھر انہوں نے یہودیوں کی زبان میں زور سے یروشلم کے لوگوں سے پکارا، جو دیوار پر تھے، انہیں ڈرا کر اور پریشان کرنے کے لیے؛ کہ وہ شہر پر قبضہ کر سکتے ہیں۔\n19۔ اور انہوں نے یروشلم کے خدا کے خلاف بات کی، جیسے زمین کے لوگوں کے دیوتاؤں کے خلاف، {جو انسانوں کے ہاتھوں کا کام تھا}۔\n20۔ اور اسی وجہ سے حزقیاہ بادشاہ اور نبی یسعیاہ ابن عاموز نے آسمان کی طرف دعا کی اور پکارا۔\n21۔ اور خداوند نے ایک فرشتہ بھیجا، جس نے آشور کے بادشاہ کے کیمپ میں موجود تمام بہادر مردوں اور رہنماؤں اور کپتانوں کو کاٹ دیا۔ لہٰذا وہ شرمندگی کے ساتھ اپنی سرزمین واپس آیا۔ اور جب وہ اپنے خدا کے گھر میں آیا، تو جو لوگ اس کی آنتوں سے نکلے انہوں نے اسے وہاں تلوار سے مار ڈالا۔ {slew...: عبرانی۔ اسے گرا دیا}\n22. یوں خداوند نے حزقیاہ اور یروشلم کے باشندوں کو آشور کے بادشاہ سنحریب، اور سب کے ہاتھوں سے بچایا، اور انہیں ہر طرف سے رہنمائی کی۔\n23۔ اور بہت سے لوگ یروشلم میں خداوند کے لیے تحفے اور یہوداہ کے بادشاہ حزقیاہ کے لیے تحفے لائے تاکہ وہ سب قوموں کی نظر میں عظیم ہو جائے۔ {پیش کرتا ہے: عبرانی۔ قیمتی چیزیں}\n24۔ ان دنوں حزقیاہ موت تک بیمار تھا، اور خداوند سے دعا کرتا تھا، اور اس نے اس سے بات کی، اور اسے ایک علامت دی۔ {دیا...: یا، اس کے لیے معجزہ کیا}\n25۔ لیکن حزقیاہ نے دوبارہ اس احسان کے مطابق نہیں دیا جو اس کے لیے دیا گیا؛ کیونکہ اس کا دل بلند ہو گیا: اس لیے اس پر، یہوداہ اور یروشلم پر غصہ آیا۔\n26۔ اس کے باوجود حزقیاہ نے اپنے دل کے غرور کے لیے خود کو عاجز کیا، {وہ اور یروشلم کے باشندے} دونوں، تاکہ خداوند کا غضب حزقیاہ کے زمانے میں ان پر نہ آیا۔ {پرائیڈ: ہیب۔ اٹھانا}\n27۔ اور حزقیاہ کے پاس بے پناہ دولت اور عزت تھی: اس نے چاندی، سونا، قیمتی پتھر، مصالحہ، ڈھال اور ہر قسم کے خوبصورت زیورات کے خزانے بنائے۔ {خوشگوار...: عبرانی۔ خواہش کے آلات}\n28۔ مکئی، شراب اور تیل کی پیداوار کے لیے بھی گودام؛ اور ہر قسم کے جانوروں کے لیے اصطبل اور ریوڑ کے لیے بستر تھے۔\n29۔ اس کے علاوہ اس نے اسے شہر، ریوڑ اور ریوڑ کی جائیداد بھی فراہم کی، کیونکہ خدا نے اسے بہت زیادہ مال دیا تھا۔\n30۔ اسی حزقیاہ نے گیہون کے بالائی پانی کے راستے کو بھی روک دیا، اور اسے سیدھا شہر داؤد کے مغربی کنارے پر لے آیا۔ اور حزقیاہ نے اپنے تمام کاموں میں کامیابی حاصل کی۔\n31۔ اگرچہ بابل کے شہزادوں کے سفیروں کے کام میں، جنہوں نے اس کے پاس بھیجا کہ وہ زمین میں ہونے والے عجائبات کے بارے میں پوچھیں، خدا نے اسے چھوڑ دیا، تاکہ وہ اسے آزمائے تاکہ وہ اپنے دل کی تمام باتیں جان سکے۔ {سفیر: عبرانی۔ مترجمین}\n32۔ اب حزقیاہ کے باقی اعمال اور اس کی نیکی، دیکھیں، وہ یسعیاہ نبی کے خواب میں لکھے گئے ہیں، جو عموز کا بیٹا ہے، {اور} یہوداہ اور اسرائیل کے بادشاہوں کی کتاب میں۔ {اچھا: عبرانی۔ مہربانی\n33۔ اور حزقیاہ نے اپنے باپ و اجداد کے ساتھ سونا شروع کیا، اور انہوں نے اسے داؤد کے بیٹوں کی سب سے بڑی قبر میں دفن کیا: اور تمام یہوداہ اور یروشلم کے باشندوں نے اس کی موت پر اس کی عزت کی۔ اور اس کے بیٹے منسی نے اس کی جگہ حکومت کی۔ {سردار: یا، سب سے اعلیٰ}","1۔ مناسی بارہ سال کا تھا جب اس نے حکومت شروع کی، اور یروشلم میں پچپن سال حکومت کی:\n2۔ بلکہ خداوند کی نظر میں جو کچھ بھی برا تھا، ویسے ہی جیسے کافروں کی گناہوں کی طرح تھا، جنہیں خداوند نے بنی اسرائیل کے سامنے نکال دیا تھا۔\n3۔ کیونکہ اس نے وہ بلند مقامات دوبارہ تعمیر کیے جو حزقیاہ نے اس کے والد نے توڑ دیے تھے، اور بعلیم کے لیے قربان گاہیں کھڑی کیں، باغات بنائیں، اور آسمان کے تمام لشکر کی عبادت کی اور ان کی خدمت کی۔ {اس نے بنایا...: عبرانی۔ وہ واپس آیا اور تعمیر کیا}\n4۔ اسی طرح اس نے خداوند کے گھر میں قربان گاہیں بنائیں، جن کے بارے میں خداوند نے فرمایا، یروشلم میں میرا نام ہمیشہ کے لیے ہوگا۔\n5۔ اور اس نے خداوند کے گھر کے دونوں صحنوں میں آسمان کے تمام لشکر کے لیے قربان گاہیں بنائیں۔\n6۔ اور اس نے اپنے بچوں کو ہنوم کے بیٹے کی وادی میں آگ سے گزارا: اس نے بھی اوقات کا مشاہدہ کیا، جادو کیا، جادوگری کی، ایک مانوس روح اور جادوگروں سے نمٹا: اس نے خداوند کے سامنے بہت برائی کی، تاکہ اسے غصہ دلائے۔\n7۔ اور اس نے خدا کے گھر میں ایک نقش شدہ مورتی رکھی، جو اس نے بنایا تھا، جس کے بارے میں خدا نے داؤد اور اس کے بیٹے سلیمان سے کہا تھا، اس گھر میں، اور یروشلم میں، جسے میں نے اسرائیل کے تمام قبائل سے پہلے چنا ہے، میں ہمیشہ کے لیے اپنا نام رکھوں گا:\n8۔ نہ میں اب اسرائیل کے قدموں کو اس زمین سے ہٹا دوں گا جو میں نے تمہارے آباؤ اجداد کے لیے مقرر کی ہے؛ تاکہ وہ وہ سب کچھ کریں جو میں نے انہیں حکم دیا ہے، پورے قانون، قوانین اور احکامات کے مطابق، موسیٰ کے ہاتھ سے۔\n9۔ یوں منسی نے یہوداہ اور یروشلم کے باشندوں کو غلطی پر مجبور کیا، {اور} ان کافروں سے بھی بدتر کیا، جنہیں خداوند نے بنی اسرائیل کے سامنے تباہ کر دیا تھا۔\n10۔ اور خداوند نے مناسی اور اس کے لوگوں سے بات کی: لیکن وہ سننے کو تیار نہ تھے۔\n11۔ چنانچہ خداوند نے ان پر آشور کے بادشاہ کی فوج کے کپتانوں کو لایا، جس نے منسی کو کانٹوں کے درمیان لے جایا، اسے زنجیروں میں باندھ کر بابل لے گیا۔ {بادشاہ کے بارے میں: عبرانی۔ جو بادشاہ کی تھیں} {زنجیریں: یا، زنجیریں}\n12۔ اور جب وہ مصیبت میں تھا، تو اس نے اپنے خدا خداوند سے دعا کی، اور اپنے باپ و اجداد کے خدا کے سامنے بہت عاجز ہوا،\n13۔ اور اس سے دعا کی، اور اس نے اس سے درخواست کی، اس کی دعا سنی اور اسے دوبارہ یروشلم لے آیا۔ پھر منسی کو معلوم ہوا کہ خداوند وہ خدا ہے۔\n14۔ اس کے بعد اس نے داؤد کے شہر کے بغیر، گیہون کے مغربی کنارے، وادی میں، مچھلی کے دروازے تک ایک دیوار بنائی، اوفیل کے گرد گھیر لیا، اور اسے بہت اونچا اٹھایا، اور یہوداہ کے تمام باڑ والے شہروں میں جنگی کپتان تعینات کیے۔ {اوفل: یا، مینار}\n15۔ اور اس نے عجیب دیوتاؤں کو، اور خدا کے گھر سے بت نکال دی، اور وہ تمام قربان گاہیں جو اس نے خداوند کے گھر کے پہاڑ اور یروشلم میں بنائی تھیں، اور انہیں شہر سے نکال دیا۔\n16۔ اور اس نے خداوند کے مذبح کی مرمت کی، اس پر صلح کی قربانیاں اور شکریہ کی قربانیاں کیں، اور یہوداہ کو حکم دیا کہ وہ اسرائیل کے خداوند خدا کی خدمت کرے۔\n17۔ اس کے باوجود لوگ اب بھی اونچی جگہوں پر قربانی دیتے رہے، {پھر بھی} صرف اپنے خدا خداوند کے لیے۔\n18۔ اب منسی کے باقی اعمال، اور اس کی دعا اپنے خدا کے لیے، اور دیکھنے والوں کے الفاظ جو اس سے خداوند خدا اسرائیل کے نام پر کہے گئے، دیکھو، یہ سب اسرائیل کے بادشاہوں کی کتاب میں لکھے گئے ہیں۔\n19۔ اس کی دعا بھی، اور {خدا کے ساتھ کیا سلوک ہوا}، اس کے تمام گناہ اور اس کے گناے، اور وہ جگہیں جہاں اس نے اونچی جگہیں بنائیں، اور جنگل اور کندہ شدہ مجسمے بنائیں، اس سے پہلے کہ وہ عاجز ہو: دیکھو، یہ سب پیش گوؤں کے اقوال میں لکھی گئی ہیں۔ {دیکھنے والے: یا، ہوسائی}\n20۔ تو مناسی اپنے باپ دادا کے ساتھ سو گیا، اور انہوں نے اسے اس کے اپنے گھر میں دفن کر دیا: اور اس کا بیٹا آمون اس کی جگہ بادشاہی کرنے لگا۔\n21۔ آمون {تھا} جب اس نے حکومت شروع کی تو وہ دو سال اور بیس سال کا تھا، اور یروشلم میں دو سال حکومت کی۔\n22. لیکن اس نے خداوند کی نظر میں جو برا تھا، جیسا کہ مناسی نے اپنے باپ نے کیا: کیونکہ آمون نے اپنے باپ کی بنائی ہوئی تمام مجسموں کے لیے قربانی دی اور ان کی خدمت کی؛\n23۔ اور خداوند کے سامنے خود کو عاجز نہیں کیا، جیسا کہ اس کے باپ مناسی نے خود کو عاجز کیا تھا؛ لیکن آمن نے زیادہ سے زیادہ غیر قانونی طور پر داخلہ لیا۔ {زیادہ سے زیادہ غیر قانونی طور پر داخل ہوا: عبرانی۔ تجاوزات کو بڑھا چڑھا کر}\n24۔ اور اس کے خادموں نے اس کے خلاف سازش کی اور اسے اس کے اپنے گھر میں قتل کر دیا۔\n25۔ لیکن اس سرزمین کے لوگوں نے ان سب کو مار ڈالا جنہوں نے بادشاہ آمون کے خلاف سازش کی تھی؛ اور اس ملک کے لوگوں نے یوشیا کو اس کی جگہ اپنا بیٹا بادشاہ بنایا۔","1۔ یوشیا آٹھ سال کا تھا جب اس نے حکومت شروع کی، اور یروشلم میں ایک اور تیس سال حکومت کی۔\n2۔ اور اس نے {جو تھا} وہ کیا جو خداوند کی نظر میں درست تھا، اور اپنے باپ داؤد کے راستوں پر چلتا رہا، اور نہ دائیں ہاتھ اور نہ بائیں طرف نہ ہاتھ سے انکار کیا۔\n3۔ کیونکہ اپنی حکومت کے آٹھویں سال میں، جب وہ ابھی جوان تھا، اس نے اپنے باپ داؤد کے خدا کی تلاش شروع کی: اور بارہویں سال اس نے یہوداہ اور یروشلم کو اونچی جگہوں، جھنڈوں، کندہ شدہ مجسموں، اور پگھلے ہوئے مجسموں سے پاک کرنا شروع کیا۔\n4۔ اور وہ اس کی موجودگی میں بعلیم کے قربان گاہوں کو توڑ دیتے ہیں؛ اور وہ تصاویر جو ان کے اوپر اوپر تھیں، اس نے کاٹ دیں؛ اور جھنڈ، کندہ شدہ مجسمے، اور پگھلے ہوئے مجسمے، اس نے ٹکڑوں میں توڑ دیا، ان سے خاک بنائی، اور ان کی قبروں پر قدم رکھا جنہوں نے ان کے لیے قربانی دی۔ {تصاویر: یا، سورج کی تصاویر} {گریوز: عبرانی۔ قبروں کا چہرہ}\n5۔ اور اس نے کاہنوں کی ہڈیاں ان کے مذبحوں پر جلا دیں، اور یہوداہ اور یروشلم کو پاک کیا۔\n6۔ اور {اسی طرح} نے منسیہ، افرائیم، اور شمعون کے شہروں میں، حتیٰ کہ نفتالی تک، ان کے مچھلیوں کے ساتھ بھی کیا۔ {میٹاکس: یا، مولز}\n7۔ اور جب اس نے قربان گاہیں اور باغات توڑ دیے، اور تراشے گئے مجسموں کو پاؤڈر میں بدل دیا، اور اسرائیل کی سرزمین کے تمام بتوں کو کاٹ دیا، تو وہ یروشلم واپس آیا۔ {میں...: عبرانی میں۔ پاؤڈر بنانے کے لیے}\n8۔ اب اپنی حکومت کے اٹھارہویں سال میں، جب اس نے زمین اور گھر کو صاف کر دیا، اس نے عزلیا کے بیٹے شافان کو، شہر کے گورنر ماسیہ، اور یوحاز ریکارڈر کے بیٹے جوح کو بھیجا تاکہ خداوند کے خدا کے گھر کی مرمت کی جا سکے۔\n9۔ اور جب وہ حلقیاہ سردار کاہن کے پاس پہنچے، تو انہوں نے خدا کے گھر میں لائے گئے پیسے پہنچائے، جو دروازے سنبھالنے والے لاویوں نے مناسی اور افرایم کے ہاتھ اور اسرائیل کے تمام باقیات اور یہوداہ اور بنیامین کے ہاتھ سے جمع کیا تھا؛ اور وہ یروشلم واپس آ گئے۔\n10۔ اور انہوں نے اسے ان مزدوروں کے ہاتھ میں دے دیا جو خداوند کے گھر کی نگرانی کرتے تھے، اور اسے ان مزدوروں کو دے دیا جو خداوند کے گھر میں کام کرتے تھے، تاکہ وہ گھر کی مرمت اور اصلاح کریں:\n11۔ حتیٰ کہ کاریگروں اور معماروں کو بھی یہ دیا گیا کہ وہ تراشے ہوئے پتھر اور جوڑوں کے لیے لکڑی خریدیں، اور یہوداہ کے بادشاہوں کے تباہ شدہ گھروں کو فرش پر رکھیں۔ {فرش پر: یا، چھت کی طرف}\n12۔ اور مردوں نے یہ کام وفاداری سے کیا: اور ان کے نگران جہات اور عوبدیا تھے، جو مراری کے بیٹوں کے لاوی تھے؛ اور زکریا اور مشولام، جو کوہتیوں کے بیٹوں سے تھے، نے اسے آگے بڑھایا؛ اور {دیگر} لاویوں میں، جو موسیقی کے آلات بجانے کی مہارت رکھتے تھے۔\n13۔ اسی طرح {وہ بوجھ اٹھانے والے} تھے، اور {تھے} ہر اس کام کے نگران جو کسی بھی قسم کی خدمت میں کام کرتا تھا؛ اور لاویوں میں {وہاں کاتب، افسر اور قلی تھے} تھے۔\n14۔ اور جب انہوں نے وہ رقم نکالی جو خداوند کے گھر میں لائی گئی تھی، تو حلقیاہ پادری نے موسیٰ کی طرف سے خداوند کے قانون کی ایک کتاب دیکھی۔ {بذریعہ: عبرانی ہاتھوں سے}\n15۔ اور حلقیاہ نے جواب دیا اور شافان کاتب سے کہا، میں نے خداوند کے گھر میں قانون کی کتاب پائی ہے۔ اور ہلکیاہ نے کتاب شافان کو دی۔\n16۔ اور شافان نے کتاب بادشاہ کے پاس لے گئی، اور بادشاہ کا پیغام واپس لایا، کہنے لگا، جو کچھ بھی تمہارے بندوں کے سپرد ہے، وہ کرے گا۔ {تمہارے...: عبرانی کے لیے۔ ہاتھ میں، وغیرہ}\n17۔ اور انہوں نے خداوند کے گھر میں ملنے والے پیسے کو اکٹھا کیا اور نگرانوں کے ہاتھ میں اور مزدوروں کے ہاتھ میں دے دیا۔ {اکٹھے ہوئے: عبرانی۔ نکال دیا گیا، یا پگھل گیا}\n18۔ پھر شفان کاتب نے بادشاہ سے کہا، کہنے پر، حلقیہ نے مجھے ایک کتاب دی ہے۔ اور شافان نے اسے بادشاہ کے سامنے پڑھا۔ {it: عبرانی اس میں}\n19۔ اور جب بادشاہ نے قانون کے الفاظ سنے، تو اس نے اپنے کپڑے پھاڑ دیے۔\n20۔ اور بادشاہ نے حلقیا، احیکم جو شافان کا بیٹا تھا، اور عبدون جو میکا کا بیٹا تھا، اور شافان کاتب اور عسیاہ کو بادشاہ کا خادم حکم دیا، اور کہا، {عدون: یا، اخبور}\n21۔ جاؤ، خداوند سے میرے لیے اور اسرائیل اور یہوداہ میں باقی رہ جانے والوں کے لیے اس کتاب کے الفاظ کے بارے میں پوچھو: کیونکہ خداوند کا غضب جو ہم پر نازل ہوا ہے، بہت بڑا ہے، کیونکہ ہمارے آباؤ اجداد نے خداوند کے کلام کو پورا نہیں کیا، جو اس کتاب میں لکھی تمام باتوں کے بعد کرنی چاہیے۔\n22۔ اور حلقیا، اور وہ جنہیں بادشاہ نے مقرر کیا تھا، ہلدہ کے پاس گئے، نبی خاتون، شلوم، ٹکوات کے بیٹے کی بیوی، حسرہ کا بیٹا، جو الماری کا رکھوالا تھا؛ (اب وہ یروشلم میں کالج میں رہتی تھی :) اور انہوں نے اس سے اسی طرح بات کی۔ {حسرہ: جسے ہرہاس بھی کہا جاتا ہے} {وارڈروب: عبوری۔ کپڑے} {کالج میں: یا، اسکول میں، یا دوسرے حصے میں}\n23۔ اور اس نے ان کا جواب دیا، یوں ہی اسرائیل کے خداوند خدا نے فرمایا، اس آدمی کو بتاؤ جس نے تمہیں میرے پاس بھیجا،\n24۔ خداوند یوں فرماتا ہے، دیکھو، میں اس جگہ اور اس کے باشندوں پر برائی لاؤں گا، {حتیٰ کہ} وہ تمام لعنتیں جو انہوں نے یہوداہ کے بادشاہ کے سامنے کتاب میں پڑھی ہیں:\n25۔ کیونکہ انہوں نے مجھے چھوڑ دیا ہے، اور دوسرے دیوتاؤں کے سامنے دھوئیں جلا دی ہیں، تاکہ وہ اپنے تمام کاموں سے مجھے غصہ دلا سکیں؛ لہٰذا میرا غضب اس جگہ پر بہہ جائے گا، اور بجھا نہیں جائے گا۔\n26۔ اور جہاں تک یہوداہ کے بادشاہ کا تعلق ہے، جس نے تمہیں خداوند سے پوچھنے بھیجا ہے، تو تم اس سے کہو گے، یہی فرماتا ہے اسرائیل کا خداوند خدا {ان الفاظ کے بارے میں} جو تم نے سنے؛\n27۔ کیونکہ تمہارا دل نرم تھا، اور تم نے خدا کے سامنے عاجز ہو گئے، جب تم نے اس جگہ اور اس کے باشندوں کے خلاف اس کے الفاظ سنے، اور میرے سامنے خود کو عاجز کیا، اپنے کپڑے پھاڑے، اور میرے سامنے رویا؛ میں نے تو یہ بھی سنا ہے {تم}، خداوند فرماتا ہے۔\n28۔ دیکھو، میں تمہیں تمہارے آباؤ اجداد کے پاس لے آؤں گا، اور تمہیں سکون سے قبر پر لایا جائے گا، نہ ہی تمہاری آنکھیں وہ تمام برائی دیکھیں گی جو میں اس جگہ اور اس کے باشندوں پر لاؤں گا۔ تو انہوں نے دوبارہ بادشاہ کا حکم دیا۔\n29۔ پھر بادشاہ نے یہوداہ اور یروشلم کے تمام بزرگوں کو بھیجا اور جمع کیا۔\n30۔ اور بادشاہ خداوند کے گھر میں چلا گیا، یہوداہ کے تمام لوگ، یروشلم کے باشندے، کاہن، لاوی لوگ، اور تمام لوگ، بڑے اور چھوٹے، اور اس نے ان کے کانوں میں عہد نامہ کی کتاب کے تمام الفاظ پڑھے جو خداوند کے گھر میں پایا تھا۔ {زبردست...: عبرانی۔ عظیم سے چھوٹے تک}\n31۔ اور بادشاہ اپنی جگہ کھڑا ہوا، اور خداوند کے سامنے عہد کیا کہ خداوند کے پیچھے چلے گا، اور اپنے احکامات، گواہیوں اور قوانین کو پورے دل اور جان سے نبھائے، کہ اس کتاب میں لکھے گئے عہد کے الفاظ کو پورا کرے گا۔\n32۔ اور اس نے یروشلم اور بنیامین میں موجود سب کو کھڑا کر دیا۔ اور یروشلم کے باشندوں نے خدا کے عہد کے مطابق کیا، جو ان کے آباؤ اجداد کا خدا تھا۔ {موجود: عبرانی مل گیا}\n33۔ اور یوشیا نے ان تمام ملکوں سے تمام گناہوں کو ختم کر دیا جو بنی اسرائیل سے متعلق تھیں، اور اسرائیل میں موجود سب کو خدمت کے لیے مقرر کیا، یہاں تک کہ خداوند اپنے خدا کی عبادت کے لیے بھی۔ {اور} اس کے تمام دنوں میں وہ خداوند کی پیروی کرنے سے نہیں ہٹے، جو ان کے باپ و اجداد کا خدا ہے۔ {موجود: عبرانی مل گیا} {سے...: عبرانی۔ اس کے بعد سے}","1۔ مزید برآں، یوشیا نے یروشلم میں خداوند کے پاس پاس منایا: اور انہوں نے پہلے مہینے کی چودہویں (دن) کو فسح کا جشن منوایا۔\n2۔ اور اس نے کاہنوں کو ان کی ذمہ داریوں میں مقرر کیا، اور انہیں خداوند کے گھر کی خدمت کی طرف راغب کیا،\n3۔ اور ان لاویوں سے کہا جنہوں نے تمام اسرائیل کو سکھایا، جو خداوند کے لیے مقدس تھے، مقدس صندوق اس گھر میں رکھو جو سلیمان، داؤد کے بیٹے اسرائیل نے بنایا تھا؛ {یہ {تمہارے} کندھوں پر بوجھ نہیں ہوگا: اب خداوند اپنے خدا اور اس کے قوم اسرائیل کی عبادت کرو،\n4۔ اور اپنے آباؤ اجداد کے گھروں کے پاس، اپنے کورس کے بعد، اسرائیل کے بادشاہ داؤد کی تحریر کے مطابق، اور اس کے بیٹے سلیمان کی تحریر کے مطابق تیار ہو جاؤ۔\n5۔ اور اپنے بھائیوں کے باپوں کے خاندانوں کی تقسیم کے مطابق مقدس جگہ پر کھڑے ہو جاؤ، اور لاویوں کے خاندانوں کی تقسیم کے بعد۔ {باپوں کے خاندان: عبرانی۔ فادرز کا گھر} {لوگ: عبرانی۔ عوام کے بیٹے}\n6۔ تو فسح کو قتل کرو، اپنے آپ کو پاک کرو، اور اپنے بھائیوں کو تیار کرو، تاکہ وہ موسیٰ کے ہاتھ سے خداوند کے کلام کے مطابق عمل کریں۔\n7۔ اور یوشیا نے لوگوں کو، ریوڑ کے، بھیڑ اور بچے دیے، سب فسح کی قربانیوں کے لیے، سب موجود سب کے لیے، تیس ہزار اور تین ہزار بیلوں تک: یہ سب بادشاہ کی دولت سے تھے۔ {دیا گیا: عبوری۔ پیش کیا گیا}\n8۔ اور اس کے شہزادوں نے خوش دلی سے لوگوں، کاہنوں اور لاویوں کو دیے: حلقیا، زکریا اور یہیئیل، خدا کے گھر کے حکمران، نے پادریوں کو فسح کی قربانی کے طور پر دو ہزار چھ سو [چھوٹے مویشی] اور تین سو بیل دیے۔ {رضاکارانہ طور پر دیا گیا: عبرانی۔ پیش کیا گیا، وغیرہ}\n9۔ کنانیاہ نے بھی، شمعیاہ اور نیتھنیئل، اس کے بھائیوں، اور حشبیا، جیئیل اور یوزآباد، جو لاویوں کے سردار تھے، لاویوں کو پانچ ہزار [چھوٹے مویشی] اور پانچ سو بیل دیے۔ {دیا گیا: عبوری۔ پیش کیا گیا}\n10۔ تو خدمت کی تیاری کی گئی، اور کاہنوں نے اپنی جگہ کھڑی ہو گئی، اور لاوی بادشاہ کے حکم کے مطابق اپنے راستے میں تھے۔\n11۔ اور انہوں نے عید فصح کو قتل کر دیا، اور کاهنوں نے ان کے ہاتھوں سے خون چھڑک دیا، اور لاویوں نے ان کے چھال اتار دیے۔\n12۔ اور انہوں نے جلانے والے نذرے ہٹا دیے تاکہ وہ لوگوں کے خاندانوں کی تقسیم کے مطابق خداوند کو پیش کر سکیں، جیسا کہ موسیٰ کی کتاب میں لکھا ہے۔ اور انہوں نے بھی، بیلوں کے ساتھ بھی۔\n13۔ اور انہوں نے عید فسح کو آگ سے روسٹ کیا، لیکن باقی مقدس نذرانے کو برتنوں، دیگچیوں اور برتنوں میں ڈال دیا گیا، اور جلدی سے سب لوگوں میں تقسیم کر دیا۔ {تقسیم شدہ...: عبرانی انہیں بھاگنے پر مجبور کیا}\n14۔ اور اس کے بعد انہوں نے اپنے لیے اور کاہنوں کے لیے تیاری کی، کیونکہ کاہن، ہارون کے بیٹے {رات تک} جلانے والے قربانیاں اور چربی پیش کرنے میں مصروف تھے؛ لہٰذا لاویوں نے اپنے لیے اور کاہنوں کے لیے ہارون کے بیٹوں کی تیاری کی۔\n15۔ اور گانے والے جو آساف کے بیٹے تھے، ان کی جگہ داؤد، عصاف، ہیمان، اور بادشاہ کے پیش گو کے حکم کے مطابق تھے؛ اور قلی ہر دروازے پر انتظار کر رہے تھے؛ وہ اپنی خدمت سے رخصت نہیں ہو سکتے؛ اپنے بھائیوں کے لیے لاویوں نے ان کے لیے تیاری کی۔ {جگہ: عبرانی۔ اسٹیشن}\n16۔ تو خداوند کی تمام خدمات اسی دن تیار کی گئیں، تاکہ فسح منایا جائے، اور بادشاہ یوشیا کے حکم کے مطابق خداوند کے قربان گاہ پر نذرانہ پیش کیا جائے۔\n17۔ اور بنی اسرائیل نے جو وہاں موجود تھے، اس وقت پاس اوور اور سات دن بغیر خمیر کی روٹی کی عید منایا۔ {موجود: عبرانی مل گیا}\n18۔ اور اسرائیل میں سموئیل نبی کے زمانے جیسا کوئی پاس نہیں تھا؛ نہ ہی اسرائیل کے تمام بادشاہوں نے وہ فسح منایا جو یوشیا نے منایا، اور نہ ہی کاہن، اور لاوی، اور تمام یہوداہ اور اسرائیل جو موجود تھے، اور یروشلم کے باشندے۔ {موجود: عبرانی مل گیا}\n19۔ یوسیاہ کی حکومت کے اٹھارہویں سال میں یہ فسح منایا جاتا تھا۔\n20۔ ان سب کے بعد، جب یوشیا نے مندر تیار کیا، مصر کا بادشاہ نکو فرات کے پاس کارکیمش کے خلاف لڑنے آیا: اور یوشیا اس کے خلاف نکل پڑا۔ {مندر: عبرانی۔ گھر}\n21۔ لیکن اس نے اس کے پاس سفیر بھیجے اور کہا، اے یہوداہ کے بادشاہ، میرا تم سے کیا لینا دینا ہے؟ {میں آج تمہارے خلاف نہیں آ رہا، بلکہ اس گھر کے خلاف جس کے ساتھ میں جنگ کر رہا ہوں: کیونکہ خدا نے مجھے جلدی کرنے کا حکم دیا ہے: خدا کے ساتھ مداخلت سے باز رہو، جو {میرے ساتھ} ہے، کہ وہ تمہیں تباہ نہ کرے۔ {گھر...: عبرانی۔ میری جنگ کا گھر}\n22۔ پھر بھی یوشیا نے اس سے منہ نہیں موڑا، بلکہ خود کو چھپا لیا تاکہ وہ اس کے ساتھ لڑ سکے، اور خدا کے منہ سے نیکو کے الفاظ کو نہیں سنا اور مگیدو کی وادی میں لڑنے آیا۔\n23۔ اور تیر اندازوں نے بادشاہ یوشیا پر گولیاں چلائی؛ اور بادشاہ نے اپنے خادموں سے کہا، مجھے لے جاؤ؛ کیونکہ میں شدید زخمی ہوں۔ {زخمی: عبرانی۔ بیمار ہو گیا}\n24۔ اس کے خادموں نے اسے اس رتھ سے نکالا اور دوسری رتھ میں بٹھا دیا؛ اور انہیں یروشلم لے گئے، اور وہ فوت ہو گیا، اور اپنے باپ و اجداد کی قبروں میں سے ایک میں دفن کیا گیا۔ اور تمام یہوداہ اور یروشلم نے یوشیا کے لیے سوگ منایا۔ {ایک میں...: یا، قبروں کے درمیان}\n25۔ اور یرمیاہ نے یوشیا کے لیے ماتم کی: اور آج تک تمام گانے والے مرد اور گانے والی عورتیں اپنی نوحیوں میں یوشیا کے بارے میں بات کرتے ہیں، اور انہیں اسرائیل میں ایک رسم بنایا: اور دیکھو، وہ نوحیوں میں لکھے گئے ہیں۔\n26۔ اب یوشیا کے باقی اعمال اور اس کی نیکی، جو خداوند کے قانون میں لکھی گئی {نیکی} کے مطابق ہے، {نیکی: عبرانی۔ مہربانی\n27۔ اور اس کے اعمال، پہلے اور آخری، دیکھو، وہ اسرائیل اور یہوداہ کے بادشاہوں کی کتاب میں لکھے گئے ہیں۔","1۔ پھر اس ملک کے لوگوں نے یہوآہز، یوسیاہ کے بیٹے، کو لے کر یروشلم میں اس کے والد کی جگہ بادشاہ بنایا۔\n2. یہوآہاز جب حکومت شروع کی تو اس کی عمر تیئس سال تھی، اور اس نے یروشلم میں تین ماہ حکومت کی۔\n3۔ اور مصر کے بادشاہ نے اسے یروشلم میں اتارا، اور اس زمین کو سو ٹیلنٹ چاندی اور ایک ٹیلنٹ سونے میں ملامت کر دی۔ {put...: عبدی۔ اسے ہٹا دیا}\n4۔ اور مصر کے بادشاہ نے الیاقیم کو اپنا بھائی یہوداہ اور یروشلم کا بادشاہ بنایا، اور اس کا نام یہویاقیم رکھ دیا۔ اور نیکو نے اپنے بھائی یہوآہاز کو لے کر مصر لے گیا۔\n5. یہویاکیم بیس پچیس سال کا تھا جب اس نے حکومت شروع کی، اور اس نے یروشلم میں گیارہ سال حکومت کی: اور اس نے خداوند اپنے خدا کی نظر میں برا کیا۔\n6۔ اس کے خلاف بابل کے بادشاہ نبوکدنضر آیا، اور اسے زنجیروں میں باندھ کر بابل لے گیا۔ {زنجیریں: یا، زنجیریں}\n7۔ نبوکدنضر نے خداوند کے گھر کے برتن بھی بابل لے جا کر بابل میں اپنے مندر میں رکھ دیے۔\n8۔ اب یہویاقیم کے باقی اعمال اور اس کے گناہ جو اس نے کیے، اور جو کچھ اس میں پایا گیا، دیکھو، یہ سب اسرائیل اور یہوداہ کے بادشاہوں کی کتاب میں لکھے گئے ہیں: اور اس کا بیٹا یہویاکین اس کی جگہ حکومت کرتا رہا۔ {یہویاچن: جسے جیکونیاہ یا کونیاہ بھی کہا جاتا ہے}\n9۔ یہویاکین آٹھ سال کا تھا جب اس نے حکومت شروع کی، اور اس نے یروشلم میں تین ماہ اور دس دن حکومت کی: اور اس نے خداوند کی نظر میں برا کیا۔\n10۔ اور جب سال ختم ہوا، بادشاہ نبوکدنضر نے بھیجا اور اسے بابل لے آیا، خداوند کے گھر کے نیک برتنوں کے ساتھ، اور زدیقیاہ کو اپنا بھائی یہوداہ اور یروشلم کا بادشاہ بنایا۔ {جب...: عبرانی۔ سال کی واپسی پر} {اچھا...: عبرانی۔ خواہش کے برتن} {صدقیا...: یا، متانیا، اس کے والد کا بھائی}\n11۔ صدقیہ {بیس سال کا} تھا جب اس نے حکومت شروع کی، اور یروشلم میں گیارہ سال حکومت کی۔\n12۔ اور اس نے خداوند اپنے خدا کی نظر میں جو برا تھا، وہ کیا جو برا تھا، اور یرمیاہ نبی کے سامنے خود کو عاجز نہیں کیا، جو خداوند کے منہ سے بولتا ہے۔\n13۔ اور اس نے بادشاہ نبوکدنضر کے خلاف بھی بغاوت کی، جس نے اسے خدا کی قسم دی تھی، لیکن اس نے اپنی گردن سخت کر لی اور اپنے دل کو اسرائیل کے خداوند خدا کی طرف رجوع کرنے سے روک دیا۔\n14۔ مزید برآں، تمام سردار کاہنوں اور عوام نے کافروں کی تمام گناہوں کے بعد بہت زیادتی کی؛ اور خداوند کے گھر کو آلودہ کیا جسے اس نے یروشلم میں مقدس قرار دیا تھا۔\n15۔ اور ان کے باپ اجداد کے خداوند خدا نے اپنے رسولوں کے ذریعے ان کے پاس بھیجا، جو صبح اٹھ کر بھیجتا ہے؛ کیونکہ اس نے اپنے لوگوں اور اپنے گھر پر رحم کیا: {بذریعہ: عبرانی۔ {betimes: یعنی مسلسل اور احتیاط سے} کے ہاتھوں سے}\n16۔ لیکن انہوں نے خدا کے رسولوں کا مذاق اڑایا، اس کے الفاظ کو حقیر سمجھا، اور اس کے نبیوں کا غلط استعمال کیا، یہاں تک کہ خداوند کا غضب اس کے لوگوں پر اٹھا، یہاں تک کہ کوئی علاج نہ رہا۔ {علاج: عبرانی۔ شفا پانا}\n17۔ اس لیے اس نے کلدیوں کے بادشاہ کو ان پر لایا، جس نے ان کے نوجوانوں کو ان کے مقدس گھر میں تلوار سے قتل کیا، اور نہ جوان، نہ لڑکی، نہ بوڑھے آدمی، نہ بوڑھے پر رحم کیا، نہ ہی اس پر جو بوڑھا ہو گیا تھا: اس نے سب کچھ اپنے ہاتھ میں دے دیا۔\n18۔ اور خدا کے گھر کے تمام برتن، بڑے اور چھوٹے، اور خداوند کے گھرانے کے خزانے، اور بادشاہ اور اس کے شہزادوں کے خزانے؛ یہ سب {یہ} وہ بابل لے کر آیا۔\n19۔ اور انہوں نے خدا کے گھر کو جلا دیا، یروشلم کی دیوار توڑ دی، اس کے تمام محلات آگ سے جلا دیے، اور اس کے تمام نیک برتن تباہ کر دیے۔\n20۔ اور جو تلوار سے بچ نکلے تھے، وہ بابل لے گئے؛ جہاں وہ اس کے اور اس کے بیٹوں کے خادم تھے جب تک کہ ایران کی بادشاہت نہ آئی: {وہ...: عبرانی۔ باقی تلوار سے}\n21. خداوند کے کلام کو یرمیاہ کے منہ سے پورا کرنا، جب تک کہ زمین اپنی سبت سے لطف اندوز نہ ہو جائے: {کیونکہ} جب تک وہ ویران رہی، اس نے سبت رکھی، تین سو سال پورے کرنے کے لیے۔\n22. اب فارس کے بادشاہ سائرس کے پہلے سال میں، تاکہ خداوند کا کلام یرمیاہ کے منہ سے مکمل ہو جائے، خداوند نے فارس کے بادشاہ سائرس کی روح کو جگایا، کہ اس نے اپنی پوری سلطنت میں اعلان کیا، اور اسے بھی تحریری طور پر کہا،\n23. یوں فارسی بادشاہ سائرس فرماتا ہے، زمین کی تمام بادشاہتیں آسمان کے خداوند خدا نے مجھے عطا کی ہیں؛ اور اس نے مجھے حکم دیا ہے کہ میں یروشلم میں اس کے لیے ایک گھر بناؤں، جو یہوداہ میں واقع ہے۔ آپ میں سے اس کے تمام لوگوں میں سے کون ہے؟ خداوند اس کا خدا اس کے ساتھ رہے، اور اسے اوپر جانے دے۔"];
